// ── IMAGE MODERATION ─────────────────────────────────────────
async function _moderateImage(dataUrl){
  try{
    var base64 = (dataUrl||'').split(',')[1];
    if(!base64) return {safe:true};
    var mime = (dataUrl.match(/^data:([^;]+);/)||[])[1] || 'image/jpeg';
    var res = await fetch(GEMINI_PROXY, {
      method:'POST', cache:'no-store',
      headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ type:'vision', image:base64, mimeType:mime,
        prompt:'¿Esta imagen contiene desnudez, contenido sexual explícito, pornografía u otro contenido inapropiado para una app de bienestar emocional? Respondé SOLO con una línea: "safe" o "unsafe: <motivo breve en español>".' })
    });
    if(!res.ok) return {safe:true};
    var data = await res.json();
    var parts = ((data.candidates||[])[0]||{});
    parts = ((parts.content||{}).parts||[]);
    var text = ((parts.find(function(p){ return !p.thought && p.text; })||{}).text||'').toLowerCase().trim();
    if(text.startsWith('unsafe')){
      var reason = text.replace(/^unsafe\s*:\s*/,'').trim() || 'contenido no permitido';
      return {safe:false, reason:reason};
    }
    return {safe:true};
  }catch(e){ return {safe:true}; }
}

async function _sendContentWarning(userId, reason){
  _initSupabase();
  if(!sbClient || !userId) return;
  try{
    await sbClient.from('broadcasts').insert({
      target: 'user:'+userId,
      subject: '⚠️ Imagen bloqueada — Advertencia de Velo',
      body: 'Tu imagen fue bloqueada automáticamente por nuestro sistema de moderación porque contiene: '+reason+'.\n\nRecordá que Velo es un espacio seguro y respetuoso. El incumplimiento reiterado puede resultar en la suspensión de tu cuenta.\n\n¿Creés que fue un error? Escribinos a consultas@heyvelo.app 💚',
      icon: '⚠️',
      sender: JSON.stringify({n:'Velo',i:'velo-system',a:'⚠️'}),
      sent_at: new Date().toISOString()
    });
  }catch(e){}
}

async function _geminiCallGrounded(prompt, cfg){
  // Try Vercel serverless proxy first, fall back to direct call
  var sources = [
    function(){ return fetch(GEMINI_PROXY, { method:'POST', cache:'no-store', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ type:'grounded', prompt:prompt, cfg:Object.assign({ temperature:0.9 }, cfg||{}) }) }); },
    function(){ return fetch(GEMINI_URLS[0] + GEMINI_KEY, { method:'POST', cache:'no-store', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ contents:[{ parts:[{ text:prompt }] }], tools:[{ google_search:{} }],
        generationConfig: Object.assign({ temperature:0.9, maxOutputTokens:1500 }, cfg||{}) }) }); }
  ];
  for(var i=0; i<sources.length; i++){
    try{
      var res = await sources[i]();
      if(!res.ok && i===0){ continue; }
      var json = await res.json();
      if(json.candidates && json.candidates[0]){
        var cand = json.candidates[0];
        var text = (cand.content && cand.content.parts && cand.content.parts[0]) ? cand.content.parts[0].text : null;
        var chunks = (cand.groundingMetadata && cand.groundingMetadata.groundingChunks) || [];
        var urls = chunks.map(function(c){ return c.web || null; }).filter(Boolean);
        return { text: text, urls: urls };
      }
    }catch(e){ continue; }
  }
  return { text: null, urls: [] };
}

// Extract text from Gemini-or-Groq-shaped response object
function _gText(json){
  try{
    var c = (json||{}).candidates;
    if(!c||!c[0]) return null;
    var p = ((c[0].content)||{}).parts;
    return (p&&p[0]&&typeof p[0].text==='string'&&p[0].text.trim()) ? p[0].text.trim() : null;
  }catch(e){ return null; }
}

async function _geminiCall(prompt, cfg){
  // 1. Gemini proxy
  try{
    var pr = await fetch(GEMINI_PROXY, { method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ prompt:prompt, cfg:cfg||{} }) });
    if(pr.ok){ var t1 = _gText(await pr.json()); if(t1) return t1; }
    else { var e1={}; try{e1=await pr.json();}catch(x){} console.warn('[Velo] Gemini proxy',pr.status, e1.error||''); }
  }catch(e){ console.warn('[Velo] Gemini proxy fetch error:', e.message); }
  // 2. Groq proxy fallback (Llama 3.3-70b — returns Gemini-compatible shape)
  try{
    var gr = await fetch(GROQ_PROXY, { method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ prompt:prompt, cfg:cfg||{} }) });
    if(gr.ok){ var t2 = _gText(await gr.json()); if(t2) return t2; }
  }catch(e){}
  // 3. Direct Gemini API (requires client-side key — likely empty in production)
  for(var attempt = 0; attempt < GEMINI_URLS.length; attempt++){
    var url = GEMINI_URLS[(_geminiUrlIdx + attempt) % GEMINI_URLS.length];
    try{
      var res = await fetch(url + GEMINI_KEY, {
        method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ contents:[{parts:[{text:prompt}]}],
          generationConfig: Object.assign({temperature:0.7,maxOutputTokens:300},cfg||{}) })
      });
      var t3 = _gText(await res.json());
      if(t3){ _geminiUrlIdx = (_geminiUrlIdx+attempt)%GEMINI_URLS.length; return t3; }
    }catch(e){ continue; }
  }
  return null;
}

