// ── TOAST ───────────────────────────────────────────────────
var _toastTimer = null;
var _toastQueue = [];
var _toastBusy  = false;

function pToast(emoji, msg){
  var last = _toastQueue[_toastQueue.length-1];
  if(last && last.emoji === (emoji||'✓') && last.msg === (msg||'')) return;
  _toastQueue.push({ emoji: emoji || '✓', msg: msg || '' });
  if(!_toastBusy) _nextToast();
}

function _nextToast(){
  if(!_toastQueue.length){ _toastBusy = false; return; }
  _toastBusy = true;
  var item = _toastQueue.shift();
  var el = document.getElementById('pToast');
  var em = document.getElementById('pToastEmoji');
  var tx = document.getElementById('pToastMsg');
  if(!el){ _toastBusy = false; return; }
  if(em) em.textContent = item.emoji;
  if(tx) tx.textContent = item.msg;
  el.classList.add('show');
  clearTimeout(_toastTimer);
  _toastTimer = setTimeout(function(){
    el.classList.remove('show');
    setTimeout(_nextToast, 300);
  }, 2000);
}
// Alias for compatibility
var toast = pToast;

// ── NAVIGATION STATE ─────────────────────────────────────────
var _curPage    = 'landing';
var _prevPage   = 'landing';
var _navToken   = 0; // incremented on every pGoTo — lets async renders bail if page changed
var _authenticated = false;
var _userType   = 'user'; // 'user' | 'pro' | 'admin'

var P_NO_NAV = ['landing','login','register','register-type','onboarding',
                'pro-reg','pro-onboarding','admin-login','admin','pro-pending','verify-email','pick-username',
                'dm-chat'];
var P_DARK   = ['help','bottle','respira'];
var P_FADE   = ['landing','onboarding','register-type','donation-exit',
                'session-room','post-chat','donate-cta','pro-pending','admin-login','calm-ai','guardian-chat','verify-email','pick-username'];

// ── NAVIGATE ─────────────────────────────────────────────────
function _trackPageView(id){
  try{
    var key = 'velo_page_views';
    var data = {}; try{ data = JSON.parse(safeLS('get', key)||'{}'); }catch(e){}
    data[id] = (data[id]||0) + 1;
    data.__total = (data.__total||0) + 1;
    data.__lastSeen = Date.now();
    safeLS('set', key, JSON.stringify(data));
    // Also fire Vercel Analytics custom event if available
    if(window.va) window.va('event', { name: 'page_view', properties: { page: id } });
  }catch(e){}
}

// Screens that should NOT be saved for reload-restore (auth flows, active chats, sensitive)
var _NO_RESTORE = ['landing','login','register','register-type','onboarding','pro-reg',
  'pro-onboarding','admin-login','admin','pro-pending','verify-email','pick-username',
  'change-password','guardian-chat','help-chat','session-room','post-chat','donate-cta'];

function pGoTo(id){
  if(!id) return;
  var inPage = document.getElementById('pg-'+id);
  if(!inPage){ console.warn('[Premium] page not found: pg-'+id); return; }

  // Admin sessions must stay in the admin panel — never cross into user-facing pages
  if(safeLS('get','velo_admin_session') === '1' && ['admin','admin-login','landing'].indexOf(id) < 0){
    id = 'admin';
    inPage = document.getElementById('pg-admin');
    if(!inPage) return;
  }

  // Save scroll of page we're leaving so goBack() can restore it
  var _outEl = document.getElementById('pg-'+_curPage);
  var _outSc = _outEl && _outEl.querySelector('.p-page-scroll');
  if(_outSc && _curPage !== id) _scrollSave[_curPage] = _outSc.scrollTop;

  // Deactivate current
  var outPage = document.getElementById('pg-'+_curPage);
  if(outPage){ outPage.classList.remove('active','fade-in'); }

  if(_curPage !== id) _prevPage = _curPage;
  _curPage = id;
  _navToken++;
  document.body.classList.toggle('is-landing', id === 'landing');

  // Remember where the user is so a browser refresh restores this screen
  if(_authenticated && _NO_RESTORE.indexOf(id) < 0){
    try{ sessionStorage.setItem('velo_last_screen', id); }catch(e){}
  }

  // Activate new page
  inPage.classList.add('active');
  if(P_FADE.indexOf(id) >= 0) inPage.classList.add('fade-in');

  // Scroll to top
  var scroll = inPage.querySelector('.p-page-scroll');
  if(scroll) scroll.scrollTop = 0;

  // Update nav active states
  var showNav = P_NO_NAV.indexOf(id) < 0 && _authenticated;
  _updateNavState(id, showNav);

  // Hide ambient player bar on chat pages so it doesn't cover the input field
  var _chatHidePages = ['circle-chat','help-chat','dm','dm-chat','guardian-chat','feed','post-chat'];
  var _ambBar = document.getElementById('ambientPlayerBar');
  if(_ambBar){
    if(_chatHidePages.indexOf(id) >= 0){
      _ambBar.dataset.hiddenForChat = '1';
      _ambBar.style.display = 'none';
    } else {
      if(_ambBar.dataset.hiddenForChat){
        delete _ambBar.dataset.hiddenForChat;
        if(_ambActive) _ambBar.style.display = 'flex';
      }
    }
  }

  // Show/hide "return to chat" badge when navigating away from an active chat
  var _activeChatPages = ['help-chat', 'guardian-chat', 'dm-chat'];
  if(_inActiveChat && _activeChatPages.indexOf(id) < 0 && _activeChatPages.indexOf(_prevPage) >= 0){
    _showReturnToChatBadge(_prevPage);
  } else if(_activeChatPages.indexOf(id) >= 0){
    _hideReturnToChatBadge();
  }

  // Update URL hash for deep-linking / bookmarkable sections
  if(_authenticated && _NO_RESTORE.indexOf(id) < 0){
    try{ history.replaceState(null,'','#'+id); }catch(e){}
  } else if(location.hash && P_NO_NAV.indexOf(id) >= 0){
    try{ history.replaceState(null,'',location.pathname+location.search); }catch(e){}
  }

  // Per-page init
  _onPageEnter(id);
  _trackPageView(id);
}

function _showReturnToChatBadge(pageId){
  var existing = document.getElementById('returnChatBadge');
  if(existing){ existing.dataset.page = pageId; return; }
  var badge = document.createElement('div');
  badge.id = 'returnChatBadge';
  badge.dataset.page = pageId;
  badge.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;max-width:700px;margin:0 auto">'
    +'<span style="display:flex;align-items:center;gap:8px;font-size:14px"><span style="font-size:18px">💬</span><span>Tenés un chat activo</span></span>'
    +'<button onclick="pGoTo(document.getElementById(\'returnChatBadge\').dataset.page)" style="background:rgba(255,255,255,.25);border:1.5px solid rgba(255,255,255,.5);border-radius:20px;color:#fff;padding:6px 16px;font-size:15px;font-weight:700;cursor:pointer;font-family:\'Jost\',sans-serif;white-space:nowrap">Volver →</button>'
    +'</div>';
  badge.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:9999;background:linear-gradient(90deg,#1b6636,#25a86a);color:#fff;padding:10px 16px;font-weight:600;font-family:\'Jost\',sans-serif;box-shadow:0 2px 12px rgba(0,0,0,.25);cursor:pointer;';
  badge.onclick = function(e){ if(e.target===badge||e.target.tagName==='SPAN') pGoTo(this.dataset.page); };
  document.body.appendChild(badge);
}
function _hideReturnToChatBadge(){
  var b = document.getElementById('returnChatBadge');
  if(b) b.remove();
}

function _updateNavState(id, showNav){
  // Sidebar
  var sidebar = document.getElementById('pSidebar');
  var topbar  = document.getElementById('pTopbar');
  var bottomnav = document.getElementById('pBottomnav');

  if(sidebar) sidebar.style.display = showNav ? '' : 'none';
  if(topbar)  topbar.style.display  = showNav ? '' : 'none';
  if(bottomnav) bottomnav.style.display = showNav ? '' : 'none';

  // Sidebar items
  document.querySelectorAll('.p-sn-item').forEach(function(item){
    item.classList.toggle('active', item.dataset.screen === id);
  });
  // Bottom nav items
  document.querySelectorAll('.p-bn-item').forEach(function(item){
    item.classList.toggle('active', item.dataset.screen === id);
  });
}

function goBack(){
  if(!_prevPage) return;
  var _tgt = _prevPage;
  var _pos = _scrollSave[_tgt] || 0;
  pGoTo(_tgt);
  if(_pos){
    requestAnimationFrame(function(){
      var _pg = document.getElementById('pg-'+_tgt);
      var _sc = _pg && _pg.querySelector('.p-page-scroll');
      if(_sc) _sc.scrollTop = _pos;
    });
  }
}

// ── MOBILE MENU ──────────────────────────────────────────────
function toggleMobileMenu(){
  var menu = document.getElementById('pMobileMenu');
  if(!menu) return;
  if(menu.classList.contains('open')){
    menu.classList.remove('open');
  } else {
    // Update Estilo label to reflect current mode before opening
    var lbl = document.getElementById('mobileEstiloLbl');
    var icon = document.getElementById('mobileEstiloBtn');
    var isDark = document.body.classList.contains('r-dark');
    if(lbl) lbl.textContent = isDark ? 'Modo claro (Estilo)' : 'Modo oscuro (Estilo)';
    if(icon) icon.querySelector('.p-mobile-nav-icon').textContent = isDark ? '☀️' : '🌙';
    menu.classList.add('open');
  }
}

// ── MODAL HELPERS ─────────────────────────────────────────────
function _syncBodyScroll(){
  var hasOpen = document.querySelector('.p-modal-ov.show');
  document.body.style.overflow   = hasOpen ? 'hidden' : '';
  document.body.style.touchAction = hasOpen ? 'none'   : '';
}
function openModal(id){
  var el = document.getElementById(id);
  if(!el) return;
  el.classList.add('show');
  _syncBodyScroll();
}
function closeModal(id){
  var el = document.getElementById(id);
  if(!el) return;
  el.classList.remove('show');
  _syncBodyScroll();
}

// ── SUPABASE AUTH ─────────────────────────────────────────────
function _getSbPass(){
  var p = safeLS('get','velo_sb_pass');
  if(!p){
    p = 'velo_' + Date.now() + '_' + Math.random().toString(36).slice(2,10) + Math.random().toString(36).slice(2,10);
    safeLS('set','velo_sb_pass', p);
  }
  return p;
}

// Guarantees a profile row exists before any save. Never overwrites existing fields.
async function _getOrCreateProfile(userId){
  _initSupabase();
  if(!sbClient || !userId) return;
  try{
    var chk = await sbClient.from('profiles').select('id').eq('id', userId).limit(1);
    if(chk.data && chk.data.length) return; // row exists — nothing to do
    // Row missing — insert minimal skeleton so subsequent UPSERTs always find it
    var _email = safeLS('get','velo_user_email') || '';
    await sbClient.from('profiles').insert({ id: userId, email: _email, role: 'user' });
  }catch(e){}
}

async function _sbSyncProfile(userId){
  if(_sbSyncProfilePending) return;
  _sbSyncProfilePending = true;
  try{ await _sbSyncProfileInner(userId); }finally{ _sbSyncProfilePending = false; }
}
async function _sbSyncProfileInner(userId){
  _initSupabase();
  if(!sbClient) return;
  // Always verify against the actual live session — never trust a cached/passed userId.
  // If the Supabase token switched to a different user (cross-tab login or token refresh),
  // using the wrong userId would load another user's profile and mood data.
  var _authSPRes;
  try{ _authSPRes = await sbClient.auth.getUser(); }catch(e){ return; }
  if(!_authSPRes || !_authSPRes.data || !_authSPRes.data.user) return;
  var sessionUid = _authSPRes.data.user.id;
  if(userId && userId !== sessionUid){
    console.warn('[_sbSyncProfile] userId mismatch — passed:',userId.slice(0,8),'session:',sessionUid.slice(0,8),'— using session');
  }
  // Session is always authoritative; lock localStorage to it
  userId = sessionUid;
  safeLS('set','velo_user_id', sessionUid);
  var res;
  // Each tier drops more optional columns; _profileSelectTier is cached so we skip
  // known-failing queries on every subsequent call (avoids 400 flood in console).
  var _selTiers = [
    'nombre,avatar,motto,role,status_music,status_book,status_phrase,status_film,username,username_changes,user_status,incognito,read_bcast_ids,badge_notified,weather_city,pro_trial_expires_at,pro_subscription_expires_at,visit_days,dark_mode,helped_count,received_count',
    'nombre,avatar,motto,role,status_music,status_book,status_phrase,status_film,username,username_changes,user_status,incognito,read_bcast_ids',
    'nombre,avatar,motto,role,status_music,status_book,status_phrase,status_film,username,username_changes',
    'nombre,avatar,motto,role,username,username_changes',
    'nombre,avatar,motto,role,username',
    'nombre,avatar,motto,role',   // fallback: username column not yet created in Supabase
    'nombre,avatar'               // bare minimum
  ];
  try{
    for(var _ti = _profileSelectTier; _ti < _selTiers.length; _ti++){
      res = await sbClient.from('profiles').select(_selTiers[_ti]).eq('id',userId).limit(1);
      if(!res.error){ _profileSelectTier = _ti; safeLS('set','velo_prof_tier', String(_ti)); break; }
      else{ console.warn('[_sbSyncProfile] tier',_ti,'failed:',res.error.message); }
    }
    if(res.error){ console.error('[_sbSyncProfile] all tiers failed'); return; }
  }catch(e){ console.error('[_sbSyncProfile] SELECT exception:',e); return; }

  if(res.error) return;

  if(!res.data || !res.data.length){
    // No profile row — first login or post-deletion re-entry. Create minimal profile.
    var curEmail = safeLS('get','velo_user_email') || '';
    if(curEmail){
      sbClient.from('profiles').upsert({
        id:userId, email:curEmail, role:'user',
        avatar: safeLS('get','velo_user_av')||'',
        motto:  safeLS('get','velo_user_motto')||''
      },{ onConflict:'id' }).then(function(){}).catch(function(){});
    }
    // Prompt user to complete their profile (handles re-entry after account deletion)
    if(!safeLS('get','velo_user_name')){
      setTimeout(function(){
        pToast('👋','¡Bienvenido/a! Completá tu perfil para comenzar 🌿');
      }, 1500);
    }
    return;
  }

  var p = res.data[0];
  console.log('[_sbSyncProfile] data from Supabase:', JSON.stringify({nombre:p.nombre,username:p.username,avatar:p.avatar?'[set]':'[empty]',motto:p.motto?'[set]':'[empty]'}));
  if(p.nombre){
    var _email    = safeLS('get','velo_user_email') || '';
    var _emailPfx = _email.split('@')[0];
    var _localName = safeLS('get','velo_user_name') || '';
    // Detect names that should never be restored from Supabase — system defaults and email patterns only
    var _INVALID_NAMES = ['Usuario','usuario','User','user','','null','undefined'];
    var _looksAutoGen = (_INVALID_NAMES.indexOf(p.nombre) >= 0) ||
                        (p.nombre === _emailPfx) ||
                        (p.nombre === _email) ||
                        (p.nombre.indexOf(' ') < 0 && /^\w+\.\w+\d{3,}$/.test(p.nombre));
    if(!_looksAutoGen){
      // Valid real name from Supabase — use on all devices
      safeLS('set','velo_user_name', p.nombre);
    } else if(_localName && _INVALID_NAMES.indexOf(_localName) < 0 && _localName !== _emailPfx && !(/^[a-zA-Z0-9._-]+\d{3,}$/.test(_localName))){
      // Supabase has a bad name but local has a real name — push local to Supabase to repair it
      sbClient.from('profiles').upsert({ id: userId, nombre: _localName }, { onConflict: 'id' })
        .then(function(r){ if(r&&r.error) console.warn('[nombre repair]', r.error); })
        .catch(function(e){ console.warn('[nombre repair catch]', e); });
      // Keep local real name — don't overwrite it with the bad Supabase value
    } else if(!_localName && !_looksAutoGen && p.nombre){
      // Fresh device, Supabase has valid name — restore it
      safeLS('set','velo_user_name', p.nombre);
    } else if(!_localName && _looksAutoGen && p.nombre){
      // Fresh device, Supabase has auto-gen name — use it temporarily, show nudge
      safeLS('set','velo_user_name', p.nombre);
      var _nudgeDay = 'velo_name_nudge_'+new Date().toISOString().slice(0,10);
      if(!safeLS('get',_nudgeDay)){
        safeLS('set',_nudgeDay,'1');
        setTimeout(function(){
          pToast('👋','Actualizá tu nombre real en Perfil 🌿');
        }, 2800);
      }
    }
  }
  if(p.avatar){
    safeLS('set','velo_user_av', p.avatar);
  } else {
    // Avatar migration: user had a base64 photo stored only in localStorage (pre-v449).
    // If this device has the photo, silently upload it to Storage so all devices can sync it.
    var _localAv = safeLS('get','velo_user_av') || '';
    if(_localAv.startsWith('data:')){
      _uploadAvatarToStorage(null, _localAv, function(pub){
        if(pub){ safeLS('set','velo_user_av', pub); _syncAvatarToSb(pub); _updateSidebarUser(); }
      });
    }
  }
  // Restore inbox read state from Supabase so messages stay read on new devices
  if(p.read_bcast_ids && Array.isArray(p.read_bcast_ids)){
    var _restoredDel = []; try{ _restoredDel = JSON.parse(safeLS('get','velo_inbox_deleted')||'[]'); }catch(e){}
    var _delChanged = false;
    p.read_bcast_ids.forEach(function(bid){
      if(!bid) return;
      if(bid === 'm1' || bid === 'm2'){ safeLS('set','velo_read_'+bid,'1'); }
      else { safeLS('set','velo_bcast_read_'+bid,'1'); }
      // rp_ IDs (admin replies) need to be in velo_inbox_deleted so pRenderInbox filters them
      if(bid.indexOf('rp_') === 0 && _restoredDel.indexOf(bid) < 0){
        _restoredDel.push(bid); _delChanged = true;
      }
      _syncedReadIds[bid] = 1;
      // Surveys: set velo_read_ key so _checkSurveyDue skips on next load
      if(bid.indexOf('survey-') === 0) safeLS('set','velo_read_'+bid,'1');
    });
    if(_delChanged) safeLS('set','velo_inbox_deleted', JSON.stringify(_restoredDel));
  } else {
    // profiles.read_bcast_ids column missing or null — read from auth.user_metadata as fallback
    // (this is where _syncBroadcastRead saves when the column doesn't exist)
    try{
      var _umr = await sbClient.auth.getUser();
      var _umeta = _umr && _umr.data && _umr.data.user && _umr.data.user.user_metadata;
      if(_umeta && Array.isArray(_umeta.read_bcast_ids)){
        _umeta.read_bcast_ids.forEach(function(bid){
          if(!bid) return;
          _syncedReadIds[bid] = 1;
          safeLS('set','velo_bcast_read_'+bid,'1');
          if(bid.indexOf('survey-') === 0) safeLS('set','velo_read_'+bid,'1');
        });
      }
    }catch(e){}
  }
  // Remove surveys and weekly summaries deleted on another device, and stale Bronce badge messages
  try{
    var _ib=[]; try{_ib=JSON.parse(safeLS('get','velo_inbox')||'[]');}catch(e2){}
    var _ibf=_ib.filter(function(m){
      if(m.tipo==='encuesta' && m.id && _syncedReadIds[m.id]) return false;
      if(m.id && m.id.indexOf('weekly-') === 0 && _syncedReadIds[m.id]) return false;
      // Bronce badge messages are "silent" — remove any that slipped through older code
      if(m.id && m.id.indexOf('badge_bronce_') === 0) return false;
      return true;
    });
    if(_ibf.length !== _ib.length) safeLS('set','velo_inbox',JSON.stringify(_ibf));
  }catch(e){}
  // Badge notification cross-device: if Supabase shows a higher badge than local, show the inbox message
  if(p.badge_notified){
    var _badgeOrder = ['Novato','Bronce','Plata','Oro','Diamante'];
    var _sbBadgeIdx = _badgeOrder.indexOf(p.badge_notified);
    var _loBadgeIdx = _badgeOrder.indexOf(safeLS('get','velo_badge_last_notified') || 'Novato');
    var _localBadgeSet = !!safeLS('get','velo_badge_last_notified');
    if(_sbBadgeIdx > _loBadgeIdx && _localBadgeSet){
      safeLS('set','velo_badge_last_notified', p.badge_notified);
      var _nbIcons = {Bronce:'🥉',Plata:'🥈',Oro:'🥇',Diamante:'💎'};
      // Only notify for real milestones (Plata+); Bronce is earned silently by just using the app
      if(p.badge_notified !== 'Bronce'){ _sendBadgeInboxMsg({ name: p.badge_notified, icon: _nbIcons[p.badge_notified] || '🏅' }); }
    } else if(!_localBadgeSet){
      safeLS('set','velo_badge_last_notified', p.badge_notified || 'Novato');
    }
  }
  if(p.motto)         safeLS('set','velo_user_motto',    p.motto);
  // Never let profile sync downgrade an active admin session
  if(p.role && safeLS('get','velo_admin_session') !== '1') safeLS('set','velo_user_type', p.role);
  // Restore status fields unconditionally (null check only, so empty strings also clear old data)
  if(p.status_music  != null) safeLS('set','velo_status_music',   p.status_music);
  if(p.status_book   != null) safeLS('set','velo_status_book',    p.status_book);
  if(p.status_phrase != null) safeLS('set','velo_status_phrase',  p.status_phrase);
  if(p.status_film   != null) safeLS('set','velo_status_film',    p.status_film);
  if(p.weather_city){
    try{ localStorage.setItem('velo_weather_city', p.weather_city); }catch(e){}
    // Notify weather widget so it auto-loads city on PWA first open (fresh localStorage)
    try{ window.dispatchEvent(new CustomEvent('velo:city-synced',{detail:{city:p.weather_city}})); }catch(e){}
  }
  if(p.username)      safeLS('set','velo_username',       p.username);
  if(p.username)      _uFill(userId, p.username);
  if(p.username_changes != null) safeLS('set','velo_username_changes', String(p.username_changes));
  // Infer onboarding done from username — if user has a username, they completed setup
  if(p.username) safeLS('set','velo_onboarding_done','1');
  // Restore "helped once" badge and guardian conv count from Supabase counter
  if(p.helped_count > 0){
    safeLS('set','velo_helped_once','1');
    var _lConvs = parseInt(safeLS('get','velo_guardian_convs')||'0',10);
    if(p.helped_count > _lConvs) safeLS('set','velo_guardian_convs', String(p.helped_count));
  }
  if(p.received_count > 0){
    var _lRecv = parseInt(safeLS('get','velo_help_received')||'0',10);
    if(p.received_count > _lRecv) safeLS('set','velo_help_received', String(p.received_count));
  }
  // Restore dark mode preference on fresh devices (never overwrite an explicit local choice)
  if(p.dark_mode !== null && p.dark_mode !== undefined){
    try{
      var _lDark = localStorage.getItem('velo-r-darkmode');
      if(_lDark === null){
        localStorage.setItem('velo-r-darkmode', p.dark_mode ? '1' : '0');
        if(p.dark_mode) document.body.classList.add('r-dark');
        else document.body.classList.remove('r-dark');
      }
    }catch(e){}
  }
  // user_status: restore on new device if local is empty; don't overwrite user's current session choice
  if(p.user_status && !safeLS('get','velo_user_status')) safeLS('set','velo_user_status', p.user_status);
  // incognito: restore on new device (treat missing/null as false)
  if(p.incognito === true && safeLS('get','velo_incognito') !== 'true') safeLS('set','velo_incognito', 'true');
  // blocked users: merge DB list into local so blocks carry over to new devices
  sbClient.from('user_blocks').select('blocked_id').eq('blocker_id', userId)
    .then(function(br){
      if(!br.data || !br.data.length) return;
      var _bl = []; try{ _bl = JSON.parse(safeLS('get','velo_blocked')||'[]'); }catch(e){}
      var dirty = false;
      br.data.forEach(function(row){
        if(_bl.indexOf(row.blocked_id) < 0){ _bl.push(row.blocked_id); dirty = true; }
      });
      if(dirty) safeLS('set','velo_blocked', JSON.stringify(_bl));
    }).catch(function(){});
  // visit_days: sync with Supabase, but use SB as authoritative when local has
  // far more days — that indicates stale data from a previous/deleted account.
  if(p.visit_days && Array.isArray(p.visit_days) && p.visit_days.length){
    var _localDays = []; try{ _localDays = JSON.parse(safeLS('get','velo_visit_days')||'[]'); }catch(e){}
    var _sbDays = p.visit_days;
    // If local has more than 2× the SB count, treat local data as stale (account was reset).
    // This prevents old localStorage dates from contaminating a freshly created account.
    if(_localDays.length > _sbDays.length * 2 && _localDays.length > 5){
      safeLS('set','velo_visit_days', JSON.stringify(_sbDays));
      _updateHomeStreak();
    } else {
      // Normal case: union so a new device gets the full SB history
      var _merged = _localDays.slice();
      _sbDays.forEach(function(d){ if(_merged.indexOf(d) < 0) _merged.push(d); });
      if(_merged.length > _localDays.length){
        safeLS('set','velo_visit_days', JSON.stringify(_merged));
        _updateHomeStreak();
      }
      if(_merged.length > _sbDays.length){
        setTimeout(function(){ _pushVisitCountToSB(_getVisitDayCount()); }, 1500);
      }
    }
  }
  if(p.role === 'plus'){
    sbClient.from('profiles').select('plus_expires_at').eq('id',userId).limit(1)
      .then(function(r2){
        if(r2.data && r2.data[0] && r2.data[0].plus_expires_at &&
           new Date(r2.data[0].plus_expires_at).getTime() < Date.now()){
          safeLS('del','velo_plan');
          safeLS('set','velo_user_type','user');
          sbClient.from('profiles').update({ role:'user' }).eq('id',userId).then(function(){}).catch(function(){});
        } else {
          safeLS('set','velo_plan','plus');
        }
      }).catch(function(){ safeLS('set','velo_plan','plus'); });
  }
  // Sync pro trial and subscription dates
  if(p.role === 'pro'){
    if(p.pro_trial_expires_at)        safeLS('set','velo_pro_trial_expires_at',        p.pro_trial_expires_at);
    if(p.pro_subscription_expires_at) safeLS('set','velo_pro_subscription_expires_at', p.pro_subscription_expires_at);
    // Mark as approved if any subscription window is still open
    var _proNow = Date.now();
    var _trialOk  = p.pro_trial_expires_at        && new Date(p.pro_trial_expires_at).getTime()        > _proNow;
    var _subOk    = p.pro_subscription_expires_at && new Date(p.pro_subscription_expires_at).getTime() > _proNow;
    if(_trialOk || _subOk) safeLS('set','velo_pro_approved','true');
    // Restore pro availability from Supabase on new devices
    sbClient.from('profiles').select('pro_availability').eq('id',userId).limit(1)
      .then(function(pr){
        if(pr.data && pr.data[0] && pr.data[0].pro_availability){
          var _av = {}; try{ _av = JSON.parse(pr.data[0].pro_availability); }catch(e){}
          if(Object.keys(_av).length){
            var _pAvKey = 'velo_pro_avail_'+(safeLS('get','velo_pro_id')||safeLS('get','velo_user_email')||userId);
            safeLS('set', _pAvKey, JSON.stringify(_av));
            _proAvailEditing = _av;
          }
        }
      }).catch(function(){});
  }
  // Check if new people have added us as favorite → show badge on star
  sbClient.from('user_favorites').select('id',{count:'exact',head:true}).eq('fav_id', userId)
    .then(function(fr){
      var newTotal = fr.count || 0;
      var prevCount = parseInt(safeLS('get','velo_fav_me_count')||'-1', 10);
      safeLS('set','velo_fav_me_count', String(newTotal));
      // Only show badge if count INCREASED vs last known value.
      // If this is the first session after localStorage clear (prevCount === -1),
      // auto-mark all as seen so stale favorites don't trigger a notification.
      if(prevCount === -1 || newTotal <= prevCount){
        safeLS('set','velo_fav_me_seen', String(newTotal));
      }
      _updateFavBadge();
    }).catch(function(){});
  // Restore guardian bio/tags/status from guardian_presence
  sbClient.from('guardian_presence').select('*').eq('user_id', userId).limit(1)
    .then(function(gr){
      if(gr.data && gr.data[0]){
        if(gr.data[0].bio)  safeLS('set','velo_guardian_bio', gr.data[0].bio);
        if(gr.data[0].tags) safeLS('set','velo_guardian_tags', Array.isArray(gr.data[0].tags) ? gr.data[0].tags.join(', ') : gr.data[0].tags);
        if(gr.data[0].is_guardian === true){
          // Only restore guardian mode from DB if the user hasn't explicitly disabled it on this device.
          // velo_is_guardian==='false' (string) means the user turned it off intentionally — don't override.
          var _localGStr = safeLS('get','velo_is_guardian');
          if(_localGStr !== 'false'){
            safeLS('set','velo_is_guardian','true');
            if(gr.data[0].status && gr.data[0].status !== 'offline'){
              // Never restore incognito on session start — always wake up as disponible
              var _rawSt = gr.data[0].status || '';
              var restoredStatus = (_rawSt === 'incognito' || _rawSt.startsWith('incognito_')) ? 'disponible' : _rawSt;
              safeLS('set','velo_guardian_status', restoredStatus);
              safeLS('set','velo_user_status', restoredStatus);
              _myGuardianStatus = restoredStatus;
            }
            setTimeout(_startGuardianReqListener, 300);
            // Re-render only when DB confirms ON — never override a manual toggle the user made after this query was sent
            _renderHomeStatusToggle();
          }
        } else {
          // DB confirmed guardian mode is off — clear any stale velo_is_guardian='true' left
          // from a previous session where the disable write may have failed (e.g. expired PWA session)
          safeLS('set','velo_is_guardian','false');
          _renderHomeStatusToggle();
        }
      }
    }).catch(function(){});
  // Refresh all UI with synced data — use localStorage (already repaired) over raw Supabase value
  var _syncName = safeLS('get','velo_user_name') || p.nombre || '';
  var _syncAv   = safeLS('get','velo_user_av')   || p.avatar || '🧑';
  var hn = document.getElementById('homeUserName');
  if(hn) hn.textContent = _syncName;
  var hnf = document.getElementById('homeUserNameFab');
  if(hnf) hnf.textContent = _syncName;
  _renderAvatarEl('homeAvFab', _syncAv);
  if(typeof _checkAndShowNameBanner === 'function'){
    _checkAndShowNameBanner(safeLS('get','velo_user_name') || '');
  }
  _updateSidebarUser();
  _updateTopbarMoodBadge();
  // Update profile page elements in-place — avoids re-calling _sbSyncProfile (infinite loop fix)
  _renderAvatarEl('profileAv', safeLS('get','velo_user_av') || '🧑');
  var _pnEl = document.getElementById('profileName');
  if(_pnEl) _pnEl.textContent = safeLS('get','velo_user_name') || 'Usuario';
  var _pmEl = document.getElementById('profileMotto');
  if(_pmEl) _pmEl.textContent = safeLS('get','velo_user_motto') || 'Tu lema aquí…';
  [['profStatusMusic','velo_status_music'],['profStatusBook','velo_status_book'],
   ['profStatusFilm','velo_status_film'],['profStatusPhrase','velo_status_phrase']].forEach(function(kv){
    var _el = document.getElementById(kv[0]); if(_el) _el.value = safeLS('get',kv[1]) || '';
  });
  typeof pRenderHomeGreet === 'function' && pRenderHomeGreet();
  // One-time migration: merge any locally-cached shown/deleted IDs into _syncedReadIds
  // (synchronous update) so the poll below has the full picture, then pushes to Supabase async
  if(typeof _migrateBcastLocalToSb === 'function') _migrateBcastLocalToSb();
  // Trigger buzón poll NOW that _syncedReadIds is fully populated
  if(typeof _buzónPollOnce === 'function') _buzónPollOnce();
  if(typeof _updateInboxDot === 'function') _updateInboxDot();
  // If the inbox is open right now, re-render so synced read IDs take effect immediately
  // (the broadcast cards were rendered before this sync completed — need a second pass)
  var _inPage = document.getElementById('pg-inbox');
  if(_inPage && _inPage.classList && _inPage.classList.contains('show') && typeof pRenderInbox === 'function'){
    pRenderInbox();
  }
  // Check survey after sync so _syncedReadIds is fully populated
  if(typeof _checkSurveyDue === 'function') _checkSurveyDue();
  // Push any local moods missing from Supabase, then run weekly summary so it has complete data
  if(typeof _pushMissingMoodsToSb === 'function'){
    _pushMissingMoodsToSb().then(function(){
      if(typeof _checkWeeklySummary === 'function') _checkWeeklySummary().catch(function(){});
    }).catch(function(){
      if(typeof _checkWeeklySummary === 'function') _checkWeeklySummary().catch(function(){});
    });
  } else if(typeof _checkWeeklySummary === 'function'){
    _checkWeeklySummary().catch(function(){});
  }
}

async function _ensureSbSession(){
  if(!sbClient) return false;
  try{
    var {data:sd} = await sbClient.auth.getSession();
    if(sd && sd.session && sd.session.user){
      var _lsEmail = (safeLS('get','velo_user_email') || '').toLowerCase().trim();
      var _sessEmail = (sd.session.user.email || '').toLowerCase().trim();
      // Cross-account token bleed: different account in session vs stored email.
      // Sign out and send to login — never re-auth silently with a stored password.
      if(_lsEmail && _sessEmail && _lsEmail !== _sessEmail){
        console.warn('[_ensureSbSession] session mismatch — redirecting to login');
        try{ await sbClient.auth.signOut(); }catch(e){}
        if(typeof pGoTo === 'function') pGoTo('login');
        return false;
      }
      if(sd.session.user.id) safeLS('set','velo_user_id', sd.session.user.id);
      return true;
    }
    // No active session — try Supabase's own stored refresh token (no password needed).
    var {data:rd, error} = await sbClient.auth.refreshSession();
    if(!error && rd && rd.user && rd.user.id){
      safeLS('set','velo_user_id', rd.user.id);
      return true;
    }
    return false;
  }catch(e){ return false; }
}

// ── SUPABASE COMMUNITY HELPERS ────────────────────────────────
async function _sbLoad(table, qFn){
  _initSupabase();
  if(!sbClient) return null;
  try{
    var q = sbClient.from(table).select('*');
    if(qFn) q = qFn(q);
    var res = await q;
    if(res.error){ console.error('[_sbLoad] '+table+':', res.error.message, res.error); return null; }
    if(!res.data) return null;
    return res.data;
  }catch(e){ console.error('[_sbLoad catch] '+table+':', e); return null; }
}

// Sequence counter so each _sbSub call gets a unique channel name,
// preventing "cannot add postgres_changes callbacks after subscribe" when
// Supabase's async removeChannel hasn't finished before the next call.
var _sbSubSeq = 0;
function _sbSub(channelName, table, callback){
  _initSupabase();
  if(!sbClient) return null;
  try{
    var uniq = channelName + ':' + (++_sbSubSeq);
    return sbClient.channel(uniq)
      .on('postgres_changes', { event: '*', schema: 'public', table: table }, callback)
      .subscribe();
  }catch(e){ return null; }
}

function _sbUnsub(ch){
  if(ch && sbClient){ try{ sbClient.removeChannel(ch); }catch(e){} }
}

// Replacement for confirm() — works on iOS Safari PWA where confirm() is silently blocked
function _pConfirm(msg, onYes){
  var ov = document.createElement('div');
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:99999;display:flex;align-items:flex-end;justify-content:center;padding:0';
  // Use hardcoded dark colors — CSS variables resolve inconsistently on dynamically appended nodes
  ov.innerHTML = '<div style="background:#0e1f14;border-radius:20px 20px 0 0;padding:24px 20px calc(28px + env(safe-area-inset-bottom,0px));width:100%;max-width:480px;font-family:Jost,sans-serif;border-top:1.5px solid rgba(116,198,157,.18)">'
    +'<p style="font-size:15px;color:#d8eed8;text-align:center;margin:0 0 22px;line-height:1.6">'+msg+'</p>'
    +'<div style="display:flex;gap:12px">'
    +'<button id="_pcNo" style="flex:1;padding:13px;border-radius:100px;border:1.5px solid rgba(116,198,157,.3);background:rgba(116,198,157,.06);color:rgba(180,220,180,.85);font-family:Jost,sans-serif;font-size:14px;cursor:pointer">Cancelar</button>'
    +'<button id="_pcYes" style="flex:1;padding:13px;border-radius:100px;border:1.5px solid rgba(255,80,80,.45);background:rgba(255,80,80,.14);color:rgba(255,130,130,1);font-family:Jost,sans-serif;font-size:14px;font-weight:700;cursor:pointer">Confirmar</button>'
    +'</div></div>';
  document.body.appendChild(ov);
  function _close(){ if(ov.parentNode) ov.parentNode.removeChild(ov); }
  ov.querySelector('#_pcNo').addEventListener('click', function(e){ e.stopPropagation(); e.preventDefault(); _close(); });
  ov.querySelector('#_pcYes').addEventListener('click', function(e){ e.stopPropagation(); e.preventDefault(); _close(); setTimeout(onYes, 80); });
  ov.addEventListener('click', function(e){ if(e.target === ov){ e.stopPropagation(); _close(); } });
}

