async function pSignUp(){
  var nameEl  = document.getElementById('regName');
  var emailEl = document.getElementById('regEmail');
  var passEl  = document.getElementById('regPass');
  var tcEl    = document.getElementById('regTcCheck');
  var btn     = document.getElementById('regBtn');
  var btnTxt  = document.getElementById('regBtnTxt');
  if(!nameEl||!emailEl||!passEl) return;

  var name  = nameEl.value.trim();
  var email = emailEl.value.trim();
  var pass  = passEl.value;

  // Validate
  var ok = true;
  _clearFieldErr('regNameErr'); _clearFieldErr('regEmailErr'); _clearFieldErr('regPassErr');
  var tcErrEl = document.getElementById('regTcErr');
  if(tcErrEl) tcErrEl.style.display = 'none';
  if(!name){ _showFieldErr('regNameErr'); ok=false; }
  if(!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){ _showFieldErr('regEmailErr'); ok=false; }
  var passOk = pass && pass.length >= 6 && /[0-9]/.test(pass) && /[a-z]/.test(pass) && /[A-Z]/.test(pass);
  if(!passOk){ _showFieldErr('regPassErr'); ok=false; }
  if(tcEl && !tcEl.checked){ if(tcErrEl) tcErrEl.style.display='block'; ok=false; }
  if(!ok) return;
  if(!_botGuardCheck()) return;

  if(btn) btn.disabled = true;
  if(btnTxt) btnTxt.textContent = 'Creando cuenta…';

  try{
    _initSupabase();
    var appURL = window.location.origin + window.location.pathname;
    var result;
    if(sbClient){
      result = await sbClient.auth.signUp({
        email:email, password:pass,
        options:{ data:{ nombre:name, role:'user' }, emailRedirectTo: appURL }
      });
      if(!result.error && result.data && result.data.user){
        await sbClient.from('profiles').upsert({
          id: result.data.user.id, nombre: name, email: email,
          role: 'user', terms_accepted_at: new Date().toISOString(),
          created_at: new Date().toISOString()
        });
      }
    } else {
      result = { error: null };
    }
    if(result.error){
      var errMsg = result.error.message || 'Error al registrar';
      if(/rate.limit/i.test(errMsg))           errMsg = 'Demasiados intentos. Esperá unos minutos o iniciá sesión si ya creaste la cuenta.';
      else if(/already.registered/i.test(errMsg)) errMsg = 'Este email ya está registrado. Si eliminaste tu cuenta, iniciá sesión para continuar como usuario nuevo 🔑';
      else if(/invalid.email/i.test(errMsg))   errMsg = 'El email no es válido.';
      else if(/password/i.test(errMsg))        errMsg = 'La contraseña debe tener al menos 6 caracteres.';
      pToast('⚠️', errMsg);
    } else {
      safeLS('set','velo_user_email', email);
      safeLS('set','velo_user_name', name);
      safeLS('set','velo_user_type','user');
      _recordTC(name, email, 'TOS-v1');
      // Go to pick-username first — pSaveUsername() will then navigate to verify-email
      safeLS('set','velo_pick_username_from_reg','1');
      pGoTo('pick-username');
    }
  }catch(e){
    pToast('⚠️','Error de conexión');
  } finally {
    if(btn) btn.disabled = false;
    if(btnTxt) btnTxt.textContent = 'Crear mi cuenta ✨';
  }
}

async function pSignIn(){
  var emailEl = document.getElementById('loginEmail');
  var passEl  = document.getElementById('loginPass');
  var btn     = document.getElementById('loginBtn');
  var btnTxt  = document.getElementById('loginBtnTxt');
  if(!emailEl||!passEl) return;

  var email = emailEl.value.trim();
  var pass  = passEl.value;

  _clearFieldErr('loginEmailErr'); _clearFieldErr('loginPassErr');
  var ok = true;
  if(!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){ _showFieldErr('loginEmailErr'); ok=false; }
  if(!pass){ _showFieldErr('loginPassErr'); ok=false; }
  if(!ok) return;

  if(btn) btn.disabled = true;
  if(btnTxt) btnTxt.textContent = 'Ingresando…';

  try{
    _initSupabase();
    // Sign out any existing Supabase session FIRST — prevents the previous account's
    // refresh token from overwriting the new session after signInWithPassword returns
    if(sbClient){ try{ await sbClient.auth.signOut(); }catch(e){} }
    var result;
    if(sbClient){
      result = await sbClient.auth.signInWithPassword({email:email, password:pass});
    } else {
      result = { error: null, data: { user: { email: email } } };
    }
    if(result.error){
      // Check provisional password created by admin
      var provKey = 'velo_prov_'+email.toLowerCase().replace(/[^a-z0-9]/g,'_');
      var provRaw = null; try{ provRaw = JSON.parse(localStorage.getItem(provKey)); }catch(e){}
      if(provRaw && provRaw.pass === pass && provRaw.expiry > Date.now()){
        _clearSession();
        safeLS('set','velo_user_email', email);
        safeLS('set','velo_user_name', email.split('@')[0]);
        safeLS('set','velo_session','1');
        safeLS('set','velo_needs_pw_change','1');
        _authenticated = true;
        pToast('🔑','Ingresaste con contraseña provisional. Por favor cambiá tu contraseña.');
        setTimeout(function(){ pGoTo('change-password'); }, 900);
      } else {
        pToast('⚠️', result.error.message || 'Credenciales incorrectas. ¿Olvidaste tu contraseña?');
      }
    } else {
      _clearSession(); // fresh slate — no leftover data from a previous account
      safeLS('del','velo_sb_pass'); // migration: remove legacy stored password if any
      safeLS('set','velo_user_email', email);
      // Don't preset email prefix — _sbSyncProfile will restore the real name from Supabase.
      // If Supabase has no real name, the email prefix will be set as a fallback below.
      safeLS('set','velo_session','1');
      if(result.data && result.data.user && result.data.user.id){
        var uid = result.data.user.id;
        safeLS('set','velo_user_id', uid);
        // Ensure profile row exists before any sync/save (avoids silent UPDATE failures)
        await _getOrCreateProfile(uid);
        // Await profile sync so name/avatar/status are restored before home renders
        await _sbSyncProfile(uid);
        // If _sbSyncProfile found no valid name, fall back to email prefix
        if(!safeLS('get','velo_user_name')) safeLS('set','velo_user_name', email.split('@')[0]);
      }
      _authenticated = true;
      _startGuardianHeartbeat();
      setTimeout(_startGlobalDMListener, 2500);
      setTimeout(_startBuzónListener, 3000);
      setTimeout(_syncFavsFromSupabase, 3500);
      setTimeout(function(){ _startProfileSync(safeLS('get','velo_user_id')); }, 4000);
      await _loginAndGo();
    }
  }catch(e){
    pToast('⚠️','Error de conexión');
  } finally {
    if(btn) btn.disabled = false;
    if(btnTxt) btnTxt.textContent = 'Ingresar';
  }
}

// Clears every session-scoped key so no data leaks between accounts (user ↔ admin ↔ pro)
function _clearSession(){
  // Wipe ALL velo_ and velo-r- localStorage keys so dynamic keys (mood diary, visit days,
  // circle caches, inbox, etc.) don't bleed into the next account's session.
  // Only velo_prov_* (admin provisional passwords) are preserved — they're login credentials,
  // not user data, and are scoped by email address anyway.
  try{
    Object.keys(localStorage).filter(function(k){
      if(k.startsWith('velo_prov_')) return false;
      return k.startsWith('velo_') || k.startsWith('velo-r-');
    }).forEach(function(k){ localStorage.removeItem(k); });
  }catch(e){}
  // Reset all in-memory caches so the next account starts clean
  _profileSelectTier = 0;
  _sbSyncProfilePending = false;
  _sbHappy = null; _pendingHappyPost = null;
  _sbHelp  = null;
  _sbBottles = null;
  _sbCircleMsgs = [];
  _liveGuardians = [];
  _presenceCache = {};
  _syncedReadIds = {};
  _favsList = null;
  _curCircle = null;
  _allCirclesCache = [];
  _circleJoinedSession = {};
  _circleLastDbMsgId  = null;
  _circleRenderPending = false;
  _circleRenderQueued  = false;
  _inboxAsyncPending = false;
  _buzónPollTmr = null;
  _buzónLastCheck = null;
  // Chat presence + DM state
  _inActiveChat = false;
  _prevChatStatus = null;
  _dmPeer = null;
  _dmPendingToId = null;
  // Guardian chat session state
  _gcLastMsgId = null;
  _gcSessionStart = 0;
  // Circles
  _selectedCircleFoto = '';
  // Username mention cache (cross-user contamination risk)
  _unameCache = {};
  // Stop guardian heartbeat and clear all RT channel refs so the next login can resubscribe
  _stopGuardianHeartbeat();
  _stopGuardianReqListener();
  [_guardianRtCh, _guardianBcastCh, _helpRtCh, _bottleRtCh, _happyRtCh, _momentoRtCh, _circleRtCh, _dmRtCh, _dmInboxCh,
   _grReqCh, _seekerGrCh, _gcRtCh, _gcSeekerCh, _buzónRtCh, _helpChatRtCh, _profileRtCh,
   _circleMembersCh].forEach(function(ch){ _sbUnsub(ch); });
  _guardianRtCh = null; _guardianBcastCh = null; _helpRtCh = null; _bottleRtCh = null; _happyRtCh = null; _momentoRtCh = null;
  _circleRtCh = null; _dmRtCh = null; _dmInboxCh = null;
  _grReqCh = null; _seekerGrCh = null; _gcRtCh = null; _gcSeekerCh = null;
  _buzónRtCh = null; _helpChatRtCh = null; _profileRtCh = null;
  _circleMembersCh = null;
  if(_homeRefreshTmr){ clearInterval(_homeRefreshTmr); _homeRefreshTmr = null; }
  if(_seekerGrPollTmr){ clearInterval(_seekerGrPollTmr); _seekerGrPollTmr = null; }
  if(_grReqPollTmr){ clearInterval(_grReqPollTmr); _grReqPollTmr = null; }
  if(_respiraTimer){ clearInterval(_respiraTimer); _respiraTimer = null; }
  if(_circleRtPollTmr){ clearInterval(_circleRtPollTmr); _circleRtPollTmr = null; }
  if(_guardianListPollTmr){ clearInterval(_guardianListPollTmr); _guardianListPollTmr = null; }
  if(_dmPollTmr){ clearInterval(_dmPollTmr); _dmPollTmr = null; }
  if(_buzónPollTmr){ clearInterval(_buzónPollTmr); _buzónPollTmr = null; }
  if(_dmReactPollTmr){ clearInterval(_dmReactPollTmr); _dmReactPollTmr = null; }
  if(_seekerPollTmr){ clearInterval(_seekerPollTmr); _seekerPollTmr = null; }
  if(_gcPollTmr){ clearInterval(_gcPollTmr); _gcPollTmr = null; }
  _gcReactHash = ''; _dmReactHash = '';
  _moodSyncDone = false;
  _sbVerifiedMoodCount = -1;
  if(_dqRtCh){ _sbUnsub(_dqRtCh); _dqRtCh = null; }
  if(_dqReactRtCh){ _sbUnsub(_dqReactRtCh); _dqReactRtCh = null; }
  _stopDqReactPoll();
}

async function pSignOut(){
  // Mark guardian offline before clearing session data
  if(safeLS('get','velo_is_guardian') === 'true') await _updateGuardianPresence('offline');
  // Persist nombre + username to Supabase before clearing localStorage (last-chance save)
  _initSupabase();
  var _soUid = safeLS('get','velo_user_id');
  // Always use the live session UID — localStorage UID can be stale
  if(sbClient){
    try{
      var {data:_soSd} = await sbClient.auth.getSession();
      if(_soSd && _soSd.session && _soSd.session.user && _soSd.session.user.id){
        _soUid = _soSd.session.user.id;
      }
    }catch(e){}
  }
  if(sbClient && _soUid && _soUid !== 'guest'){
    var _soUpdate = {};
    var _soNombre = safeLS('get','velo_user_name');
    var _soUname  = safeLS('get','velo_username');
    var _soAvatar = safeLS('get','velo_user_av');
    var _soMotto  = safeLS('get','velo_user_motto');
    if(_soNombre) _soUpdate.nombre  = _soNombre;
    if(_soUname)  _soUpdate.username = _soUname;
    if(_soAvatar && !_soAvatar.startsWith('data:')) _soUpdate.avatar = _soAvatar;
    if(_soMotto)  _soUpdate.motto   = _soMotto;
    var _soMusic  = safeLS('get','velo_status_music');
    var _soBook   = safeLS('get','velo_status_book');
    var _soPhrase = safeLS('get','velo_status_phrase');
    var _soFilm   = safeLS('get','velo_status_film');
    if(_soMusic)  _soUpdate.status_music  = _soMusic;
    if(_soBook)   _soUpdate.status_book   = _soBook;
    if(_soPhrase) _soUpdate.status_phrase = _soPhrase;
    if(_soFilm)   _soUpdate.status_film   = _soFilm;
    if(Object.keys(_soUpdate).length){
      _soUpdate.id = _soUid;
      try{ await sbClient.from('profiles').upsert(_soUpdate, { onConflict:'id' }); }catch(e){}
    }
  }
  if(sbClient){ try{ await sbClient.auth.signOut(); }catch(e){} }
  _clearSession();
  _authenticated = false;
  _userType = 'user';
  pToast('🌿','Sesión cerrada');
  pGoTo('landing');
  _updateNavState('landing', false);
}

