// ── DATE HELPERS ──────────────────────────────────────────────
function _dateKey(d){
  d = d || new Date();
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function _fmtDate(ts){
  var d = new Date(ts);
  var months = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
  return d.getDate()+' '+months[d.getMonth()]+' '+d.getFullYear()+' · '+d.toLocaleTimeString('es',{hour:'2-digit',minute:'2-digit'});
}

// ── VISIT DAY TRACKING ──────────────────────────────────────────
// Records each unique calendar day the user opens the app (for Bronze badge)
function _localDateStr(){
  var d = new Date();
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}

// Push dark mode preference to Supabase profiles (called from rToggleDarkMode in premium-redesign.js)
function _syncDarkModeToSB(isDark){
  _initSupabase();
  var uid = _myUserId ? _myUserId() : safeLS('get','velo_user_id');
  if(!sbClient || !uid || uid === 'guest') return;
  sbClient.from('profiles').update({dark_mode: isDark ? true : false}).eq('id', uid)
    .then(function(){}).catch(function(){});
}

// Push current visit count + full dates array to Supabase profiles (fire-and-forget)
function _pushVisitCountToSB(count){
  _initSupabase();
  var uid = _myUserId();
  if(!sbClient || !uid || uid === 'guest') return;
  var _days = []; try{ _days = JSON.parse(safeLS('get','velo_visit_days')||'[]'); }catch(e){}
  sbClient.from('profiles').update({ visit_day_count: count, visit_days: _days }).eq('id', uid)
    .then(function(){}).catch(function(){}); // silent — column may not exist yet
}

// On boot: read visit_day_count from Supabase and take the maximum with local count.
// This restores count on new devices or after localStorage is cleared.
async function _pullVisitCountFromSB(){
  _initSupabase();
  var uid = _myUserId();
  if(!sbClient || !uid || uid === 'guest') return;
  try{
    var r = await sbClient.from('profiles').select('visit_day_count,visit_days').eq('id', uid).maybeSingle();
    if(r.error || !r.data) return;
    var sbCount = parseInt(r.data.visit_day_count || 0, 10);
    if(sbCount > 0){
      safeLS('set','velo_visit_day_count_sb', String(sbCount));
    }
    // Merge SB visit_days into local so consecutive streak survives cache clears
    if(r.data.visit_days && Array.isArray(r.data.visit_days) && r.data.visit_days.length){
      var _localDays2 = []; try{ _localDays2 = JSON.parse(safeLS('get','velo_visit_days')||'[]'); }catch(e){}
      var _merged2 = _localDays2.slice();
      r.data.visit_days.forEach(function(d){ if(_merged2.indexOf(d) < 0) _merged2.push(d); });
      if(_merged2.length > _localDays2.length){
        safeLS('set','velo_visit_days', JSON.stringify(_merged2));
      }
    }
    // Push local if local has more days than SB
    var localCount = _getVisitDayCount();
    if(localCount > sbCount) _pushVisitCountToSB(localCount);
    // Always refresh the UI so both devices show the same number
    _updateHomeStreak();
  }catch(e){} // Column may not exist yet — ignore
}

function _streakLabel(days){
  if(days < 30) return String(days);
  var months = days / 30;
  if(months < 1.25) return '1 mes';
  if(months < 1.75) return '1½ mes';
  var full = Math.floor(months);
  var half = (months - full) >= 0.4;
  return full + (half ? '½' : '') + (full === 1 ? ' mes' : ' meses');
}

// Backfill velo_visit_days with any day that has a mood record.
// If the user recorded a mood, they visited — these must always be in sync.
function _syncMoodDaysToVisitDays(){
  var days = []; try{ days = JSON.parse(safeLS('get','velo_visit_days')||'[]'); }catch(e){}
  var daySet = {};
  days.forEach(function(d){ daySet[d] = true; });
  var changed = false;
  var today = new Date();
  for(var i = 0; i < 365; i++){
    var d = new Date(today.getFullYear(), today.getMonth(), today.getDate() - i);
    var key = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
    if(!daySet[key] && safeLS('get','velo_mood_'+key)){
      days.push(key); daySet[key] = true; changed = true;
    }
  }
  if(changed) safeLS('set','velo_visit_days', JSON.stringify(days));
  return changed;
}

function _updateHomeStreak(){ /* mood counter removed from home — lives only in profile */ }

function _trackVisitDay(){
  var today = _localDateStr();
  var days = []; try{ days = JSON.parse(safeLS('get','velo_visit_days')||'[]'); }catch(e){}
  if(days.indexOf(today) < 0){
    days.push(today);
    safeLS('set','velo_visit_days', JSON.stringify(days));
    _checkAndNotifyBadge();
    _updateHomeStreak(); // refresh stat immediately once today is recorded
    // Delay push so _pullVisitCountFromSB (runs at 2500ms) can set the SB baseline first.
    // _getVisitDayCount() then returns Math.max(local, sbCount) — never overwrites a higher SB value.
    setTimeout(function(){
      _pushVisitCountToSB(_getVisitDayCount());
    }, 3200);
  }
}

function _getVisitDayCount(){
  var days = []; try{ days = JSON.parse(safeLS('get','velo_visit_days')||'[]'); }catch(e){}
  var sbCount = parseInt(safeLS('get','velo_visit_day_count_sb')||'0', 10);
  return Math.max(days.length, sbCount);
}
// Returns consecutive mood-registration streak using velo_mood_YYYY-MM-DD keys.
// These keys are account-scoped (cleared on _clearSession) so they can't carry
// over data from a previous/deleted account — unlike velo_visit_days which
// accumulates across app opens and can contain stale cross-account history.
function _getMoodStreak(){
  var days = [];
  try{
    var prefix = 'velo_mood_';
    Object.keys(localStorage).forEach(function(k){
      if(k.indexOf(prefix) !== 0) return;
      var dateStr = k.slice(prefix.length);
      if(!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return;
      var val = null; try{ val = JSON.parse(localStorage.getItem(k)); }catch(e){}
      if(val && val.emoji) days.push(dateStr);
    });
  }catch(e){}
  if(!days.length) return 0;
  days.sort(function(a,b){ return a < b ? 1 : a > b ? -1 : 0; });
  var today = _localDateStr();
  var d = new Date(); d.setHours(12,0,0,0);
  var yest = new Date(d); yest.setDate(d.getDate()-1);
  var yesterdayStr = yest.getFullYear()+'-'+String(yest.getMonth()+1).padStart(2,'0')+'-'+String(yest.getDate()).padStart(2,'0');
  if(days[0] !== today && days[0] !== yesterdayStr) return 0;
  var streak = 1;
  for(var i = 1; i < days.length; i++){
    var prev = new Date(days[i-1]+'T12:00:00');
    var curr = new Date(days[i]+'T12:00:00');
    if(Math.round((prev - curr) / 86400000) === 1){ streak++; } else { break; }
  }
  return streak;
}

// Returns the number of CONSECUTIVE days ending on today (or yesterday if not yet visited today)
function _getConsecutiveStreak(){
  var days = []; try{ days = JSON.parse(safeLS('get','velo_visit_days')||'[]'); }catch(e){}
  if(!days.length) return 0;
  // Sort descending
  days.sort(function(a,b){ return a < b ? 1 : a > b ? -1 : 0; });
  var today = _localDateStr();
  var d = new Date(); d.setHours(12,0,0,0);
  var yesterday = new Date(d); yesterday.setDate(d.getDate()-1);
  var yesterdayStr = yesterday.getFullYear()+'-'+String(yesterday.getMonth()+1).padStart(2,'0')+'-'+String(yesterday.getDate()).padStart(2,'0');
  // Streak must start from today or yesterday (if user hasn't visited yet today, keep streak alive)
  if(days[0] !== today && days[0] !== yesterdayStr) return 0;
  var streak = 1;
  for(var i = 1; i < days.length; i++){
    var prev = new Date(days[i-1]+'T12:00:00');
    var curr = new Date(days[i]+'T12:00:00');
    var diff = Math.round((prev - curr) / 86400000);
    if(diff === 1){ streak++; } else { break; }
  }
  return streak;
}

// ── STREAK CELEBRATION ────────────────────────────────────────
function _showStreakCelebration(){
  var todayKey = _dateKey();
  if(safeLS('get','velo_streak_cel_'+todayKey)) return; // already shown today
  // Use mood-registration streak (account-scoped) — NOT visit-day streak which
  // can contain stale data from previous/deleted accounts in localStorage.
  var streak = _getMoodStreak();
  if(streak < 1) return;
  safeLS('set','velo_streak_cel_'+todayKey, '1');
  var milestones = {1:'¡Primer registro! 🌱',3:'¡3 días! Estás en racha 🔥',7:'¡Una semana seguida! 🏆',14:'¡14 días! Constancia real ⭐',30:'¡30 días! Sos increíble 🌟',50:'¡50 días! 💎',100:'¡100 días! Leyenda 🌟'};
  var milestone = milestones[streak];
  // Create overlay
  var el = document.createElement('div');
  el.id = 'streakCelebEl';
  el.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%) translateY(20px);z-index:9999;background:linear-gradient(135deg,rgba(20,55,35,.96),rgba(10,40,22,.98));border:1.5px solid rgba(116,198,157,.45);border-radius:20px;padding:14px 22px;text-align:center;min-width:200px;max-width:280px;box-shadow:0 8px 32px rgba(0,0,0,.35);opacity:0;transition:all .35s cubic-bezier(.2,.8,.2,1);font-family:Jost,sans-serif';
  el.innerHTML = '<div style="font-size:28px;line-height:1;margin-bottom:6px">🔥</div>'
    + '<div style="font-size:22px;font-weight:800;color:#fff;letter-spacing:-.3px">'+streak+' días de racha</div>'
    + (milestone ? '<div style="font-size:14px;color:rgba(116,198,157,.90);margin-top:4px;font-weight:600">'+milestone+'</div>' : '');
  document.body.appendChild(el);
  // Animate in
  requestAnimationFrame(function(){ requestAnimationFrame(function(){
    el.style.opacity = '1'; el.style.transform = 'translateX(-50%) translateY(0)';
  }); });
  // Auto dismiss after 3s
  setTimeout(function(){
    el.style.opacity = '0'; el.style.transform = 'translateX(-50%) translateY(20px)';
    setTimeout(function(){ if(el.parentNode) el.parentNode.removeChild(el); }, 400);
  }, 3000);
}

// ── MEMORY CARD ───────────────────────────────────────────────
function _loadHomeMemoryCard(){
  var el = document.getElementById('homeMemoryCard');
  if(!el) return;
  var today = new Date();
  // Check 7 days ago then 30 days ago
  var targets = [7, 30];
  var found = null, foundDays = 0;
  for(var i=0; i<targets.length; i++){
    var t = new Date(today); t.setDate(t.getDate()-targets[i]);
    var dk = t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0');
    var stored = null; try{ stored = JSON.parse(safeLS('get','velo_mood_'+dk)||'null'); }catch(e){}
    if(stored && stored.emoji){ found = stored; foundDays = targets[i]; break; }
  }
  if(!found){ el.style.display='none'; return; }
  var daysLabel = foundDays === 7 ? 'Hace 7 días' : 'Hace un mes';
  var labelMap = {'😄':'Muy bien','😊':'Bien','😐':'Regular','😞':'Bajo','😢':'Difícil'};
  var moodLabel = found.label || labelMap[found.emoji] || '';
  el.style.display = 'block';
  el.innerHTML = '<div style="background:linear-gradient(135deg,rgba(200,158,56,.14),rgba(178,138,18,.09));border:1.5px solid rgba(200,158,56,.35);border-radius:16px;padding:12px 14px;display:flex;align-items:center;gap:12px;cursor:default">'
    + '<div style="font-size:28px;line-height:1;flex-shrink:0">'+found.emoji+'</div>'
    + '<div style="flex:1;min-width:0">'
    + '<div class="home-memo-ago">✨ '+daysLabel+'</div>'
    + '<div style="font-size:15px;font-weight:600;color:var(--ink2)">Te sentías <strong>'+moodLabel+'</strong></div>'
    + (found.note ? '<div style="font-size:13px;color:var(--ink4);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+found.note.slice(0,60)+'</div>' : '')
    + '</div>'
    + '<div class="home-memo-ver" onclick="pGoTo(\'mood\')">Ver →</div>'
    + '</div>';
}

