if('serviceWorker' in navigator && 'PushManager' in window){
  navigator.serviceWorker.ready.then(function(r){
    _swReg = r;
    // If a new SW is waiting, activate it immediately so subscribe() uses the active worker
    if(r.waiting){ r.waiting.postMessage({type:'SKIP_WAITING'}); }
  }).catch(function(){});
  // When SW updates and takes control, refresh _swReg
  navigator.serviceWorker.addEventListener('controllerchange', function(){
    navigator.serviceWorker.ready.then(function(r){ _swReg = r; }).catch(function(){});
  });
  // When the browser rotates the push endpoint (pushsubscriptionchange in SW),
  // the SW sends us the new subscription via postMessage — save it immediately.
  navigator.serviceWorker.addEventListener('message', function(e){
    if(!e.data || e.data.type !== 'PUSH_SUB_CHANGED') return;
    try{
      var newSub = JSON.parse(e.data.sub);
      safeLS('set','velo_push_sub', JSON.stringify(newSub));
      _savePushSubscriptionToSupabase(newSub).catch(function(){});
      console.log('[push] subscription rotated by browser — saved new endpoint');
    }catch(_me){}
  });
}

function _urlBase64ToUint8Array(base64String){
  var padding = '='.repeat((4 - base64String.length % 4) % 4);
  var base64 = (base64String + padding).replace(/-/g,'+'). replace(/_/g,'/');
  var rawData = atob(base64);
  var arr = new Uint8Array(rawData.length);
  for(var i=0; i<rawData.length; i++) arr[i] = rawData.charCodeAt(i);
  return arr;
}

async function _savePushSubscriptionToSupabase(sub){
  _initSupabase(); // always init — sbClient may be null on first call
  if(!sbClient) return;
  var _uid = safeLS('get','velo_user_id');
  if(!_uid) return;
  // Session may be expired (iOS PWA backgrounded) — refresh before the UPDATE or RLS will block it silently
  try{ await _ensureSbSession(); }catch(e){}
  try{
    // Wrap subscription with timezone so server can send at the right local time per region
    var _tz = (typeof Intl !== 'undefined' && Intl.DateTimeFormat) ? Intl.DateTimeFormat().resolvedOptions().timeZone : '';
    var _payload = JSON.stringify({ sub: sub, tz: _tz || 'America/Argentina/Buenos_Aires' });
    var {error:_pErr} = await sbClient.from('profiles').update({ push_subscription: _payload }).eq('id', _uid);
    if(_pErr) console.warn('[push sub save]', _pErr.message);
    else console.log('[push sub save] OK for uid', _uid, 'tz:', _tz);
  }catch(e){ console.warn('[push sub save]', e && e.message); }
}

// On startup, sync any existing localStorage push subscription to Supabase.
// Handles users who subscribed before the DB-save worked, or who cleared cache on one device.
async function _syncPushSubOnStartup(){
  var _uid = safeLS('get','velo_user_id');
  if(!_uid) return;
  if(!('serviceWorker' in navigator) || !('PushManager' in window)) return;
  try{
    // Use pushManager.getSubscription() as the authoritative source —
    // the browser may have silently rotated the endpoint since we last saved it.
    var _reg = await navigator.serviceWorker.ready;
    var _browserSub = await _reg.pushManager.getSubscription();
    if(_browserSub){
      // Always update LS with the real browser sub (endpoint may have rotated)
      safeLS('set','velo_push_sub', JSON.stringify(_browserSub));
      _initSupabase();
      if(!sbClient) return;
      try{ await _ensureSbSession(); }catch(e){}
      await _savePushSubscriptionToSupabase(_browserSub);
      console.log('[push sync startup] subscription synced from browser endpoint');
    } else {
      // No active browser subscription — clear stale LS entry
      safeLS('remove','velo_push_sub');
    }
  }catch(e){ console.warn('[push sync startup]', e && e.message); }
}

async function pRequestPushPermission(){
  if(!('Notification' in window) || !('serviceWorker' in navigator)) return;
  if(Notification.permission === 'granted'){
    var _hasSub = !!safeLS('get','velo_push_sub');
    if(_hasSub){ pToast('🔔','Las notificaciones ya están activas'); return; }
    // Delegate to sync subscribe (preserves user gesture on iOS)
    _tryRecoverPushSub();
    return;
  }
  if(Notification.permission === 'denied'){
    pToast('🔕','Notificaciones bloqueadas — activálas desde ajustes del navegador');
    return;
  }
  var perm = await Notification.requestPermission();
  if(perm !== 'granted') return;
  safeLS('set','velo_push_granted','1');
  // After requestPermission we still have user activation — call subscribe immediately
  if(_swReg){
    _swReg.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: _urlBase64ToUint8Array(_VAPID_PUBLIC_KEY)
    }).then(function(sub){
      if(!sub) return;
      safeLS('set','velo_push_sub', JSON.stringify(sub));
      _savePushSubscriptionToSupabase(sub).catch(function(){});
      pToast('🔔','¡Notificaciones activadas! 💚');
      _updateEditPushUI();
      _renderHomePushBanner();
    }).catch(function(){ _showPushFixModal('error'); });
  } else {
    try{
      var reg = await navigator.serviceWorker.ready;
      var sub = await reg.pushManager.subscribe({ userVisibleOnly:true, applicationServerKey:_urlBase64ToUint8Array(_VAPID_PUBLIC_KEY) });
      safeLS('set','velo_push_sub', JSON.stringify(sub));
      _savePushSubscriptionToSupabase(sub).catch(function(){});
      pToast('🔔','¡Notificaciones activadas! 💚');
      _updateEditPushUI();
      _renderHomePushBanner();
    }catch(e){ _showPushFixModal('error'); }
  }
}

function _checkRequestPushPermission(){
  // Only ask if: notifications not yet granted, user has been using app for 2+ days, not asked before
  if(!('Notification' in window)) return;
  if(Notification.permission !== 'default') return;
  if(safeLS('get','velo_push_asked')) return;
  var dayCount = _getVisitDayCount();
  if(dayCount < 2) return;
  safeLS('set','velo_push_asked','1');
  // Show in-app prompt (friendlier than browser popup directly)
  setTimeout(function(){ _showPushPrompt(); }, 4000);
}

function _showPushPrompt(){
  if(document.getElementById('pushPromptEl')) return;
  var el = document.createElement('div');
  el.id = 'pushPromptEl';
  el.style.cssText = 'position:fixed;bottom:90px;left:16px;right:16px;z-index:9998;background:linear-gradient(135deg,rgba(12,40,24,.97),rgba(8,28,16,.99));border:1.5px solid rgba(116,198,157,.40);border-radius:20px;padding:16px 18px;box-shadow:0 8px 32px rgba(0,0,0,.40);font-family:Jost,sans-serif;animation:pushPromptIn .4s cubic-bezier(.2,.8,.2,1) both';
  el.innerHTML = '<style>@keyframes pushPromptIn{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}</style>'
    + '<div style="display:flex;align-items:flex-start;gap:12px">'
    + '<div style="font-size:26px;line-height:1;flex-shrink:0">🔔</div>'
    + '<div style="flex:1">'
    + '<div style="font-size:14px;font-weight:700;color:#fff;margin-bottom:4px">¿Querés un recordatorio diario?</div>'
    + '<div style="font-size:14px;color:rgba(255,255,255,.65);line-height:1.45;margin-bottom:12px">Mañana, tarde y noche — siempre amigable, nunca spam. Un recordatorio para registrar cómo te sentís.</div>'
    + '<div style="display:flex;gap:8px">'
    + '<button onclick="pRequestPushPermission();document.getElementById(\'pushPromptEl\').remove()" style="flex:1;padding:10px 14px;border-radius:12px;border:none;background:linear-gradient(135deg,rgba(116,198,157,.25),rgba(74,160,110,.30));color:rgba(116,198,157,.95);font-size:15px;font-weight:700;font-family:Jost,sans-serif;cursor:pointer">Sí, quiero 💚</button>'
    + '<button onclick="document.getElementById(\'pushPromptEl\').remove()" style="padding:10px 14px;border-radius:12px;border:1px solid rgba(255,255,255,.15);background:transparent;color:rgba(255,255,255,.50);font-size:14px;font-weight:600;font-family:Jost,sans-serif;cursor:pointer">Ahora no</button>'
    + '</div>'
    + '</div>'
    + '</div>';
  document.body.appendChild(el);
}

