var _curGuardian = null;
var _guardianFilter = 'all';
var _myGuardianStatus = safeLS('get','velo_guardian_status') || 'disponible'; // disponible/ocupado/incognito
var _guardianHeartbeatTimer = null;
var _lastGuardianListKey = ''; // dedup key to skip re-render when list didn't change
// Module-level so pToggleGuardianMode can cancel them on re-activation, preventing
// the race where a stale blur/visibility timer fires AFTER re-activation and writes 'ocupado'.
var _guardianVisibilityTimer = null;
var _guardianBlurTimer = null;

// The user's general availability (disponible/ocupado). Guardians may also be 'incognito'.
function _presenceStatus(){
  if(safeLS('get','velo_is_guardian') === 'true') return safeLS('get','velo_guardian_status') || 'disponible';
  return safeLS('get','velo_user_status') || 'disponible';
}

// Upserts the current user's presence row. Used for ALL logged-in users, not just guardians.
async function _updateGuardianPresence(status){
  _initSupabase();
  if(!sbClient) return;
  var uid = _myUserId ? _myUserId() : (safeLS('get','velo_user_email')||'guest');
  if(!uid || uid === 'guest') return;
  // Ensure auth session is alive — critical on iOS PWA where sessions expire silently.
  try{ await _ensureSbSession(); }catch(e){}
  // Re-read uid after session refresh — _ensureSbSession may have written a fresh velo_user_id
  var _freshUid = safeLS('get','velo_user_id');
  if(_freshUid) uid = _freshUid;
  if(!uid || uid === 'guest') return;
  var isG  = safeLS('get','velo_is_guardian') === 'true';
  var st   = status || _presenceStatus();
  var _isIncogStatus = st === 'incognito' || st.startsWith('incognito_');
  var name = _isIncogStatus ? 'Guardián Anónimo' : (safeLS('get','velo_user_name') || 'Usuario');
  var _rawAv = _isIncogStatus ? '🌿' : (safeLS('get','velo_user_av') || (isG ? '💚' : '🧑'));
  var av = (_rawAv.startsWith('data:') || _rawAv.startsWith('http')) ? (isG ? '💚' : '🧑') : _rawAv;
  var row  = { user_id: uid, name: name, avatar: av, is_guardian: isG,
    status: st, last_seen: new Date().toISOString() };
  if(isG){
    row.bio = safeLS('get','velo_guardian_bio') || '';
    var tagsRaw = safeLS('get','velo_guardian_tags') || '';
    row.tags = tagsRaw ? tagsRaw.split(',').map(function(t){ return t.trim(); }).filter(Boolean) : [];
    row.convs = parseInt(safeLS('get','velo_guardian_convs')||'0', 10);
    row.rating = 5.0;
  }
  var _upsertOk = false;
  var _doRetry = false;
  try{
    var _upRes = await sbClient.from('guardian_presence').upsert(row, { onConflict: 'user_id' });
    if(_upRes && _upRes.error){
      console.error('[presence upsert]', _upRes.error.message, _upRes.error);
      _doRetry = true;
    } else { _upsertOk = true; }
  }catch(e){ console.error('[presence upsert catch]', e); _doRetry = true; }
  if(_doRetry){
    // Retry once after 2s — session may have expired (iOS PWA) or network briefly dropped.
    // CRITICAL: re-check is_guardian before writing — if the user toggled state during the
    // 2s wait, the old row is stale and writing it would overwrite the correct DB state.
    try{
      await new Promise(function(r){ setTimeout(r, 2000); });
      var _currentIsG = safeLS('get','velo_is_guardian') === 'true';
      if(_currentIsG !== isG){ _upsertOk = true; return; } // state changed — let that write handle DB
      await _ensureSbSession();
      row.last_seen = new Date().toISOString();
      var _retry = await sbClient.from('guardian_presence').upsert(row, { onConflict: 'user_id' });
      if(_retry && _retry.error){ console.error('[presence upsert retry]', _retry.error.message); }
      else { _upsertOk = true; }
    }catch(e2){ console.error('[presence upsert retry catch]', e2); }
  }
  if(!_upsertOk) return; // Don't broadcast if DB write failed
  // Broadcast the change so other clients update instantly.
  // The channel may still be in JOINING state (just subscribed) — retry once after 1.5s
  // before nulling, so the initial beat() on re-activation doesn't kill the channel.
  try{
    if(_guardianBcastCh){
      var _bcastCh = _guardianBcastCh, _bcastRow = row;
      _guardianBcastCh.send({ type:'broadcast', event:'presence_change', payload: row })
        .then(function(res){
          if(res !== 'ok'){
            setTimeout(function(){
              if(_guardianBcastCh === _bcastCh && _guardianBcastCh){
                _guardianBcastCh.send({ type:'broadcast', event:'presence_change', payload: _bcastRow })
                  .then(function(res2){ if(res2 !== 'ok'){ _sbUnsub(_guardianBcastCh); _guardianBcastCh = null; } })
                  .catch(function(){ _sbUnsub(_guardianBcastCh); _guardianBcastCh = null; });
              }
            }, 1500);
          }
        })
        .catch(function(){ _sbUnsub(_guardianBcastCh); _guardianBcastCh = null; });
    }
  }catch(e){ _sbUnsub(_guardianBcastCh); _guardianBcastCh = null; }
}

// ── PRESENCE CACHE (online dots everywhere) ────────────────────
var _presenceCache = {};
async function _refreshPresenceCache(){
  _initSupabase();
  if(!sbClient) return;
  try{
    var cutoff = new Date(Date.now() - 3*60*1000).toISOString();
    var res = await sbClient.from('guardian_presence').select('user_id,status,last_seen').gte('last_seen', cutoff);
    var fresh = {};
    (res.data||[]).forEach(function(r){ fresh[r.user_id] = { status:r.status, last_seen:r.last_seen }; });
    _presenceCache = fresh;
  }catch(e){}
}
function _presenceInfo(userId){
  var p = userId ? _presenceCache[userId] : null;
  if(p && p.last_seen && (Date.now() - new Date(p.last_seen).getTime()) < 5*60*1000 && p.status !== 'offline'){
    // Incognito users are completely invisible — show as offline to contacts and favorites
    if(p.status === 'incognito' || (p.status && p.status.startsWith('incognito_'))){
      return { color:'rgba(150,150,150,.45)', label:'Desconectado', on:false };
    }
    if(p.status === 'ocupado') return { color:'#E0A92E', label:'Ocupado/a', on:true };
    return { color:'#5BBF87', label:'En línea', on:true };
  }
  return { color:'rgba(150,150,150,.45)', label:'Desconectado', on:false };
}
// Returns a small presence-dot HTML span. Empty string when no userId (anonymous).
function _presenceDot(userId, size){
  if(!userId) return '';
  var s = size || 9;
  var info = _presenceInfo(userId);
  return '<span title="'+info.label+'" style="display:inline-block;width:'+s+'px;height:'+s+'px;border-radius:50%;background:'+info.color+';border:1.5px solid #fff;box-shadow:0 0 3px rgba(0,0,0,.25);flex-shrink:0"></span>';
}

// Creates/re-creates the shared broadcast channel for guardian presence changes.
// Called on login, on every heartbeat tick, and on page entry so a CLOSED channel
// is always replaced before the next send attempt.
function _createGuardianBcastCh(){
  if(!sbClient || _guardianBcastCh) return;
  _guardianBcastCh = sbClient.channel('velo:guardian-changes')
    .on('broadcast', { event: 'presence_change' }, function(msg){
      if(_curPage === 'guardians') pRenderGuardians();
    })
    .subscribe(function(status){
      // Detect CLOSED/CHANNEL_ERROR so the reference is nulled and the next
      // heartbeat tick (or page entry) re-creates a working channel.
      if(status === 'CLOSED' || status === 'CHANNEL_ERROR'){
        _guardianBcastCh = null;
      }
    });
}

// Universal presence heartbeat — runs for every logged-in user, not only guardians.
function _startGuardianHeartbeat(){
  _startGuardianReqListener();
  // Subscribe to broadcast channel here (at login) so the guardian can SEND on it
  // even when not on the guardians page. Must happen before the early-return guard.
  _initSupabase();
  _createGuardianBcastCh();
  if(_guardianHeartbeatTimer) return;
  var beat = function(){
    // Self-heal: re-create both channels if they were CLOSED since the last tick.
    _createGuardianBcastCh();
    if(!_guardianReqCh) _startGuardianReqListener();
    _updateGuardianPresence(_inActiveChat ? 'ocupado' : _presenceStatus());
    _refreshPresenceCache().then(function(){
      if(_curPage === 'contacts') pRenderContacts();
      else _updateFavBadge();
    }).catch(function(){});
    if(_curCircle){
      var _cmId = safeLS('get','velo_user_id') || safeLS('get','velo_user_email') || '';
      if(_cmId && sbClient){
        sbClient.from('circle_members').upsert({circle_id:_curCircle.id, user_id:_cmId, last_seen:new Date().toISOString()},
          {onConflict:'circle_id,user_id'}).then(function(){}).catch(function(){});
      }
    }
  };
  beat();
  _guardianHeartbeatTimer = setInterval(beat, 30000);
}

function _stopGuardianHeartbeat(){
  if(_guardianHeartbeatTimer){ clearInterval(_guardianHeartbeatTimer); _guardianHeartbeatTimer = null; }
  _stopGuardianReqListener();
}

function pHomeToggleGuardian(){
  var wasOn = safeLS('get','velo_is_guardian') === 'true';
  if(!wasOn){
    // Show setup modal on the first activation of each day
    var today = new Date().toISOString().slice(0,10);
    var lastDay = safeLS('get','velo_guardian_setup_day') || '';
    if(lastDay !== today){
      safeLS('set','velo_guardian_setup_day', today);
      pShowGuardianSetupModal();
      return;
    }
  }
  pToggleGuardianMode();
  setTimeout(function(){
    var isOn  = safeLS('get','velo_is_guardian') === 'true';
    var gBtn  = document.getElementById('homeGuardianBtn');
    var gWrap = document.getElementById('homeGuardianWrap');
    if(gBtn){
      var _gs = _gBtnStyle(isOn);
      gBtn.style.background  = _gs.bg;
      gBtn.style.borderColor = _gs.border;
      gBtn.style.color       = _gs.color;
      gBtn.textContent       = isOn ? '🛡️ Activado' : '🛡️ Actívame';
    }
    var gLabel = gWrap ? gWrap.querySelector('span') : null;
    if(gLabel) gLabel.textContent = isOn ? 'Activo' : 'Activarme';
  }, 50);
}

