// ── ACOMPAÑANTE VELO IA ──────────────────────────────────────────
var _calmAIMsgs = [];
var _calmChipsShown = false;

// ── Calm AI: session memory (localStorage per day) ───────────────────
function _calmTodayKey(){
  var d = new Date();
  return 'velo_calm_'+d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function _saveCalmSession(){
  if(!_calmAIMsgs.some(function(m){ return m.user; })) return;
  safeLS('set', _calmTodayKey(), JSON.stringify(_calmAIMsgs.slice(-30)));
}
function _loadCalmSession(){
  try{ return JSON.parse(safeLS('get', _calmTodayKey())||'[]'); }catch(e){ return []; }
}

// ── Calm AI: mood context from today's mood log ───────────────────────
function _calmMoodContext(){
  var d = new Date();
  var dk = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  var stored = safeLS('get','velo_mood_'+dk);
  if(!stored) return null;
  try{ return JSON.parse(stored); }catch(e){ return null; }
}

// ── Calm AI: personalized greeting ───────────────────────────────────
function _calmGreeting(mood){
  var hour = new Date().getHours();
  var tg = hour < 12 ? 'Buenos días' : hour < 20 ? 'Buenas tardes' : 'Buenas noches';
  if(mood && mood.emoji){
    var desc = {'😄':'muy bien hoy','😊':'bien hoy','😐':'más o menos hoy','😞':'no tan bien hoy','😢':'bastante mal hoy'}[mood.emoji]||'de cierta manera hoy';
    var noteSnip = mood.note ? ' Me comentaste: "'+mood.note.slice(0,55)+(mood.note.length>55?'…':'')+'". ' : ' ';
    return tg+' 🌿 Vi que registraste que te sentís '+desc+'.'+noteSnip+'Estoy acá si querés contarme más, sin ningún apuro.';
  }
  var opts = [
    'Hola, estoy acá para acompañarte 🌿 ¿Cómo te sentís en este momento? Podés contarme lo que quieras, sin apuros.',
    tg+' 🌿 Me alegra que estés acá. ¿Cómo andás hoy?',
    'Hola 🌿 Este es tu espacio, sin juicios. ¿Qué te trajo por acá hoy?'
  ];
  var d = new Date();
  return opts[(d.getDate()+d.getHours())%opts.length];
}

// ── Calm AI: quick-start chips ────────────────────────────────────────
function _showCalmChips(){
  var msgEl = document.getElementById('calmAIMessages');
  if(!msgEl || _calmChipsShown) return;
  _calmChipsShown = true;
  var chips = [
    { label:'😰 Estoy ansioso/a',       text:'Estoy sintiendo mucha ansiedad' },
    { label:'😔 Me siento solo/a',       text:'Me siento muy solo/a últimamente' },
    { label:'😤 Tuve un día difícil',    text:'Tuve un día muy difícil' },
    { label:'😴 No puedo dormir',        text:'Tengo problemas para dormir' },
    { label:'💭 Solo quiero hablar',      text:'Quiero hablar y que alguien me escuche' }
  ];
  var wrap = document.createElement('div');
  wrap.id = 'calmChips';
  wrap.style.cssText = 'display:flex;flex-wrap:wrap;gap:8px;padding:6px 0 10px';
  wrap.innerHTML = chips.map(function(c){
    return '<button class="calm-chip" onclick="pCalmChipSend('+_jsAttr(c.text)+')">'+c.label+'</button>';
  }).join('');
  msgEl.appendChild(wrap);
  msgEl.scrollTop = msgEl.scrollHeight;
}
function pCalmChipSend(text){
  var chips = document.getElementById('calmChips');
  if(chips) chips.remove();
  var ta = document.getElementById('calmAIInput');
  if(ta){ ta.value = text; }
  pSendCalmAIMsg();
}

function _initCalmAIPage(){
  _calmChipsShown = false;
  var msgEl = document.getElementById('calmAIMessages');
  if(msgEl) msgEl.innerHTML = '';
  var ta = document.getElementById('calmAIInput');
  if(ta){ ta.value = ''; ta.style.height = ''; }

  var prevMsgs = _loadCalmSession();
  var hasUser = prevMsgs.some(function(m){ return m.user; });

  if(hasUser){
    // Offer to resume today's conversation
    var lastUser = prevMsgs.slice().reverse().find(function(m){ return m.user; });
    var _lt = lastUser ? (lastUser.text||'') : '';
    var snippet = _lt ? _escHtml(_lt.slice(0,65))+(_lt.length>65?'…':'') : '';
    var resumeDiv = document.createElement('div');
    resumeDiv.style.cssText = 'margin:16px 0 8px;padding:14px;background:rgba(116,198,157,.08);border:1px solid rgba(116,198,157,.22);border-radius:16px;text-align:center';
    resumeDiv.innerHTML = '<div style="font-size:13px;color:rgba(255,255,255,.45);margin-bottom:6px;letter-spacing:.3px">CONVERSACIÓN DE HOY</div>'
      +'<div style="font-size:14px;color:rgba(255,255,255,.6);font-style:italic;margin-bottom:12px;line-height:1.5">"'+snippet+'"</div>'
      +'<div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap">'
      +'<button onclick="_calmResumeSession()" style="padding:9px 18px;background:rgba(116,198,157,.18);border:1.5px solid rgba(116,198,157,.38);border-radius:100px;font-size:14px;font-weight:700;color:rgba(116,198,157,.9);cursor:pointer;font-family:\'Jost\',sans-serif">↩️ Retomar conversación</button>'
      +'<button onclick="_calmStartFresh()" style="padding:9px 18px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);border-radius:100px;font-size:14px;color:rgba(255,255,255,.45);cursor:pointer;font-family:\'Jost\',sans-serif">Empezar de nuevo</button>'
      +'</div>';
    if(msgEl) msgEl.appendChild(resumeDiv);
  } else {
    _calmStartFresh();
  }
}

function _calmStartFresh(){
  _calmAIMsgs = [];
  _calmChipsShown = false;
  var msgEl = document.getElementById('calmAIMessages');
  if(msgEl) msgEl.innerHTML = '';
  var mood = _calmMoodContext();
  var greeting = _calmGreeting(mood);
  setTimeout(function(){
    _calmAIAddMsg(greeting, false);
    setTimeout(_showCalmChips, 700);
  }, 400);
}

function _calmResumeSession(){
  var prevMsgs = _loadCalmSession();
  _calmAIMsgs = prevMsgs;
  _calmChipsShown = true;
  var msgEl = document.getElementById('calmAIMessages');
  if(msgEl) msgEl.innerHTML = '';
  prevMsgs.forEach(function(m){
    var div = document.createElement('div');
    div.innerHTML = _buildMsgBubble(m.text, m.user, '🌿', 'Acompañante Velo', 'calmAIInput', 'calmAIReplyBar', '');
    if(!m.user){
      var bubble = div.querySelector('.feed-bubble');
      if(bubble) bubble.innerHTML = bubble.innerHTML.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
    }
    var child = div.firstElementChild;
    if(child && msgEl) msgEl.appendChild(child);
  });
  if(msgEl) msgEl.scrollTop = msgEl.scrollHeight;
  setTimeout(function(){
    _calmAIAddMsg('Seguimos donde lo dejamos 🌿 ¿Cómo te sentís ahora?', false);
  }, 350);
}

function _calmAIAddMsg(text, isUser){
  _calmAIMsgs.push({text:text, user:isUser});
  var msgEl = document.getElementById('calmAIMessages');
  if(!msgEl) return;
  var div = document.createElement('div');
  div.innerHTML = _buildMsgBubble(text, isUser, '🌿', 'Acompañante Velo', 'calmAIInput', 'calmAIReplyBar', '');
  if(!isUser){
    var bubble = div.querySelector('.feed-bubble');
    if(bubble) bubble.innerHTML = bubble.innerHTML.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  }
  var child = div.firstElementChild;
  if(child) msgEl.appendChild(child);
  msgEl.scrollTop = msgEl.scrollHeight;
}

async function _geminiChat(systemPrompt, msgs, cfg){
  // 1. Gemini proxy — primary (multi-turn chat)
  try{
    var pr = await fetch(GEMINI_PROXY, { method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ type:'chat', systemPrompt:systemPrompt, msgs:msgs, cfg:cfg||{} }) });
    if(pr.ok){ var t1 = _gText(await pr.json()); if(t1) return t1; }
    else { var e1={}; try{e1=await pr.json();}catch(x){} console.warn('[Velo] Gemini chat',pr.status,e1.error||''); }
  }catch(e){ console.warn('[Velo] Gemini chat error:',e.message); }
  // 2. Groq proxy — fallback multi-turn chat (llama-3.3-70b)
  try{
    var gr = await fetch(GROQ_PROXY, { method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ type:'chat', systemPrompt:systemPrompt, msgs:msgs, cfg:cfg||{} }) });
    if(gr.ok){ var t2 = _gText(await gr.json()); if(t2) return t2; }
  }catch(e){}
  // 3. Last resort: embed conversation as single generate prompt
  var convLines = msgs.slice(-8).map(function(m){
    return (m.user ? 'Usuario' : 'Acompañante Velo') + ': ' + m.text;
  });
  var fallbackPrompt = systemPrompt
    + '\n\nConversación hasta ahora:\n' + convLines.join('\n')
    + '\n\nAcompañante Velo (respondé en 2-3 oraciones, cálido y específico a lo que el usuario dijo):';
  return _geminiCall(fallbackPrompt, Object.assign({ temperature:0.88, maxOutputTokens:220 }, cfg||{}));
}

async function pSendCalmAIMsg(){
  var ta = document.getElementById('calmAIInput');
  if(!ta || !ta.value.trim()) return;
  var text = ta.value.trim();
  ta.value = '';
  ta.style.height = '';
  // Remove quick-start chips on first user message
  var chips = document.getElementById('calmChips');
  if(chips) chips.remove();
  var calmQuote = _getReplyQuote('calmAIReplyBar');
  pClearReplyBar('calmAIReplyBar');
  _calmAIMsgs.push({text:text, user:true});
  var msgEl0 = document.getElementById('calmAIMessages');
  var div0 = document.createElement('div');
  div0.innerHTML = _buildMsgBubble(text, true, '', '', 'calmAIInput', 'calmAIReplyBar', calmQuote);
  var child0 = div0.firstElementChild; if(child0 && msgEl0){ msgEl0.appendChild(child0); msgEl0.scrollTop = msgEl0.scrollHeight; }
  var msgEl = document.getElementById('calmAIMessages');
  var typingDiv = document.createElement('div');
  typingDiv.id = 'calmAITyping';
  typingDiv.className = 'feed-msg';
  typingDiv.innerHTML = '<div class="feed-av">🌿</div><div><div class="feed-sender" style="font-size:13px;color:var(--ink4)">Acompañante Velo</div><div class="feed-bubble" style="color:var(--ink4);font-style:italic">Escribiendo…</div></div>';
  if(msgEl){ msgEl.appendChild(typingDiv); msgEl.scrollTop = msgEl.scrollHeight; }

  // Mood context — inject today's mood if the user logged one
  var _cm = _calmMoodContext();
  var moodLine = _cm
    ? '\nEstado de ánimo registrado hoy por el usuario: '+_cm.emoji+((_cm.label)?' ('+_cm.label+')':'')+'.'+(_cm.note?' Su nota: "'+_cm.note.slice(0,80)+'". ':'')+'Usá esto como contexto cuando sea relevante, no lo menciones directamente a menos que el usuario lo traiga.'
    : '';

  var systemPrompt = 'Sos Velo, un acompañante emocional especializado, entrenado en técnicas de psicología clínica y humanista. '
    +'Aplicás escucha activa profunda, técnicas rogerianas de reflejo y validación, y preguntas socráticas para facilitar la reflexión genuina. '
    +'Tenés experiencia y sensibilidad especial en: ansiedad y ataques de pánico, tristeza y depresión, duelo y pérdidas, problemas de pareja y familia, maltrato emocional y violencia doméstica, autoestima herida y trauma. '
    +'Respondés siempre en español rioplatense (usás "vos", "te", "estás", "querés"). '
    +'Estructura de cada respuesta: (1) Validación empática específica — nombrás exactamente lo que dijo la persona, sin frases genéricas. (2) Reflejo o reformulación que demuestre comprensión profunda. (3) Una pregunta abierta y reflexiva que invite a explorar, sin presionar. '
    +'Usás entre 2-4 oraciones por respuesta — concisas, cálidas y directas. NUNCA dés consejos directivos antes de explorar cómo se siente. NUNCA repetís frases. NUNCA minimizás el dolor ("todo pasa", "hay gente peor"). '
    +'Si la persona menciona violencia activa, maltrato o peligro: con calidez reconocé el valor de contarlo y mencioná: la Sala de Ayuda de Velo y el 0800-222-1002 (violencia) o el 135 (crisis emocionales, Argentina). '
    +'No sos terapeuta ni médico. Sos un espacio seguro, humano y sin juicios.'
    + moodLine;

  var reply = await _geminiChat(systemPrompt, _calmAIMsgs.slice(-14), { temperature:0.88, maxOutputTokens:280 });
  if(!reply){
    await new Promise(function(r){ setTimeout(r, 1500); });
    reply = await _geminiChat(systemPrompt, _calmAIMsgs.slice(-14), { temperature:0.88, maxOutputTokens:280 });
  }
  var typingEl = document.getElementById('calmAITyping');
  if(typingEl) typingEl.remove();
  if(!reply){
    _calmAIAddMsg('Hay un problema de conexión en este momento 🌿 ¿Podés intentarlo de nuevo en un instante? Estoy acá para vos.', false);
  } else {
    _calmAIAddMsg(reply, false);
  }
  _saveCalmSession(); // Feature: persist session for today
  _geminiCrisisCheck(text);
}

// ── COMPARTIR FRASE DEL DÍA ────────────────────────────────────
function pShareDailyQuote(){
  var quoteEl  = document.getElementById('homeDailyQuoteText');
  var authorEl = document.getElementById('homeDailyQuoteAuthor');
  var quote  = quoteEl  ? quoteEl.textContent.trim()  : '';
  var author = (authorEl ? authorEl.textContent.trim() : '').replace(/^—\s*/,'');
  if(!quote){ pToast('🌟','Esperá un momento mientras carga la frase'); return; }

  // Try logo URLs in order; first success wins, last failure draws without logo
  var _logoUrls = [
    'assets/logo.png',
    'https://yuravtnjvvztsxdtggod.supabase.co/storage/v1/object/public/velo-assets/IMG_2624.png'
  ];
  (function _nextLogo(i){
    if(i >= _logoUrls.length){ _drawShareCanvas(quote, author, null); return; }
    var img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload  = function(){ _drawShareCanvas(quote, author, img); };
    img.onerror = function(){ _nextLogo(i+1); };
    img.src = _logoUrls[i];
  })(0);
}

function _drawShareCanvas(quote, author, logoImg){
  var W = 1080, H = 1920;
  var canvas = document.createElement('canvas');
  canvas.width = W; canvas.height = H;
  var ctx = canvas.getContext('2d');

  // ── Deep forest-to-midnight gradient background ──────────────
  var bg = ctx.createLinearGradient(0, 0, W*0.6, H);
  bg.addColorStop(0,    '#0C2E1A');
  bg.addColorStop(0.45, '#092535');
  bg.addColorStop(1,    '#0A1E12');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // ── Ambient light blobs (wellness glow) ──────────────────────
  // Emerald glow — top right
  var ga = ctx.createRadialGradient(W*0.88, H*0.10, 0, W*0.88, H*0.10, 560);
  ga.addColorStop(0,   'rgba(56,188,106,.26)');
  ga.addColorStop(0.5, 'rgba(22,101,52,.10)');
  ga.addColorStop(1,   'rgba(0,0,0,0)');
  ctx.fillStyle = ga; ctx.fillRect(0, 0, W, H);

  // Teal glow — bottom left
  var gb = ctx.createRadialGradient(W*0.12, H*0.90, 0, W*0.12, H*0.90, 520);
  gb.addColorStop(0,   'rgba(14,120,148,.22)');
  gb.addColorStop(0.5, 'rgba(8,70,90,.08)');
  gb.addColorStop(1,   'rgba(0,0,0,0)');
  ctx.fillStyle = gb; ctx.fillRect(0, 0, W, H);

  // Soft lavender haze — center-right
  var gc = ctx.createRadialGradient(W*0.78, H*0.52, 0, W*0.78, H*0.52, 380);
  gc.addColorStop(0,   'rgba(130,80,180,.10)');
  gc.addColorStop(1,   'rgba(0,0,0,0)');
  ctx.fillStyle = gc; ctx.fillRect(0, 0, W, H);

  // Warm gold glow — center (behind quote)
  var gd = ctx.createRadialGradient(W*0.50, H*0.50, 0, W*0.50, H*0.50, 350);
  gd.addColorStop(0,   'rgba(200,158,56,.07)');
  gd.addColorStop(1,   'rgba(0,0,0,0)');
  ctx.fillStyle = gd; ctx.fillRect(0, 0, W, H);

  // ── Organic star-like particles ───────────────────────────────
  var seed = 42;
  function _rnd(){ seed=(seed*16807+0)%2147483647; return(seed-1)/2147483646; }
  for(var pi=0; pi<220; pi++){
    var px=_rnd()*W, py=_rnd()*H, pr=_rnd()*1.8+0.3, pa=_rnd()*.18+.04;
    ctx.beginPath(); ctx.arc(px,py,pr,0,Math.PI*2);
    ctx.fillStyle='rgba(200,230,215,'+pa+')'; ctx.fill();
  }

  // ── Leaf / botanical accent (top-left) ───────────────────────
  ctx.save();
  ctx.translate(90, 330);
  ctx.rotate(-0.35);
  ctx.strokeStyle = 'rgba(116,198,157,.22)';
  ctx.lineWidth = 2;
  // Simple leaf outline
  ctx.beginPath();
  ctx.moveTo(0, 80); ctx.bezierCurveTo(-50, 40, -55, -30, 0, -80);
  ctx.bezierCurveTo(55, -30, 50, 40, 0, 80);
  ctx.stroke();
  ctx.beginPath(); ctx.moveTo(0, 80); ctx.lineTo(0, -80); ctx.stroke();
  ctx.restore();

  // Mirror leaf — bottom-right
  ctx.save();
  ctx.translate(W-90, H-320);
  ctx.rotate(2.80);
  ctx.strokeStyle = 'rgba(116,198,157,.18)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0, 80); ctx.bezierCurveTo(-50, 40, -55, -30, 0, -80);
  ctx.bezierCurveTo(55, -30, 50, 40, 0, 80);
  ctx.stroke();
  ctx.beginPath(); ctx.moveTo(0, 80); ctx.lineTo(0, -80); ctx.stroke();
  ctx.restore();

  // ── Corner filigree accents ───────────────────────────────────
  function _filigree(x, y, sx, sy){
    ctx.strokeStyle = 'rgba(200,158,56,.30)';
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(x, y+sy*50); ctx.lineTo(x, y); ctx.lineTo(x+sx*50, y); ctx.stroke();
    ctx.strokeStyle = 'rgba(200,158,56,.12)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(x+sx*8, y+sy*50); ctx.lineTo(x+sx*8, y+sy*8); ctx.lineTo(x+sx*50, y+sy*8); ctx.stroke();
  }
  var fp=110, fy1=290, fy2=H-290;
  _filigree(fp,   fy1,  1,  1);
  _filigree(W-fp, fy1, -1,  1);
  _filigree(fp,   fy2,  1, -1);
  _filigree(W-fp, fy2, -1, -1);

  // ── Brand header: large dark-mode logo ───────────────────────
  var logoW = 600, logoH = 600;
  var logoX = (W - logoW) / 2;
  var logoY = 60;

  if(logoImg){
    ctx.save();
    ctx.shadowColor = 'rgba(116,198,157,.55)';
    ctx.shadowBlur  = 70;
    ctx.drawImage(logoImg, 0, 0, logoImg.naturalWidth, logoImg.naturalHeight, logoX, logoY, logoW, logoH);
    ctx.restore();
  }

  // ── "Mi frase del día" label ──────────────────────────────────
  var logoBottom = logoY + (logoImg ? logoH : 240);
  var labelY = logoBottom + 100;
  ctx.font = 'italic 300 44px Georgia,serif'; ctx.fillStyle = 'rgba(220,190,110,.82)'; ctx.textAlign = 'center';
  ctx.fillText('Mi frase del día', W/2, labelY);
  // Thin dot-line ornament beneath label
  ctx.strokeStyle = 'rgba(200,158,56,.32)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(W/2-240, labelY+28); ctx.lineTo(W/2-12, labelY+28); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(W/2+12, labelY+28); ctx.lineTo(W/2+240, labelY+28); ctx.stroke();
  ctx.fillStyle='rgba(200,158,56,.55)'; ctx.beginPath(); ctx.arc(W/2, labelY+28, 3.5, 0, Math.PI*2); ctx.fill();

  // ── Large decorative quote mark ───────────────────────────────
  ctx.font='300 220px Georgia,serif'; ctx.fillStyle='rgba(200,158,56,.12)'; ctx.textAlign='left';
  ctx.fillText('”', 100, 630);

  // ── Quote text (word-wrap, centered) ─────────────────────────
  ctx.font='italic 400 72px Georgia,serif'; ctx.fillStyle='rgba(248,246,240,.94)'; ctx.textAlign='center';
  var words=quote.split(' '), lines=[], cur='', maxTW=W-200;
  words.forEach(function(w){
    var t=cur?cur+' '+w:w;
    if(ctx.measureText(t).width>maxTW){lines.push(cur);cur=w;}else cur=t;
  });
  if(cur)lines.push(cur);
  var lh=96, tH=lines.length*lh;
  var qY=Math.max(labelY + 100, Math.round((H-tH)/2)-50);
  lines.forEach(function(l,i){ ctx.fillText(l,W/2,qY+i*lh); });

  // ── Author area — ornamental divider + name ───────────────────
  var aY = qY + tH + 90;
  var lineLen = 220;
  ctx.strokeStyle='rgba(200,158,56,.45)'; ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.moveTo(W/2-lineLen, aY-38); ctx.lineTo(W/2-26, aY-38); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(W/2+26, aY-38); ctx.lineTo(W/2+lineLen, aY-38); ctx.stroke();
  ctx.fillStyle='rgba(200,158,56,.65)';
  ctx.beginPath(); ctx.arc(W/2, aY-38, 4.5, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(W/2-lineLen, aY-38, 3, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(W/2+lineLen, aY-38, 3, 0, Math.PI*2); ctx.fill();
  if(author){
    ctx.font='300 40px Arial,sans-serif'; ctx.fillStyle='rgba(220,180,80,.90)'; ctx.textAlign='center';
    ctx.fillText(author.toUpperCase(), W/2, aY);
  }

  // ── Bottom CTA pill ───────────────────────────────────────────
  var ctaBaseY = H - 240;
  // Ornamental divider with end dots
  ctx.strokeStyle='rgba(200,158,56,.25)'; ctx.lineWidth=1;
  ctx.beginPath(); ctx.moveTo(160,ctaBaseY-60); ctx.lineTo(W-160,ctaBaseY-60); ctx.stroke();
  ctx.fillStyle='rgba(200,158,56,.40)';
  ctx.beginPath(); ctx.arc(160,ctaBaseY-60, 3, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(W-160,ctaBaseY-60, 3, 0, Math.PI*2); ctx.fill();

  // Pill background
  var pillW=680, pillH=116, pillX=(W-pillW)/2, pillY=ctaBaseY-22;
  ctx.beginPath(); ctx.roundRect(pillX, pillY, pillW, pillH, 58);
  var pillGrad=ctx.createLinearGradient(pillX,pillY,pillX+pillW,pillY+pillH);
  pillGrad.addColorStop(0,'rgba(22,160,80,.30)');
  pillGrad.addColorStop(0.5,'rgba(14,120,148,.26)');
  pillGrad.addColorStop(1,'rgba(22,160,80,.30)');
  ctx.fillStyle=pillGrad; ctx.fill();
  ctx.save();
  ctx.shadowColor='rgba(116,198,157,.35)'; ctx.shadowBlur=18;
  ctx.strokeStyle='rgba(116,198,157,.55)'; ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.roundRect(pillX, pillY, pillW, pillH, 58); ctx.stroke();
  ctx.restore();

  // “Únete a nuestra comunidad”
  ctx.font='300 31px Arial,sans-serif'; ctx.fillStyle='rgba(180,235,205,.75)'; ctx.textAlign='center';
  ctx.fillText('Únete a nuestra comunidad', W/2, pillY+44);

  // “heyvelo.app”
  ctx.font='700 50px Arial,sans-serif'; ctx.fillStyle='rgba(200,158,56,.94)'; ctx.textAlign='center';
  ctx.fillText('heyvelo.app', W/2, pillY+92);

  // ── Share ─────────────────────────────────────────────────────
  canvas.toBlob(function(blob){
    if(!blob){ pToast('⚠️','No se pudo generar la imagen'); return; }
    var file = new File([blob], 'frase-velo.png', {type:'image/png'});
    var shareText = '“' + quote + '”' + (author ? '\n— ' + author : '') + '\n\n✨ Únete a heyvelo.app';
    var shareData = { title: 'Frase del día · Velo', text: shareText, files: [file] };
    if(navigator.canShare && navigator.canShare({files:[file]})){
      navigator.share(shareData).catch(function(){});
    } else if(navigator.share){
      navigator.share({ title: shareData.title, text: shareData.text }).catch(function(){});
    } else {
      var a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'frase-velo.png';
      a.click();
      setTimeout(function(){ URL.revokeObjectURL(a.href); }, 3000);
    }
  }, 'image/png');
}

// ── SUGERENCIAS PERSONALIZADAS ──────────────────────────────────
async function _renderPersonalizedSuggestions(){
  var el = document.getElementById('homeSuggestions');
  if(!el) return;
  var _tok = _navToken;
  var moods = []; try{ moods = JSON.parse(safeLS('get','velo_mood_log')||'[]'); }catch(e){}
  if(moods.length < 3){ el.style.display='none'; return; }
  var emojiList = moods.slice(0,7).map(function(m){ return m.emoji; }).join(', ');
  var prompt = 'Sos el sistema de sugerencias de Velo, una app de bienestar emocional entre pares. '
    +'El usuario registró estos estados de ánimo recientes (del más reciente al más antiguo): '+emojiList+'. '
    +'Emojis: 😄=muy bien, 😊=bien, 😐=regular, 😞=mal, 😢=muy mal. '
    +'Secciones disponibles: guardianes=conectarse con personas que escuchan, help=Sala de Ayuda, circles=grupos temáticos, diary=escritura reflexiva, calm=respiración y meditación, bottle=mensajes anónimos al mar, news=buenas noticias del día. '
    +'Sugerí 2 secciones relevantes para este patrón de ánimo. Respondé en JSON: '
    +'[{"icon":"emoji","titulo":"nombre","razon":"una oración breve","page":"guardianes|help|circles|diary|calm|bottle|news"}] '
    +'Solo el array JSON.';
  var result = await _geminiCall(prompt);
  if(_navToken !== _tok || !document.getElementById('homeSuggestions')) return;
  var sugs = [];
  if(result){
    try{ var match = result.match(/\[[\s\S]*\]/); if(match) sugs = JSON.parse(match[0]); }catch(e){}
  }
  if(!sugs.length){ el.style.display='none'; return; }
  el.style.display = '';
  el.innerHTML = '<div style="font-size:13px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:var(--ink4);margin-bottom:10px">Sugerido para vos 💡</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">'
    +sugs.map(function(s){
      return '<div class="p-card p-card--hover" style="padding:14px;cursor:pointer" onclick="pGoTo(\''+_escHtml(s.page||'home')+'\')">'
        +'<div style="font-size:22px;margin-bottom:6px">'+s.icon+'</div>'
        +'<div style="font-family:\'Cormorant Garamond\',serif;font-size:15px;color:var(--ink);margin-bottom:4px">'+_escHtml(s.titulo)+'</div>'
        +'<div style="font-size:13px;color:var(--ink4);line-height:1.4">'+_escHtml(s.razon)+'</div>'
        +'</div>';
    }).join('')
    +'</div>';
}

