var HAPPY_TTL       = 24 * 60 * 60 * 1000; // 24 horas
var HAPPY_MAX       = 50;                   // máximo de posts en el muro global
var _happyEmojis    = ['☀️','🌻','🎉','🌈','💚','🌸','✨','🌱','🎵','🙌','🦋','💛'];
var _happyReactEmojis = ['💛','🌸','🤗','🌿','✨'];
var _selectedHappyEmoji = '☀️';
