function pSetAvatarFromFile(input){
  if(!input.files || !input.files[0]) return;
  var file = input.files[0];
  if(file.size > 5*1024*1024){ pToast('⚠️','Imagen demasiado grande (máx 5MB)'); return; }
  var reader = new FileReader();
  reader.onload = function(e){
    _compressImg(e.target.result, async function(dataUrl){
      pToast('🔍','Verificando imagen…');
      var mod = await _moderateImage(dataUrl);
      if(!mod.safe){
        pToast('🚫','Imagen no permitida: '+mod.reason);
        var _warnId = safeLS('get','velo_user_id');
        if(_warnId) _sendContentWarning(_warnId, mod.reason);
        return;
      }
      // Show preview immediately using local data URL
      safeLS('set','velo_user_av', dataUrl);
      pLoadProfile();
      _propagateAvatarUI(dataUrl);
      // Upload to Supabase Storage (public URL, not base64 in DB)
      _uploadAvatarToStorage(file, dataUrl, function(publicUrl){
        var finalAv = publicUrl || dataUrl;
        safeLS('set','velo_user_av', finalAv);
        _syncAvatarToSb(finalAv);
        pToast('✅','Foto de perfil actualizada 🌿');
        closeModal('avatarPickerOv');
        pLoadProfile();
        _propagateAvatarUI(finalAv);
      });
    });
  };
  reader.readAsDataURL(file);
}

function _uploadAvatarToStorage(file, dataUrl, callback){
  _initSupabase();
  var uid = safeLS('get','velo_user_id');
  if(!sbClient || !uid){ callback(null); return; }
  try{
    var mimeType = (file && file.type) || (dataUrl.split(',')[0].split(':')[1]||'').split(';')[0] || 'image/jpeg';
    var ext = mimeType.split('/')[1]||'jpg';
    var path = uid+'.'+ext;
    // Convert data URL to Blob
    var byteStr = atob(dataUrl.split(',')[1]);
    var ab = new ArrayBuffer(byteStr.length);
    var ia = new Uint8Array(ab);
    for(var i=0;i<byteStr.length;i++) ia[i]=byteStr.charCodeAt(i);
    var blob = new Blob([ab], {type:mimeType});
    sbClient.storage.from('avatars').upload(path, blob, {contentType:mimeType, upsert:true})
      .then(function(r){
        if(r.error){ console.warn('[avatar storage]', r.error.message); callback(null); return; }
        var urlRes = sbClient.storage.from('avatars').getPublicUrl(path);
        var pub = urlRes && urlRes.data && urlRes.data.publicUrl;
        // Append cache-bust so browsers reload the image on re-upload
        if(pub) pub = pub.split('?')[0]+'?t='+Date.now();
        callback(pub||null);
      }).catch(function(e){ console.warn('[avatar storage catch]', e); callback(null); });
  }catch(e){ console.warn('[avatar storage error]', e); callback(null); }
}

async function _syncAvatarToSb(av){
  _initSupabase();
  var uid = safeLS('get','velo_user_id');
  if(!sbClient) return;
  try{
    var {data:_avSd} = await sbClient.auth.getSession();
    if(_avSd && _avSd.session && _avSd.session.user && _avSd.session.user.id){
      uid = _avSd.session.user.id;
      safeLS('set','velo_user_id', uid);
    }
  }catch(e){}
  if(!uid) return;
  // Only store URL or emoji in profiles.avatar — never store large base64 strings
  var stored = (av && av.length > 8000) ? '' : av;
  sbClient.from('profiles').upsert({ id:uid, avatar:stored },{ onConflict:'id' })
    .then(function(r){ if(r && r.error) pToast('⚠️','Foto guardada solo en este dispositivo (sin conexión a la nube).'); })
    .catch(function(){ pToast('⚠️','Foto guardada solo en este dispositivo (sin conexión a la nube).'); });
}

function pLoadProfile(){
  var name  = safeLS('get','velo_user_name') || 'Usuario';
  var av    = safeLS('get','velo_user_av') || '🧑';
  var motto = safeLS('get','velo_user_motto') || 'Mi camino, mi ritmo.';
  var uname = safeLS('get','velo_username') || '';
  var _pConvs = parseInt(safeLS('get','velo_guardian_convs')||'0',10);
  var _pBadge = _getBadge(_pConvs);
  var _pVerified = (_pBadge.name==='Plata'||_pBadge.name==='Oro'||_pBadge.name==='Diamante');
  // Name with verified tick
  var nameEl = document.getElementById('profileName');
  if(nameEl) nameEl.innerHTML = _escHtml(name) + (_pVerified ? ' <span class="velo-verified" title="Verificado — Plata o superior">✓</span>' : '');
  _renderAvatarEl('profileAv', av);
  // Verified badge on avatar photo (bottom-left, status dot is bottom-right)
  var avWrap = document.getElementById('profileAv') && document.getElementById('profileAv').parentElement;
  if(avWrap){
    var old = avWrap.querySelector('.velo-verified-av');
    if(old) old.parentElement.removeChild(old);
    if(_pVerified){
      var vb = document.createElement('div');
      vb.className = 'velo-verified-av';
      vb.title = 'Verificado — Guardián Plata o superior';
      vb.textContent = '✓';
      avWrap.appendChild(vb);
    }
  }
  _setEl('profileMotto', motto);
  // Show @username or prompt to set one
  var unameEl = document.getElementById('profileUsername');
  if(unameEl){
    if(uname){
      unameEl.innerHTML = '<span style="color:var(--sage2);font-weight:700">@'+_escHtml(uname)+'</span>';
      unameEl.onclick = null;
      unameEl.style.cursor = 'default';
    } else {
      unameEl.innerHTML = '<span style="color:#E0A92E;font-weight:700;cursor:pointer" onclick="pGoTo(\'pick-username\')">⚠️ Elegí tu @usuario</span>';
      unameEl.onclick = function(){ pGoTo('pick-username'); };
      unameEl.style.cursor = 'pointer';
    }
  }
  // Pre-fill username in edit modal
  var euEl = document.getElementById('editUsername');
  if(euEl){ euEl.value = uname; euEl.disabled = false; }
  var _unCh = parseInt(safeLS('get','velo_username_changes')||'0', 10);
  var _unLeft = Math.max(0, 2 - _unCh);
  var _unHint = document.getElementById('usernameChangesHint');
  if(_unHint){
    if(_unLeft === 0) _unHint.innerHTML = ' · <span style="color:#E05C5C">sin cambios restantes</span>';
    else _unHint.innerHTML = '';
  }
  if(_unLeft === 0 && euEl) euEl.disabled = true;
  // Show the "max 2 changes" note with remaining count
  var noteEl = document.getElementById('editUsernameChangesNote');
  var leftEl  = document.getElementById('editUsernameChangesLeft');
  if(noteEl) noteEl.style.display = 'block';
  if(leftEl){
    if(_unLeft === 0) leftEl.innerHTML = ' <strong style="color:#E05C5C">Ya usaste los 2 cambios disponibles.</strong>';
    else leftEl.innerHTML = ' Te quedan <strong>'+_unLeft+'</strong> cambio'+(_unLeft===1?'':'s')+'.';
  }

  // Plan badge
  var planBadge = document.getElementById('profilePlanBadge');
  if(planBadge){
    planBadge.innerHTML = _isPremium()
      ? '<span class="p-pill p-pill--gold">⭐ Velo Plus</span>'
      : '<span class="p-pill p-pill--sage">🌱 Gratuito</span>';
  }

  // Email
  _setEl('profileEmail', safeLS('get','velo_user_email') || '—');
  // Push notifications toggle — always show; iOS handles gracefully
  var _prRow = document.getElementById('profilePushRow');
  if(_prRow){ _prRow.style.display = 'block'; _updateEditPushUI(); }

  // Stats — count mood-recording days in the CURRENT month, with dynamic month label
  var _today = new Date();
  var _curYear  = _today.getFullYear();
  var _curMonth = _today.getMonth(); // 0-indexed
  var _monthNames = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  var _daysInCurMonth = new Date(_curYear, _curMonth+1, 0).getDate();
  var _moodDayCount = 0;
  for(var _di = 1; _di <= _daysInCurMonth; _di++){
    var _mdk = _curYear+'-'+String(_curMonth+1).padStart(2,'0')+'-'+String(_di).padStart(2,'0');
    if(safeLS('get','velo_mood_'+_mdk)) _moodDayCount++;
  }
  var _monthLabel = _monthNames[_curMonth];
  _setEl('profileDays', _moodDayCount);
  var _lbl = document.getElementById('profileDaysLbl');
  if(_lbl) _lbl.innerHTML = 'ÁNIMOS<br>' + _monthLabel.toUpperCase();
  var _locHelped = parseInt(safeLS('get','velo_guardian_convs')||'0', 10);
  var _locRecv   = parseInt(safeLS('get','velo_help_received')||'0', 10);
  _setEl('profileChats',    _locHelped + _locRecv);
  _setEl('profileHelped',   _locHelped);
  _setEl('profileReceived', _locRecv);
  // Count real conversations — three sources: localStorage, guardian_requests table, profiles table
  _initSupabase();
  if(sbClient){
    // Always use auth.getUser() for the uid — localStorage may be stale
    sbClient.auth.getUser().then(function(_authPL){
      var _pUid = (_authPL && _authPL.data && _authPL.data.user) ? _authPL.data.user.id : safeLS('get','velo_user_id');
      if(!_pUid) return;
      safeLS('set','velo_user_id', _pUid);
      // Fetch current-month mood count from Supabase in background (cross-device sync)
      var _sbMonthPrefix = _curYear+'-'+String(_curMonth+1).padStart(2,'0');
      sbClient.from('mood_entries').select('date_key', {count:'exact', head:true})
        .eq('user_id', _pUid).like('date_key', _sbMonthPrefix+'%')
        .then(function(r){
          var sbMoodDays = (r && r.count != null) ? r.count : 0;
          _sbVerifiedMoodCount = sbMoodDays; // lock in Supabase value — stops localStorage from overriding
          _setEl('profileDays', sbMoodDays);
        }).catch(function(){});

      // Bitácora public post count
      sbClient.from('bitacora_posts').select('id',{count:'exact',head:true}).eq('user_id',_pUid).eq('is_anon',false)
        .then(function(r){ var el=document.getElementById('profileBitacoraCount'); if(el) el.textContent=(r&&r.count!=null)?r.count:0; })
        .catch(function(){});

      Promise.all([
        sbClient.from('guardian_requests').select('id', {count:'exact', head:true}).eq('guardian_id', _pUid).eq('status','ended'),
        sbClient.from('guardian_requests').select('id', {count:'exact', head:true}).eq('seeker_id',   _pUid).eq('status','ended'),
        sbClient.from('profiles').select('helped_count,received_count').eq('id', _pUid).maybeSingle()
      ]).then(function(results){
        var realH  = (results[0] && results[0].count  != null) ? results[0].count  : 0;
        var realR  = (results[1] && results[1].count  != null) ? results[1].count  : 0;
        var profH  = (results[2] && results[2].data   && results[2].data.helped_count)   ? parseInt(results[2].data.helped_count,  10) : 0;
        var profR  = (results[2] && results[2].data   && results[2].data.received_count) ? parseInt(results[2].data.received_count,10) : 0;
        var finalH = Math.max(realH, profH);
        var finalR = Math.max(realR, profR);
        safeLS('set','velo_guardian_convs', String(finalH));
        safeLS('set','velo_help_received',  String(finalR));
        if(finalH > profH) _bumpProfileCounter('helped_count',   finalH);
        if(finalR > profR) _bumpProfileCounter('received_count', finalR);
        _setEl('profileChats',    finalH + finalR);
        _setEl('profileHelped',   finalH);
        _setEl('profileReceived', finalR);
      }).catch(function(){});
    }).catch(function(){});
  }

  // Mi estado inputs — pre-fill from saved values
  var msEl = document.getElementById('profStatusMusic');
  var mbEl = document.getElementById('profStatusBook');
  var mfEl = document.getElementById('profStatusFilm');
  var mpEl = document.getElementById('profStatusPhrase');
  if(msEl) msEl.value = safeLS('get','velo_status_music')  || '';
  if(mbEl) mbEl.value = safeLS('get','velo_status_book')   || '';
  if(mfEl) mfEl.value = safeLS('get','velo_status_film')   || '';
  if(mpEl) mpEl.value = safeLS('get','velo_status_phrase') || '';

  // Sub status display
  var subEl = document.getElementById('subStatusDisplay');
  if(subEl){
    subEl.textContent = _isPremium() ? '✅ Velo Plus activo' : 'Sin suscripción activa';
    subEl.style.color = _isPremium() ? 'var(--sage)' : 'var(--ink4)';
  }

  // Incognito toggle
  var inc = document.getElementById('incognitoTog');
  if(inc){ var isInc = safeLS('get','velo_incognito')==='true'; inc.classList.toggle('on', isInc); }
  _initGuardianToggleUI();

  // Edit form pre-fill
  var en = document.getElementById('editName');
  var em = document.getElementById('editMotto');
  if(en) en.value = name;
  if(em) em.value = motto;

  // Reviews
  var rvEl = document.getElementById('profileReviews');
  if(rvEl){
    var myProfileId = safeLS('get','velo_user_id')||'';
    if(myProfileId){
      rvEl.innerHTML = '<p class="p-sm p-muted">Cargando reseñas…</p>';
      _loadUserReviews(myProfileId).then(function(revs){
        if(!revs.length){
          rvEl.innerHTML = '<div class="p-empty"><span class="p-empty-emoji">⭐</span><div class="p-empty-title">Aún no hay reseñas</div><div class="p-empty-sub">Las reseñas aparecerán después de tus sesiones</div></div>';
          return;
        }
        rvEl.innerHTML = _renderReviewsList(revs, myProfileId, myProfileId);
      });
    } else {
      rvEl.innerHTML = '<div class="p-empty"><span class="p-empty-emoji">⭐</span><div class="p-empty-title">Aún no hay reseñas</div><div class="p-empty-sub">Las reseñas aparecerán después de tus sesiones</div></div>';
    }
  }

  // Bitácora feed on own profile
  (function(){
    var btFeed = document.getElementById('profileBitacoraFeed');
    var btCard = document.getElementById('profileBitacoraCard');
    if(!btFeed) return;
    var _uid = safeLS('get','velo_user_id')||'';
    if(!_uid || !sbClient){ btFeed.innerHTML='<p class="p-sm p-muted">Inicia sesión para ver tus publicaciones.</p>'; return; }
    btFeed.innerHTML='<p class="p-sm p-muted">Cargando…</p>';
    sbClient.from('bitacora_posts').select('id,titulo,contenido,categoria,created_at')
      .eq('user_id',_uid).order('created_at',{ascending:false}).limit(50)
      .then(function(res){
        if(res.error||!res.data){ btFeed.innerHTML='<p class="p-sm p-muted">No se pudieron cargar las publicaciones.</p>'; return; }
        var posts = res.data;
        if(!posts.length){
          if(btCard) btCard.style.display='none';
          return;
        }
        if(btCard) btCard.style.display='';
        var _btCatLabel={apoyo:'🫂 Apoyo',superacion:'⭐ Superación',debate:'💬 Debate'};
        var _btCatColor={apoyo:'rgba(80,108,225,.70)',superacion:'rgba(188,138,14,.70)',debate:'rgba(44,154,94,.70)'};
        var _mkCard=function(p){
          var col=_btCatColor[p.categoria]||'rgba(116,198,157,.70)';
          var lbl=_btCatLabel[p.categoria]||p.categoria||'';
          var _pc=_btCleanContenido(p.contenido); var prev=_pc.slice(0,90)+(_pc.length>90?'…':'');
          var dateStr='';
          try{ var d=new Date(p.created_at); dateStr=d.toLocaleDateString('es',{day:'numeric',month:'short',year:'numeric'}); }catch(e){}
          return '<div onclick="_btOpenDetail(\''+_escHtml(String(p.id))+'\')" style="cursor:pointer;background:var(--sage7);border:1px solid var(--border);border-left:3px solid '+col+';border-radius:10px;padding:10px 12px;margin-bottom:6px">'
            +(p.titulo?'<div style="font-size:15px;font-weight:700;color:var(--ink);margin-bottom:3px">'+_escHtml(p.titulo)+'</div>':'')
            +'<div style="font-size:13px;color:var(--ink3);font-style:italic;line-height:1.5;margin-bottom:5px">'+_escHtml(prev)+'</div>'
            +'<div style="display:flex;align-items:center;justify-content:space-between">'
              +'<span style="font-size:11px;font-weight:700;color:'+col+';border-radius:20px;padding:2px 8px;background:var(--sage7);border:1px solid var(--border)">'+lbl+'</span>'
              +(dateStr?'<span style="font-size:12px;color:var(--ink5)">'+dateStr+'</span>':'')
            +'</div>'
            +'</div>';
        };
        var shown=posts.slice(0,3);
        var rest=posts.slice(3);
        var moreId='prBtMore';
        var html=shown.map(_mkCard).join('');
        if(rest.length){
          html+='<div id="'+moreId+'" style="display:none">'+rest.map(_mkCard).join('')+'</div>'
            +'<button onclick="var m=document.getElementById(\''+moreId+'\');if(!m)return;var op=m.style.display!==\'none\';m.style.display=op?\'none\':\'block\';this.textContent=op?\'Ver más ('+rest.length+') ↓\':\'Ver menos ↑\';" '
            +'style="background:none;border:none;color:var(--sage);font-size:14px;font-weight:600;cursor:pointer;padding:4px 0;font-family:\'Jost\',sans-serif">Ver más ('+rest.length+') ↓</button>';
        }
        btFeed.innerHTML=html;
      }).catch(function(){ btFeed.innerHTML='<p class="p-sm p-muted">Error cargando publicaciones.</p>'; });
  })();

  // Badges
  _renderBadgesGrid();
}

// Deletes all mood_entries from Supabase for the current user and clears localStorage.
// Addresses cross-account contamination where another account's moods were written under this uid.
async function pResetMyMoodData(){
  _pConfirm('¿Limpiar todos tus registros de ánimos de este dispositivo y Supabase? Esta acción no se puede deshacer.', async function(){
    _initSupabase();
    // Block _pushMissingMoodsToSb from re-uploading deleted data during and after this operation
    _moodResetPending = true;
    _moodSyncDone = true; // block background sync from fetching stale data during awaits
    var _authRM; try{ _authRM = await sbClient.auth.getUser(); }catch(e){}
    var _rmUid = (_authRM && _authRM.data && _authRM.data.user) ? _authRM.data.user.id : null;
    // 1. Delete from Supabase FIRST — before touching localStorage
    if(sbClient && _rmUid){
      try{
        var _countRes = await sbClient.from('mood_entries').select('date_key', {count:'exact', head:true}).eq('user_id', _rmUid);
        var _expectedCount = (_countRes && _countRes.count != null) ? _countRes.count : -1;
        var _delMoods = await sbClient.from('mood_entries').delete().eq('user_id', _rmUid).select('date_key');
        if(_delMoods && _delMoods.error){
          console.warn('[resetMoods] Supabase error — add DELETE policy: CREATE POLICY "delete_own_moods" ON mood_entries FOR DELETE USING (auth.uid() = user_id);');
          pToast('⚠️','Limpieza Supabase falló — intente de nuevo');
          _moodResetPending = false; _moodSyncDone = false; return;
        } else {
          var _deleted = (_delMoods.data || []).length;
          if(_deleted === 0 && _expectedCount > 0){
            console.warn('[resetMoods] DELETE blocked by RLS (expected '+_expectedCount+' rows).');
            pToast('⚠️','Limpieza Supabase bloqueada — agregá política DELETE');
            _moodResetPending = false; _moodSyncDone = false; return;
          }
        }
      }catch(e){
        pToast('⚠️','Error al conectar con Supabase');
        _moodResetPending = false; _moodSyncDone = false; return;
      }
    }
    // 2. Clear localStorage mood keys AFTER confirmed Supabase delete
    var _toRemove = [];
    for(var _ri = 0; _ri < localStorage.length; _ri++){
      var _rk = localStorage.key(_ri);
      if(_rk && _rk.startsWith('velo_mood_')) _toRemove.push(_rk);
    }
    _toRemove.forEach(function(k){ localStorage.removeItem(k); });
    safeLS('del','velo_mood_log');
    // Lock display at 0 — re-lock after awaits in case any in-flight callback overwrote it
    _sbVerifiedMoodCount = 0;
    _setEl('profileDays', 0);
    pToast('✅','Ánimos limpiados correctamente');
    _renderHomeWeekMoodGraph().catch(function(){});
    _updateHomeStreak();
  });
}

async function pSaveProfileStatus(){
  var music  = (document.getElementById('profStatusMusic')||{}).value  || '';
  var book   = (document.getElementById('profStatusBook')||{}).value   || '';
  var film   = (document.getElementById('profStatusFilm')||{}).value   || '';
  var phrase = (document.getElementById('profStatusPhrase')||{}).value || '';
  safeLS('set','velo_status_music',  music.trim());
  safeLS('set','velo_status_book',   book.trim());
  safeLS('set','velo_status_film',   film.trim());
  safeLS('set','velo_status_phrase', phrase.trim());
  _initSupabase();
  var uid = safeLS('get','velo_user_id');
  if(sbClient){
    try{
      var {data:_ps} = await sbClient.auth.getSession();
      if(_ps && _ps.session && _ps.session.user && _ps.session.user.id) uid = _ps.session.user.id;
    }catch(e){}
  }
  if(sbClient && uid){
    try{
      var updateRes = await sbClient.from('profiles').upsert({
        id: uid, status_music: music.trim(), status_book: book.trim(),
        status_film: film.trim(), status_phrase: phrase.trim()
      },{ onConflict:'id' });
      if(updateRes && updateRes.error){
        pToast('⚠️','Guardado solo en este dispositivo (error de red)');
        return;
      }
      pToast('✨','Estado actualizado y visible para todos 💚');
    }catch(e){
      pToast('⚠️','Guardado solo en este dispositivo (sin conexión)');
    }
  } else {
    pToast('✨', 'Estado actualizado 💚');
  }
}

async function pShowPublicProfile(){
  var name   = safeLS('get','velo_user_name')    || 'Usuario';
  var av     = safeLS('get','velo_user_av')      || '🧑';
  var motto  = safeLS('get','velo_user_motto')   || 'Mi camino, mi ritmo.';
  var music  = safeLS('get','velo_status_music') || '';
  var book   = safeLS('get','velo_status_book')  || '';
  var film   = safeLS('get','velo_status_film')  || '';
  var phrase = safeLS('get','velo_status_phrase')|| '';
  var isInc  = safeLS('get','velo_incognito') === 'true';
  var myId   = safeLS('get','velo_user_id') || '';
  var myRole = safeLS('get','velo_user_type') || 'user';
  var convs  = parseInt(safeLS('get','velo_guardian_convs')||'0', 10);

  // If status fields empty, fetch fresh from Supabase before rendering (cross-device sync)
  if(!isInc && !music && !book && !film && !phrase && myId){
    _initSupabase();
    if(sbClient){
      try{
        await _ensureSbSession();
        var _sr = await sbClient.from('profiles')
          .select('status_music,status_book,status_film,status_phrase,nombre,motto,avatar')
          .eq('id', myId).limit(1);
        if(!_sr.error && _sr.data && _sr.data.length){
          var _sp = _sr.data[0];
          if(_sp.status_music  != null){ safeLS('set','velo_status_music',  _sp.status_music);  music  = _sp.status_music||'';  }
          if(_sp.status_book   != null){ safeLS('set','velo_status_book',   _sp.status_book);   book   = _sp.status_book||'';   }
          if(_sp.status_film   != null){ safeLS('set','velo_status_film',   _sp.status_film);   film   = _sp.status_film||'';   }
          if(_sp.status_phrase != null){ safeLS('set','velo_status_phrase', _sp.status_phrase); phrase = _sp.status_phrase||''; }
          if(_sp.nombre)  { safeLS('set','velo_user_name',  _sp.nombre);  name  = _sp.nombre; }
          if(_sp.motto)   { safeLS('set','velo_user_motto', _sp.motto);   motto = _sp.motto;  }
          if(_sp.avatar)  { safeLS('set','velo_user_av',    _sp.avatar);  av    = _sp.avatar; }
        }
      }catch(e){}
    }
  }

  var badge  = _getBadge(convs);
  var displayName = isInc ? 'Anónimo/a 🎭' : _escHtml(name);
  var displayAv   = isInc ? '🎭' : av;

  var statusHtml = '';
  if(!isInc && (music || book || film || phrase)){
    statusHtml = '<div style="background:var(--sage7);border-radius:12px;padding:12px;margin-top:12px;font-size:15px;color:var(--ink3);line-height:1.9;text-align:left">';
    if(music)  statusHtml += '<div><span style="color:var(--ink4);font-size:14px">🎵 Música</span> · '+_escHtml(music)+'</div>';
    if(book)   statusHtml += '<div><span style="color:var(--ink4);font-size:14px">📚 Libro</span> · '+_escHtml(book)+'</div>';
    if(film)   statusHtml += '<div><span style="color:var(--ink4);font-size:14px">🎬 Película</span> · '+_escHtml(film)+'</div>';
    if(phrase) statusHtml += '<div style="font-style:italic;margin-top:4px;color:var(--sage2)">✨ &ldquo;'+_escHtml(phrase)+'&rdquo;</div>';
    statusHtml += '</div>';
  }

  var existing = document.getElementById('publicProfileOv');
  if(existing) existing.remove();
  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.id = 'publicProfileOv';
  ov.innerHTML = '<div class="p-sheet">'
    +'<div class="p-sheet-handle"></div>'
    +'<div style="text-align:center;padding:8px 0 16px">'
    +'<div style="font-size:64px;margin-bottom:10px;display:flex;justify-content:center">'+_avInline(displayAv,72)+'</div>'
    +'<div style="font-family:\'Cormorant Garamond\',serif;font-size:22px;color:var(--ink);margin-bottom:4px">'+displayName+'</div>'
    +'<div style="font-size:15px;color:var(--ink4);font-style:italic;margin-bottom:10px">'+_escHtml(motto)+'</div>'
    +'<span style="font-size:22px">'+badge.icon+'</span> <span style="font-size:14px;color:var(--ink4)">Guardián '+badge.name+'</span>'
    +statusHtml
    +(isInc ? '<div style="margin-top:12px;font-size:14px;color:var(--ink4);background:var(--cream2);border-radius:10px;padding:10px">🎭 Modo incógnito · tu nombre y avatar están ocultos</div>' : '')
    +'</div>'
    +'<div id="pubProfStats" style="margin:0 0 8px"></div>'
    +'<div id="pubProfReviews" style="margin:0 0 8px"></div>'
    +'<div id="pubProfBitacora" style="margin:0 0 12px"></div>'
    +'<button class="p-btn p-btn--secondary p-btn--md p-btn--full" onclick="document.getElementById(\'publicProfileOv\').remove()">Cerrar</button>'
    +'</div>';
  document.body.appendChild(ov);

  if(!myId) return;

  // Load guardian stats + reviews in parallel
  var statsPromise = (async function(){
    try{
      _initSupabase(); await _ensureSbSession();
      var rProf = await sbClient.from('profiles')
        .select('helped_count,received_count')
        .eq('id', myId).maybeSingle();
      var helped   = (rProf.data && rProf.data.helped_count)   ? parseInt(rProf.data.helped_count,10)   : convs;
      var received = (rProf.data && rProf.data.received_count) ? parseInt(rProf.data.received_count,10) : 0;
      return { helped: helped, received: received };
    }catch(e){ return { helped: convs, received: 0 }; }
  })();

  var reviewsPromise = myId ? _loadUserReviews(myId) : Promise.resolve([]);

  statsPromise.then(function(st){
    var el = document.getElementById('pubProfStats');
    if(!el) return;
    if(st.helped > 0 || st.received > 0){
      el.innerHTML = '<div style="display:flex;gap:8px;margin-bottom:8px">'
        +'<div style="flex:1;background:rgba(116,198,157,.08);border-radius:10px;padding:10px;text-align:center">'
        +'<div style="font-size:20px;font-weight:700;color:var(--sage2)">'+st.helped+'</div>'
        +'<div style="font-size:12px;color:var(--ink4);margin-top:2px">personas acompañadas</div></div>'
        +'<div style="flex:1;background:rgba(116,198,157,.08);border-radius:10px;padding:10px;text-align:center">'
        +'<div style="font-size:20px;font-weight:700;color:var(--sage2)">'+st.received+'</div>'
        +'<div style="font-size:12px;color:var(--ink4);margin-top:2px">veces que me apoyaron</div></div>'
        +'</div>';
    }
  }).catch(function(){});

  reviewsPromise.then(function(revs){
    var rvEl = document.getElementById('pubProfReviews');
    if(!rvEl) return;
    if(!revs.length) return;
    rvEl.innerHTML = '<div style="font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--ink4);margin-bottom:8px">⭐ RESEÑAS ('+revs.length+')</div>'
      +'<div style="max-height:220px;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;padding-right:2px">'
      + _renderReviewsList(revs, myId, myId)
      +'</div>';
  }).catch(function(){});

  // Load own public Bitácora posts
  if(!isInc && sbClient){
    (async function(){
      try{
        var btRes = await sbClient.from('bitacora_posts')
          .select('id,titulo,contenido,categoria,created_at,is_anon')
          .eq('user_id', myId).eq('is_anon', false)
          .order('created_at',{ascending:false}).limit(5);
        var btEl = document.getElementById('pubProfBitacora');
        if(!btEl) return;
        if(btRes.error || !btRes.data || !btRes.data.length) return;
        var _btCatLabel={apoyo:'🫂 Apoyo',superacion:'⭐ Superación',debate:'💬 Debate'};
        var _btCatColor={apoyo:'rgba(80,108,225,.70)',superacion:'rgba(188,138,14,.70)',debate:'rgba(44,154,94,.70)'};
        var shown=btRes.data.slice(0,3), rest=btRes.data.slice(3);
        var _moreId='ppBtMore'+Math.random().toString(36).slice(2,6);
        var _mkBtCard=function(p){
          var col=_btCatColor[p.categoria]||'rgba(116,198,157,.70)';
          var lbl=_btCatLabel[p.categoria]||p.categoria||'';
          var _pc=_btCleanContenido(p.contenido); var prev=_pc.slice(0,90)+(_pc.length>90?'…':'');
          return '<div onclick="_btOpenDetail(\''+_escHtml(String(p.id))+'\');document.getElementById(\'publicProfileOv\').remove()" '
            +'style="cursor:pointer;background:var(--sage7);border:1px solid var(--border);border-left:3px solid '+col+';border-radius:10px;padding:10px 12px;margin-bottom:6px">'
            +(p.titulo?'<div style="font-size:15px;font-weight:700;color:var(--ink);margin-bottom:3px">'+_escHtml(p.titulo)+'</div>':'')
            +'<div style="font-size:13px;color:var(--ink3);font-style:italic;line-height:1.5;margin-bottom:5px">'+_escHtml(prev)+'</div>'
            +'<span style="font-size:11px;font-weight:700;color:'+col+';background:rgba(255,255,255,.06);border-radius:20px;padding:2px 8px">'+lbl+'</span>'
            +'</div>';
        };
        btEl.innerHTML = '<div style="text-align:left">'
          +'<div style="font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--ink4);margin-bottom:8px">📖 EN BITÁCORA ('+btRes.data.length+')</div>'
          +shown.map(_mkBtCard).join('')
          +(rest.length
            ? '<div id="'+_moreId+'" style="display:none">'+rest.map(_mkBtCard).join('')+'</div>'
              +'<button onclick="var m=document.getElementById(\''+_moreId+'\');if(!m)return;var op=m.style.display!==\'none\';m.style.display=op?\'none\':\'block\';this.textContent=op?\'Ver más ('+rest.length+') ↓\':\'Ver menos ↑\';" style="background:none;border:none;color:var(--sage);font-size:14px;font-weight:600;cursor:pointer;padding:2px 0;font-family:\'Jost\',sans-serif">Ver más ('+rest.length+') ↓</button>'
            : '')
          +'</div>';
      }catch(e){}
    })();
  }
}

function _calcBadges(){
  var b = 0;
  var diary = []; try{ diary = JSON.parse(safeLS('get','velo_diary')||'[]'); }catch(e){}
  if(diary.length >= 1) b++;
  if(diary.length >= 7) b++;
  if(diary.length >= 30) b++;
  return b;
}

function _renderBadgesGrid(){
  var el = document.getElementById('profileBadgesGrid');
  if(!el) return;

  // Guardian badge section at top
  var convs = parseInt(safeLS('get','velo_guardian_convs')||'0', 10);
  var badge = _getBadge(convs);
  var progPct = badge.next ? Math.round((convs - (_getBadge(convs-1).needed !== badge.needed ? 0 : 0)) / (convs + badge.needed) * 100) : 100;
  // Simpler progress: based on range
  var ranges = {Novato:[0,5],Bronce:[5,20],Plata:[20,40],Oro:[40,100],Diamante:[100,100]};
  var r = ranges[badge.name] || [0,5];
  var progFill = badge.next ? Math.min(100, Math.round((convs - r[0]) / (r[1] - r[0]) * 100)) : 100;

  var tiers = [
    { name:'Novato',   icon:'🌱', min:0,   max:5,   color:'var(--sage4)', unlock:'Nivel inicial — podés pedir acompañamiento a otros guardianes' },
    { name:'Bronce',   icon:'🥉', min:5,   max:20,  color:'#C07840',      unlock:'Requiere: ingresar 5 días distintos a la app · Desbloqueá: insignia de Bronce en tu perfil' },
    { name:'Plata',    icon:'🥈', min:20,  max:40,  color:'#8892A4',      unlock:'Requiere: 20 conversaciones completadas · Desbloqueá: insignia verificada visible en la comunidad' },
    { name:'Oro',      icon:'🥇', min:40,  max:100, color:'#C8A200',      unlock:'Requiere: 40 conversaciones · Desbloqueá: crear Círculos de Paz ☮️ + prioridad en el listado' },
    { name:'Diamante', icon:'💎', min:100, max:100, color:'#7B68EE',      unlock:'Requiere: 100 conversaciones · Desbloqueá: estado top de la comunidad + 3 meses de Velo Plus gratis 🎁' }
  ];
  var tierRows = tiers.map(function(t){
    var reached = t.name === 'Bronce' ? _getVisitDayCount() >= 5 : convs >= t.min;
    var isCurrent = badge.name === t.name;
    var minLabel = t.name === 'Bronce' ? '' : (t.min > 0 ? t.min + ' conv.' : '');
    return '<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--border2)">'
      +'<span style="font-size:22px;opacity:'+(reached?1:.35)+'">'+t.icon+'</span>'
      +'<div style="flex:1;min-width:0">'
      +'<div style="font-size:14px;font-weight:700;color:'+(reached?'var(--ink)':'var(--ink5)')+'">'+t.name
      +(isCurrent?' <span style="font-size:12px;background:var(--sage6);color:var(--sage);border-radius:100px;padding:1px 7px;margin-left:4px">Actual</span>':'')
      +(minLabel?'  <span style="font-size:12px;color:var(--ink5)">'+minLabel+'</span>':'')+'</div>'
      +'<div style="font-size:13px;color:'+(reached?'var(--ink3)':'var(--ink5)')+'">'+t.unlock+'</div>'
      +'</div>'
      +(reached?'<span style="font-size:14px;color:var(--sage)">✅</span>':'<span style="font-size:14px;color:var(--ink5)">🔒</span>')
      +'</div>';
  }).join('');

  var guardianSection = '<div class="guardian-badge-card" style="margin-bottom:16px">'
    +'<div style="font-size:14px;font-weight:700;color:var(--sage);text-transform:uppercase;letter-spacing:1px;margin-bottom:12px">Mi nivel de Guardián</div>'
    +'<div style="display:flex;align-items:center;gap:14px;margin-bottom:12px">'
    +'<span style="font-size:44px">'+badge.icon+'</span>'
    +'<div style="flex:1">'
    +'<div style="font-size:18px;font-weight:800;color:var(--ink);margin-bottom:2px">Guardián '+badge.name+'</div>'
    +'<div style="font-size:14px;color:var(--ink4);margin-bottom:8px">'+convs+' conversaciones completadas</div>'
    +'<div class="guardian-badge-prog"><div class="guardian-badge-prog-fill" style="width:'+progFill+'%"></div></div>'
    +(badge.next
      ? '<div style="font-size:13px;color:var(--ink5);margin-top:4px">'+badge.needed+(badge.visitBased?' días':' conv.')+' más para <strong style="color:var(--sage2)">'+badge.next+'</strong></div>'
      : '<div style="font-size:13px;color:var(--sage);margin-top:4px">✨ Nivel máximo alcanzado</div>')
    +'</div>'
    +'</div>'
    +'<div style="font-size:13px;font-weight:700;color:var(--ink4);text-transform:uppercase;letter-spacing:.5px;margin-bottom:4px">Qué desbloquea cada nivel</div>'
    +tierRows
    +'</div>';

  var diary = []; try{ diary = JSON.parse(safeLS('get','velo_diary')||'[]'); }catch(e){}
  var _badgeUid = _myUserId ? _myUserId() : (safeLS('get','velo_user_id')||'');
  var _badgeHKey = _badgeUid ? 'velo_happy_history_'+_badgeUid : 'velo_happy_history';
  var happyPosts = []; try{ happyPosts = JSON.parse(safeLS('get',_badgeHKey)||safeLS('get','velo_happy')||'[]'); }catch(e){}
  var daysActive = Math.ceil((Date.now()-(parseInt(safeLS('get','velo_registered_ts')||Date.now(),10)))/86400000);
  // Count total days with registered mood (up to last 365)
  var moodDaysTotal = 0;
  var moodStreak = 0;
  (function(){
    var d = new Date();
    var streakBroken = false;
    for(var mi=0; mi<365; mi++){
      var mk = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
      if(safeLS('get','velo_mood_'+mk)){
        moodDaysTotal++;
        if(!streakBroken) moodStreak++;
      } else if(mi > 0) {
        streakBroken = true;
      }
      d.setDate(d.getDate()-1);
    }
  }());
  var badges = [
    { icon:'🌱', name:'Primer Paso',      desc:'Crear tu cuenta',                              done:true,            prog:100 },
    { icon:'📔', name:'Escribiendo',       desc:'Primera entrada en el diario',                 done:!!diary.length,  prog:diary.length?100:0 },
    { icon:'🌈', name:'En Movimiento',     desc:'Registrar tu ánimo 7 días',                   done:moodDaysTotal>=7, prog:Math.min(100,Math.round(moodDaysTotal/7*100)) },
    { icon:'💙', name:'Corazón Abierto',   desc:'Participar en Sala de Ayuda',                 done:!!safeLS('get','velo_helped_once'), prog:safeLS('get','velo_helped_once')?100:0 },
    { icon:'⭐', name:'Constancia',        desc:'30 días en la comunidad',                     done:daysActive>=30,  prog:Math.min(100,Math.round(daysActive/30*100)) },
    { icon:'🦋', name:'Transformación',    desc:'Completar onboarding',                        done:!!safeLS('get','velo_onboarding_done'), prog:safeLS('get','velo_onboarding_done')?100:0 },
    { icon:'🌊', name:'Mensaje al Mar',    desc:'Enviar tu primer mensaje al Mar',             done:parseInt(safeLS('get','velo_bottle_count')||safeLS('get','velo_total_bottles')||'0',10)>0 || JSON.parse(safeLS('get','velo_my_bottles')||'[]').length>0, prog:null },
    { icon:'🤝', name:'Primer Apoyo',      desc:'Acompañar a alguien en Sala de Ayuda',       done:!!safeLS('get','velo_helped_once') && parseInt(safeLS('get','velo_helped_others')||'0',10)>0, prog:null },
    { icon:'🌻', name:'Muro en Flor',      desc:'Primera publicación en el Muro',              done:happyPosts.length>0, prog:happyPosts.length?100:0 },
    { icon:'💬', name:'Conversador/a',     desc:'Enviar 10 mensajes en chats',                 done:parseInt(safeLS('get','velo_total_msgs')||'0',10)>=10, prog:Math.min(100,Math.round(parseInt(safeLS('get','velo_total_msgs')||'0',10)/10*100)) },
    { icon:'🧘', name:'Momento de Calma', desc:'Completar la sesión de respiración',          done:!!safeLS('get','velo_breathed_once'), prog:safeLS('get','velo_breathed_once')?100:0 },
    { icon:'🌟', name:'Velo Plus',         desc:'Suscribirse a Velo Plus',                     done:safeLS('get','velo_plan')==='plus', prog:safeLS('get','velo_plan')==='plus'?100:0 },
    { icon:'🏡', name:'En Comunidad',      desc:'7 días activo en la app',                     done:daysActive>=7,   prog:Math.min(100,Math.round(daysActive/7*100)) },
    { icon:'🗓️', name:'Semana Completa',   desc:'Abrir la app 7 días distintos',               done:_getVisitDayCount()>=7, prog:Math.min(100,Math.round(_getVisitDayCount()/7*100)) }
  ];
  el.innerHTML = guardianSection + badges.map(function(b){
    var progPct = b.done ? 100 : (b.prog != null ? b.prog : 0);
    return '<div class="p-badge-row" style="opacity:'+(b.done?1:(progPct>0?.75:.45))+'"><div class="p-badge-ic" style="background:'+(b.done?'var(--sage7)':'var(--cream2)')+'">'+b.icon+'</div><div style="flex:1;min-width:0"><div style="font-size:15px;font-weight:700;color:var(--ink)">'+b.name+'</div><div style="font-size:13px;color:var(--ink4)">'+b.desc+'</div><div class="p-badge-prog-track"><div class="p-badge-prog-fill" style="width:'+progPct+'%;background:'+(b.done?'var(--sage2)':'var(--sage4)')+'"></div></div></div>'+(b.done?'<span style="font-size:16px">✅</span>':'<span style="font-size:14px;color:var(--ink5)">🔒</span>')+'</div>';
  }).join('');
}

function switchProfileTab(tab, btn){
  document.querySelectorAll('.p-tab').forEach(function(t){ t.classList.remove('active'); });
  document.querySelectorAll('.p-tab-content').forEach(function(c){ c.classList.remove('active'); });
  if(btn) btn.classList.add('active');
  var content = document.getElementById('tab-'+tab);
  if(content) content.classList.add('active');
}

