          +'<div style="font-size:13px;color:var(--ink4);line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden">'+_escHtml((r.reply||'').slice(0,120))+'</div>'
