// One-time migration: push all locally-known shown/deleted broadcast IDs to Supabase so
// messages handled before v529 (before per-action sync was added) don't re-appear on new devices.
// Updates _syncedReadIds synchronously so _buzónPollOnce immediately has the correct state.
function _migrateBcastLocalToSb(){
  if(safeLS('get','velo_bcast_sb_push_v5')) return;
  safeLS('set','velo_bcast_sb_push_v5','1'); // set flag immediately to prevent double-run
  // Collect all locally-known broadcast IDs synchronously and write them to
  // velo_bcast_read_* so pRenderInbox's new filter catches them immediately
  var newIds = [];
  function _addMigrId(bid){
    if(!bid || _syncedReadIds[bid]) return;
    _syncedReadIds[bid] = 1;
    safeLS('set','velo_bcast_read_'+bid,'1'); // ensure render filter sees it now
    newIds.push(bid);
  }
  try{
    var shown = JSON.parse(safeLS('get','velo_bcast_shown') || '{}');
    Object.keys(shown).forEach(function(bid){ _addMigrId(bid); });
  }catch(e){}
  try{
    Object.keys(localStorage).forEach(function(k){
      if(k.indexOf('velo_bcast_read_') === 0) _addMigrId(k.replace('velo_bcast_read_',''));
    });
  }catch(e){}
  try{
    var del = JSON.parse(safeLS('get','velo_inbox_deleted') || '[]');
    del.forEach(function(id){
      if(id && id.indexOf('bc_') === 0) _addMigrId(id.replace('bc_',''));
      else if(id && id.indexOf('rp_') === 0) _addMigrId(id);
      else if(id === 'm1' || id === 'm2') _addMigrId(id);
      else if(id && id.indexOf('survey-') === 0){ safeLS('set','velo_read_'+id,'1'); _addMigrId(id); }
    });
  }catch(e){}
  // Also migrate completed/dismissed surveys stored as velo_read_survey-* keys
  try{
    Object.keys(localStorage).forEach(function(k){
      if(k.indexOf('velo_read_survey-') === 0){
        var sid2 = k.replace('velo_read_','');
        if(safeLS('get',k) === '1') _addMigrId(sid2);
      }
    });
  }catch(e){}
  if(!newIds.length) return;
  // Async push to Supabase — SELECT first to merge, not overwrite
  _initSupabase();
  if(!sbClient) return;
  (async function(){
    try{
      var ok = await _ensureSbSession();
      if(!ok) return;
      var uid = safeLS('get','velo_user_id');
      if(!uid) return;
      var cur = await sbClient.from('profiles').select('read_bcast_ids').eq('id',uid).limit(1);
      if(!cur.error && cur.data && cur.data[0] && Array.isArray(cur.data[0].read_bcast_ids)){
        cur.data[0].read_bcast_ids.forEach(function(id){ if(id) _syncedReadIds[id] = 1; });
      }
      var merged = Object.keys(_syncedReadIds);
      if(!cur.error){
        var r = await sbClient.from('profiles').update({read_bcast_ids: merged}).eq('id', uid);
        if(r && r.error) console.warn('[migrate bcast] profiles UPDATE error:', r.error.message);
      }
      // Always also save to auth.user_metadata
      try{ await sbClient.auth.updateUser({ data: { read_bcast_ids: merged } }); }catch(e){}
    }catch(e){}
  })();
}

// Persist a broadcast ID as read/deleted to localStorage and Supabase profiles.read_bcast_ids.
// SELECTs the current array first and MERGES before updating, so concurrent deletes on
// different devices never overwrite each other.
function _syncBroadcastRead(bcId){
  if(!bcId) return;
  safeLS('set','velo_bcast_read_'+bcId,'1');
  _syncedReadIds[bcId] = 1;
  _initSupabase();
  if(!sbClient) return;
  (async function(){
    try{
      var ok = await _ensureSbSession();
      if(!ok){ console.warn('[sync bcast] no session — delete not synced to Supabase'); return; }
      // Always use auth.getUser() — localStorage uid may be stale/wrong (cross-account bug)
      var {data:_authBR} = await sbClient.auth.getUser();
      if(!_authBR || !_authBR.user){ console.warn('[sync bcast] no auth user'); return; }
      var uid = _authBR.user.id;
      safeLS('set','velo_user_id', uid);
      if(!uid){ console.warn('[sync bcast] no uid — delete not synced to Supabase'); return; }
      // SELECT first — merge remote IDs so we never overwrite another device's deletions
      var cur = await sbClient.from('profiles').select('read_bcast_ids').eq('id',uid).limit(1);
      var _profilesColOk = false;
      if(cur.error){
        console.warn('[sync bcast] profiles SELECT error:', cur.error.message, 'code:', cur.error.code);
        // Also check auth.user_metadata for IDs saved by fallback path
        try{
          var _ar0 = await sbClient.auth.getUser();
          var _meta0 = _ar0 && _ar0.data && _ar0.data.user && _ar0.data.user.user_metadata;
          if(_meta0 && Array.isArray(_meta0.read_bcast_ids)){
            _meta0.read_bcast_ids.forEach(function(id){ if(id) _syncedReadIds[id] = 1; });
          }
        }catch(e){}
      } else {
        _profilesColOk = true;
        if(cur.data && cur.data[0] && Array.isArray(cur.data[0].read_bcast_ids)){
          cur.data[0].read_bcast_ids.forEach(function(id){ if(id) _syncedReadIds[id] = 1; });
        }
      }
      var merged = Object.keys(_syncedReadIds);
      // Save to profiles if column exists, always save to auth.user_metadata as fallback
      if(_profilesColOk){
        var r = await sbClient.from('profiles').update({read_bcast_ids: merged}).eq('id', uid);
        if(r && r.error){
          console.warn('[sync bcast] profiles UPDATE error:', r.error.message, 'code:', r.error.code);
          _profilesColOk = false;
        } else {
          console.log('[sync bcast] ✓ profiles.read_bcast_ids saved', merged.length, 'IDs');
        }
      }
      // Always save to auth.user_metadata (works even if profiles column missing)
      try{
        var _ar = await sbClient.auth.updateUser({ data: { read_bcast_ids: merged } });
        if(_ar.error) console.warn('[sync bcast] auth.updateUser error:', _ar.error.message);
        else console.log('[sync bcast] ✓ auth.user_metadata saved', merged.length, 'IDs' + (_profilesColOk ? '' : ' (profiles column missing — using auth fallback)'));
      }catch(e){ console.warn('[sync bcast] auth.updateUser exception:', e); }
    }catch(e){ console.warn('[sync bcast] exception:', e); }
  })();
}

function pDeleteInboxMsg(id, el){
  var del = []; try{ del = JSON.parse(safeLS('get','velo_inbox_deleted')||'[]'); }catch(e){}
  if(del.indexOf(id) < 0){ del.push(id); safeLS('set','velo_inbox_deleted', JSON.stringify(del)); }
  var inbox = []; try{ inbox = JSON.parse(safeLS('get','velo_inbox')||'[]'); }catch(e){}
  var newInbox = inbox.filter(function(m){ return m.id !== id; });
  if(newInbox.length !== inbox.length){ safeLS('set','velo_inbox', JSON.stringify(newInbox)); }
  if(el){ var card = el.closest('.p-inbox-msg'); if(card) card.remove(); }
  _updateHomeBell();
  if(id && id.indexOf('bc_') === 0) _syncBroadcastRead(id.replace('bc_',''));
  else if(id && id.indexOf('rp_') === 0) _syncBroadcastRead(id);
  else if(id === 'm1' || id === 'm2') _syncBroadcastRead(id);
  else if(id && id.indexOf('survey-') === 0){
    safeLS('set','velo_read_'+id,'1');
    safeLS('set','velo_last_survey', String(Date.now())); // 90-day cooldown on dismiss
    _syncBroadcastRead(id);
  }
}

function pInboxVaciar(){
  _pConfirm('¿Vaciar el buzón? Se eliminarán todos los mensajes visibles.', function(){
    var el = document.getElementById('inboxList');
    if(!el) return;
    var del = []; try{ del = JSON.parse(safeLS('get','velo_inbox_deleted')||'[]'); }catch(e){}
    el.querySelectorAll('.p-inbox-msg[data-mid]').forEach(function(c){
      var id = c.getAttribute('data-mid'); if(!id) return;
      if(del.indexOf(id) < 0) del.push(id);
      if(id.indexOf('bc_') === 0) _syncBroadcastRead(id.replace('bc_',''));
      else if(id.indexOf('rp_') === 0) _syncBroadcastRead(id);
      else if(id === 'm1' || id === 'm2') _syncBroadcastRead(id);
      else if(id.indexOf('survey-') === 0){ safeLS('set','velo_read_'+id,'1'); safeLS('set','velo_last_survey',String(Date.now())); _syncBroadcastRead(id); }
    });
    safeLS('set','velo_inbox_deleted', JSON.stringify(del));
    safeLS('set','velo_inbox', JSON.stringify([]));
    safeLS('set','velo_inbox_cleared_at', Date.now().toString());
    pRenderInbox();
  });
}

function pOpenBroadcastMsg(readKey, subject, body, senderName, fecha, rowEl, senderId, senderAv, senderUsername){
  safeLS('set', readKey, '1');
  if(rowEl){ rowEl.classList.remove('unread'); var dot = rowEl.querySelector('.p-inbox-dot'); if(dot) dot.remove(); }
  _updateHomeBell();
  // Persist read state to Supabase so new devices don't re-show this message as unread
  _syncBroadcastRead(readKey.replace('velo_bcast_read_',''));
  var existing = document.getElementById('inboxBcOv');
  if(existing) existing.remove();

  var isIdentified = !!(senderId && senderName && senderName !== 'Velo — Al Mar' && senderName.indexOf('Velo') !== 0);
  var uname = senderUsername ? '@'+senderUsername : (isIdentified ? '@'+(senderName||'').toLowerCase().replace(/\s+/g,'_').slice(0,16) : '');
  var isFav = isIdentified && pGetFavs().some(function(f){ return f.id === senderId; });

  var senderCard = isIdentified
    ? '<div style="display:flex;align-items:center;gap:12px;background:var(--cream2);border:1.5px solid var(--border2);border-radius:16px;padding:12px 14px;margin-bottom:16px">'
      +'<div style="position:relative;flex-shrink:0;cursor:pointer" onclick="pQuickProfile('+_jsAttr(senderName)+','+_jsAttr(senderAv||'🧑')+',\'\',\'\','+_jsAttr(senderId)+')">'
      +_avInline(senderAv||'🧑', 48)
      +'</div>'
      +'<div style="flex:1;min-width:0">'
      +'<div style="font-size:14px;font-weight:700;color:var(--ink);cursor:pointer;margin-bottom:2px" onclick="pQuickProfile('+_jsAttr(senderName)+','+_jsAttr(senderAv||'🧑')+',\'\',\'\','+_jsAttr(senderId)+')">'+_escHtml(senderName)+'</div>'
      +(uname ? '<div style="font-size:13px;color:var(--sage3);font-weight:600">'+_escHtml(uname)+'</div>' : '')
      +'<div style="font-size:12px;color:var(--ink5);margin-top:2px">'+_escHtml(fecha||'')+'</div>'
      +'</div>'
      +'<div style="display:flex;flex-direction:column;gap:6px;flex-shrink:0">'
      +'<button onclick="pQuickProfile('+_jsAttr(senderName)+','+_jsAttr(senderAv||'🧑')+',\'\',\'\','+_jsAttr(senderId)+')" style="padding:5px 10px;background:var(--sage7);border:1.5px solid var(--sage4);border-radius:100px;font-size:13px;font-weight:700;color:var(--sage);cursor:pointer;font-family:\'Jost\',sans-serif;white-space:nowrap">Ver perfil</button>'
      +'<button id="bcFavBtn" onclick="'+(isFav?'pRemoveFav(\''+_escHtml(senderId)+'\')':'pAddFav('+_jsAttr(senderId)+','+_jsAttr(senderName)+','+_jsAttr(senderAv||'🧑')+')')+';this.textContent=\''+(isFav?'☆ Favorito':'⭐ Guardado')+'\';pToast(\''+(isFav?'☆':'⭐')+'\',\''+(isFav?'Quitado de favoritos':'¡Guardado como favorito!')+'\')" style="padding:5px 10px;background:rgba(255,200,50,'+(isFav?'.18':'.08')+');border:1.5px solid rgba(255,200,50,'+(isFav?'.45':'.25')+');border-radius:100px;font-size:13px;font-weight:700;color:'+(isFav?'#c8a040':'var(--ink4)')+';cursor:pointer;font-family:\'Jost\',sans-serif;white-space:nowrap">'+(isFav?'⭐ Guardado':'☆ Favorito')+'</button>'
      +'</div></div>'
    : '<div style="display:flex;align-items:center;gap:10px;margin-bottom:16px">'
      +'<div style="font-size:30px;width:46px;height:46px;border-radius:14px;background:var(--sage7);display:flex;align-items:center;justify-content:center;flex-shrink:0">🌊</div>'
      +'<div><div style="font-size:14px;font-weight:700;color:var(--sage)">Alguien de la comunidad</div>'
      +'<div style="font-size:13px;color:var(--ink5)">'+_escHtml(fecha||'')+'</div></div>'
      +'</div>';

  var replyBtn = isIdentified
    ? '<button class="p-btn p-btn--primary p-btn--md p-btn--full" style="margin-bottom:8px" onclick="document.getElementById(\'inboxBcOv\').remove();pLeaveOfflineMsg('+_jsAttr(senderId)+','+_jsAttr(senderName)+','+_jsAttr(senderAv||'🧑')+')">💌 Responder</button>'
    : '';

  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.id = 'inboxBcOv';
  ov.innerHTML = '<div class="p-sheet" style="max-height:88vh;overflow-y:auto">'
    +'<div class="p-sheet-handle"></div>'
    +senderCard
    +'<h2 style="font-family:\'Cormorant Garamond\',serif;font-size:20px;color:var(--ink);margin-bottom:14px;line-height:1.3">'+_escHtml(subject)+'</h2>'
    +(body ? '<div style="font-size:14px;color:var(--ink3);line-height:1.85;white-space:pre-line;background:var(--cream2);border-radius:12px;padding:16px;margin-bottom:16px">'+_escHtml(body)+'</div>' : '')
    // Velo logo signature — always shown on official broadcasts
    +'<div style="display:flex;align-items:center;gap:10px;border-top:1px solid var(--border2);padding-top:14px;margin-bottom:18px">'
    +'<div style="height:28px;width:72px;background:url(\'assets/logo.png\') left center / contain no-repeat;opacity:.55" class="r-velo-sig-logo"></div>'
    +'<div style="font-size:13px;color:var(--ink5);line-height:1.4">Velo · Acompañamiento emocional entre pares<br><span style="font-size:12px;opacity:.6">Mensaje oficial del equipo de Velo</span></div>'
    +'</div>'
    +replyBtn
    +'<button class="p-btn p-btn--secondary p-btn--md p-btn--full" onclick="document.getElementById(\'inboxBcOv\').remove()">Cerrar</button>'
    +'</div>';
  document.body.appendChild(ov);
  ov.addEventListener('click', function(e){ if(e.target===ov) ov.remove(); });
}

function pOpenInboxMsg(msgId, rowEl){
  var msgs = []; try{ msgs = JSON.parse(safeLS('get','velo_inbox')||'[]'); }catch(e){}
  var mockMsgs = [
    { id:'m1', icon:'💚', remitente:'Equipo Velo', asunto:'¡Bienvenido/a a Velo!', cuerpo:'Gracias por unirte a nuestra comunidad. Aquí encontrarás apoyo, personas que escuchan y herramientas de bienestar.\n\nSi en algún momento sentís que necesitás hablar, accedé a la Sala de Guardianes o la Sala de Ayuda. Estamos acá para vos. 🌿', fecha:'Hoy' },
    { id:'m2', icon:'🌿', remitente:'Velo', asunto:'Consejo del día', cuerpo:'Está bien no estar bien. El primer paso es reconocerlo. Cuidarte a vos mismo/a no es egoísmo, es necesidad. 💙', fecha:'Hoy' }
  ];
  var all = msgs.concat(mockMsgs);
  var msg = all.find(function(m){ return m.id === msgId; });
  if(!msg) return;
  // Mark as read
  safeLS('set','velo_read_'+msgId,'1');
  var localMsgs = msgs.map(function(m){ return m.id === msgId ? Object.assign({},m,{leido:true}) : m; });
  safeLS('set','velo_inbox', JSON.stringify(localMsgs));
  if(rowEl){ rowEl.classList.remove('unread'); var dot = rowEl.querySelector('.p-inbox-dot'); if(dot) dot.remove(); }
  _updateHomeBell();
  // Persist read state to Supabase (same pool as broadcast IDs) for cross-device sync
  if(msgId) _syncBroadcastRead(msgId);
  // Show full message modal
  var existing = document.getElementById('inboxMsgOv');
  if(existing) existing.remove();
  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.id = 'inboxMsgOv';
  ov.innerHTML = '<div class="p-sheet" style="max-height:88vh;overflow-y:auto">'
    +'<div class="p-sheet-handle"></div>'
    +'<div style="display:flex;align-items:center;gap:12px;margin-bottom:16px">'
    +'<div style="font-size:30px;width:46px;height:46px;border-radius:14px;background:var(--sage7);display:flex;align-items:center;justify-content:center;flex-shrink:0">'+msg.icon+'</div>'
    +'<div><div style="font-size:14px;font-weight:700;color:var(--sage)">'+_escHtml(msg.remitente||'Velo')+'</div>'
    +'<div style="font-size:13px;color:var(--ink5)">'+_escHtml(msg.fecha||'')+'</div></div>'
    +'</div>'
    +'<h2 style="font-family:\'Cormorant Garamond\',serif;font-size:21px;color:var(--ink);margin-bottom:16px;line-height:1.3">'+_escHtml(msg.asunto)+'</h2>'
    +(msg.cuerpo ? '<div style="font-size:14px;color:var(--ink3);line-height:1.85;white-space:pre-line;background:var(--cream2);border-radius:12px;padding:16px;margin-bottom:20px">'+_escHtml(msg.cuerpo)+'</div>' : '')
    +(msg.tipo==='pro-msg' && msg.proId ? '<button class="p-btn p-btn--primary p-btn--lg p-btn--full" style="margin-bottom:8px" onclick="document.getElementById(\'inboxMsgOv\').remove();pReplyToProMsg(\''+_escHtml(msg.proId)+'\',\''+_escHtml(msg.proName||msg.remitente||'Pro')+'\',\''+_escHtml(msg.remitente||'Pro')+'\')">💬 Responder</button>' : '')
    +'<button class="p-btn p-btn--secondary p-btn--md p-btn--full" onclick="document.getElementById(\'inboxMsgOv\').remove()">Cerrar</button>'
    +'</div>';
  document.body.appendChild(ov);
  ov.addEventListener('click', function(e){ if(e.target===ov) ov.remove(); });
}

