    +(allowReply ? '<button class="p-btn p-btn--primary p-btn--lg p-btn--full" style="margin-bottom:8px" onclick="document.getElementById(\'inboxAdminReplyOv\').remove();pReplyToAdmin('+_jsAttr(topic||'')+')">💬 Responder</button>' : '')
