function pReplyToAdmin(originalTopic){
  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.id = 'replyToAdminOv';
  ov.innerHTML = '<div class="p-sheet">'
    +'<div class="p-sheet-handle"></div>'
    +'<div style="font-family:\'Cormorant Garamond\',serif;font-size:20px;color:var(--ink);margin-bottom:4px">Responder a Velo</div>'
    +'<p style="font-size:14px;color:var(--ink4);margin-bottom:14px">Tu respuesta llegará al equipo. Asunto: <strong>Re: '+_escHtml(originalTopic)+'</strong></p>'
    +'<textarea class="p-textarea" id="replyToAdminTa" rows="4" placeholder="Escribí tu respuesta..."></textarea>'
    +'<div style="height:12px"></div>'
    +'<button class="p-btn p-btn--primary p-btn--lg p-btn--full" onclick="pSendReplyToAdmin(\''+_escHtml(originalTopic).replace(/'/g,"\\'")+'\')">Enviar 💌</button>'
    +'<div style="height:8px"></div>'
    +'<button class="p-btn p-btn--secondary p-btn--md p-btn--full" onclick="document.getElementById(\'replyToAdminOv\').remove()">Cancelar</button>'
    +'</div>';
  document.body.appendChild(ov);
  ov.addEventListener('click', function(e){ if(e.target===ov) ov.remove(); });
}

async function pSendReplyToAdmin(originalTopic){
  var ta = document.getElementById('replyToAdminTa');
  if(!ta || !ta.value.trim()){ pToast('✍️','Escribí tu respuesta antes de enviar'); return; }
  var texto = ta.value.trim();
  var email = safeLS('get','velo_user_email') || '';
  var name  = safeLS('get','velo_user_name') || '';
  var topic = 'Re: ' + (originalTopic || 'Consulta');
  var btn = document.querySelector('#replyToAdminOv .p-btn--primary');
  if(btn){ btn.disabled = true; btn.textContent = 'Enviando...'; }
  try{
    var ok = await sbSaveContact(topic, texto, email);
    if(ok || !email){
      var existing = document.getElementById('replyToAdminOv');
      if(existing) existing.remove();
      pToast('💌','Respuesta enviada al equipo Velo');
    } else {
      pToast('⚠️','Error al enviar. Intentá de nuevo.');
    }
  } catch(e){ pToast('⚠️','Error de conexión'); }
  finally{ if(btn){ btn.disabled=false; btn.textContent='Enviar 💌'; } }
}

async function pQuickProfile(name, av, bio, guardianId, userId){
  var isAnon = !name || name === 'Usuario Anónimo' || name === 'Anónimo' || name === 'Guardián Anónimo';
  var uid = userId || (guardianId ? guardianId.replace('live_','') : '');

  // Show the sheet immediately with a loading state, then enrich
  var existing = document.getElementById('quickProfileOv');
  if(existing) existing.remove();
  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.id = 'quickProfileOv';
  ov.innerHTML = '<div class="p-sheet" style="max-height:88vh;overflow-y:auto">'
    +'<div class="p-sheet-handle"></div>'
    +'<div id="qpBody" style="text-align:center;padding:30px 0;color:var(--ink5);font-size:15px">Cargando perfil…</div>'
    +'</div>';
  document.body.appendChild(ov);
  ov.addEventListener('click', function(e){ if(e.target===ov) ov.remove(); });

  // Fetch full profile + reviews + accurate session counts
  var prof = null, reviews = [], _qpHelped = 0, _qpReceived = 0, _qpBtPosts = [];
  if(uid && !isAnon){
    _initSupabase();
    if(sbClient){
      try{
        var pr = await sbClient.from('profiles').select('*').eq('id', uid).limit(1);
        if(pr.data && pr.data.length) prof = pr.data[0];
      }catch(e){}
      // Seed from profiles columns (always available, may be slightly stale)
      _qpHelped   = (prof && prof.helped_count)   ? parseInt(prof.helped_count,10)   : 0;
      _qpReceived = (prof && prof.received_count) ? parseInt(prof.received_count,10) : 0;
      // Use RPC to bypass RLS and get accurate counts from guardian_requests.
      // Direct table queries on guardian_requests are blocked by RLS when viewing
      // another user's data — the RPC runs SECURITY DEFINER so it can count freely.
      try{
        var rpc = await sbClient.rpc('get_user_session_counts', { p_user_id: uid });
        if(!rpc.error && rpc.data && rpc.data.length){
          var rpcH = parseInt(rpc.data[0].helped,  10) || 0;
          var rpcR = parseInt(rpc.data[0].received,10) || 0;
          if(rpcH > _qpHelped)   _qpHelped   = rpcH;
          if(rpcR > _qpReceived) _qpReceived = rpcR;
          // Write back to profiles so future reads are fast (no RPC needed)
          if(rpcH > (prof && prof.helped_count   ? parseInt(prof.helped_count,10)   : 0))
            sbClient.from('profiles').update({helped_count:rpcH}).eq('id',uid).then(function(){}).catch(function(){});
          if(rpcR > (prof && prof.received_count ? parseInt(prof.received_count,10) : 0))
            sbClient.from('profiles').update({received_count:rpcR}).eq('id',uid).then(function(){}).catch(function(){});
        }
      }catch(e){}
      reviews = await _loadUserReviews(uid);
      // Load public Bitácora posts (non-anonymous) for the profile
      try{
        var btRes = await sbClient.from('bitacora_posts_full')
          .select('id,titulo,contenido,categoria,created_at')
          .eq('user_id', uid).eq('is_anon', false)
          .order('created_at',{ascending:false}).limit(4);
        if(!btRes.error && btRes.data) _qpBtPosts = btRes.data;
      }catch(e){}
    }
  }
  var body = document.getElementById('qpBody');
  if(!body) return; // sheet was closed

  var dispName     = isAnon ? 'Usuario Anónimo' : ((prof && prof.nombre) || name || 'Usuario');
  var dispAv       = isAnon ? '👤' : ((prof && prof.avatar) || av || '🧑');
  var dispUsername = (!isAnon && prof && prof.username) ? prof.username : '';
  var motto        = (!isAnon && prof && prof.motto) ? prof.motto : (isAnon ? '' : (bio||''));
  var isFav    = uid ? pIsFav(uid) : false;
  var presence = (uid && !isAnon) ? _presenceInfo(uid) : null;

  var helped   = _qpHelped;
  var received = _qpReceived;
  // Use profile owner's visit days (not the viewer's) for accurate badge tier
  var profVisitDays = (prof && prof.visit_day_count) ? parseInt(prof.visit_day_count,10) : 0;
  var badge    = _getBadge(helped, profVisitDays);

  // Status block — same format as "Como me ven"
  var statusLines = '';
  if(prof && !isAnon){
    if(prof.status_music)  statusLines += '<div><span style="color:var(--ink4);font-size:14px">🎵 Música</span> · '+_escHtml(prof.status_music)+'</div>';
    if(prof.status_book)   statusLines += '<div><span style="color:var(--ink4);font-size:14px">📚 Libro</span> · '+_escHtml(prof.status_book)+'</div>';
    if(prof.status_film)   statusLines += '<div><span style="color:var(--ink4);font-size:14px">🎬 Película</span> · '+_escHtml(prof.status_film)+'</div>';
    if(prof.status_phrase) statusLines += '<div style="font-style:italic;margin-top:4px;color:var(--sage2)">✨ &ldquo;'+_escHtml(prof.status_phrase)+'&rdquo;</div>';
  }
  var likes = statusLines
    ? '<div style="background:var(--sage7);border-radius:12px;padding:12px;margin-bottom:12px;font-size:15px;color:var(--ink3);line-height:1.9;text-align:left">'+statusLines+'</div>'
    : '';

  var counters = (!isAnon && prof)
    ? '<div style="display:flex;gap:8px;margin-bottom:12px">'
      +'<div style="flex:1;background:rgba(116,198,157,.08);border-radius:10px;padding:10px;text-align:center">'
      +'<div style="font-size:20px;font-weight:700;color:var(--sage2)">'+helped+'</div>'
      +'<div style="font-size:12px;color:var(--ink4);margin-top:2px">personas acompañadas</div></div>'
      +'<div style="flex:1;background:rgba(116,198,157,.08);border-radius:10px;padding:10px;text-align:center">'
      +'<div style="font-size:20px;font-weight:700;color:var(--sage2)">'+received+'</div>'
      +'<div style="font-size:12px;color:var(--ink4);margin-top:2px">veces que lo/la apoyaron</div></div>'
      +'</div>'
    : '';
  var _qpMyId = _myUserId();
  var revHtml = reviews.length
    ? '<div style="text-align:left;margin-bottom:12px">'
      +'<div style="font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--ink4);margin-bottom:8px">⭐ RESEÑAS ('+reviews.length+')</div>'
      +'<div style="max-height:220px;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;padding-right:2px">'
      + _renderReviewsList(reviews, _qpMyId, userId||'')
      +'</div>'
      +'</div>'
    : '';

  var _showFavBtn = !isAnon && uid && uid !== _qpMyId;
  body.style.cssText = '';
  body.innerHTML =
    '<div style="text-align:center;padding:6px 0 16px">'
    +'<div style="position:relative;display:inline-block;margin-bottom:10px">'
    +'<div style="font-size:60px;display:flex;justify-content:center">'+_avInline(dispAv,72)+'</div>'
    +(presence ? '<span style="position:absolute;bottom:3px;right:3px;width:15px;height:15px;border-radius:50%;background:'+presence.color+';border:2.5px solid var(--cream)"></span>' : '')
    +'</div>'
    +'<div style="font-family:\'Cormorant Garamond\',serif;font-size:22px;color:var(--ink);margin-bottom:2px">'+_escHtml(dispName)+'</div>'
    +(dispUsername ? '<div style="font-size:14px;color:var(--ink4);margin-bottom:6px;font-family:Jost,sans-serif;letter-spacing:.2px">@'+_escHtml(dispUsername)+'</div>' : '')
    +(motto ? '<div style="font-size:15px;color:var(--ink4);font-style:italic;margin-bottom:10px">'+_escHtml(motto)+'</div>' : '')
    +(!isAnon ? '<div><span style="font-size:20px">'+badge.icon+'</span> <span style="font-size:14px;color:var(--ink4)">Guardián '+badge.name+'</span></div>' : '')
    +(presence ? '<div style="font-size:13px;color:'+(presence.on?presence.color:'var(--ink5)')+';margin-top:6px">● '+presence.label+'</div>' : '')
    +'</div>'
    + likes + counters + revHtml
    // ── Bitácora posts section (always shown with count, even if 0) ──
    +(!isAnon ? (function(){
      var _btCatLabel = {apoyo:'🫂 Apoyo',superacion:'⭐ Superación',debate:'💬 Debate'};
      var _btCatColor = {apoyo:'rgba(80,108,225,.70)',superacion:'rgba(188,138,14,.70)',debate:'rgba(44,154,94,.70)'};
      var sorted = (_qpBtPosts||[]).slice().sort(function(a,b){
        return new Date(b.created_at||0) - new Date(a.created_at||0);
      });
      var shown = sorted.slice(0,3);
      var rest  = sorted.slice(3);
      var _moreId = 'qpBtMore'+Math.random().toString(36).slice(2,6);
      var _makeCard = function(p){
        var col = _btCatColor[p.categoria]||'rgba(116,198,157,.70)';
        var lbl = _btCatLabel[p.categoria]||p.categoria||'';
        var _pc2=_btCleanContenido(p.contenido); var prev = _pc2.slice(0,90)+(_pc2.length>90?'…':'');
        return '<div onclick="_btOpenDetail(\''+_escHtml(String(p.id))+'\');document.getElementById(\'quickProfileOv\').remove()" style="cursor:pointer;background:var(--sage7);border:1px solid var(--border);border-left:3px solid '+col+';border-radius:10px;padding:10px 12px;margin-bottom:6px">'
          +(p.titulo?'<div style="font-size:15px;font-weight:700;color:var(--ink);margin-bottom:3px">'+_escHtml(p.titulo)+'</div>':'')
          +'<div style="font-size:13px;color:var(--ink3);font-style:italic;line-height:1.5;margin-bottom:5px">'+_escHtml(prev)+'</div>'
          +'<span style="font-size:11px;font-weight:700;color:'+col+';background:rgba(255,255,255,.06);border-radius:20px;padding:2px 8px">'+lbl+'</span>'
          +'</div>';
      };
      var n = sorted.length;
      return '<div style="text-align:left;margin-bottom:14px">'
        +'<div style="font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--ink4);margin-bottom:8px">📖 EN BITÁCORA ('+n+')</div>'
        +(n===0
          ? '<div style="background:var(--sage7);border:1px dashed var(--border);border-radius:10px;padding:14px;text-align:center;font-size:13px;color:var(--ink4);font-style:italic">Sin historias publicadas aún</div>'
          : shown.map(_makeCard).join('')
            +(rest.length
              ? '<div id="'+_moreId+'" style="display:none">'+rest.map(_makeCard).join('')+'</div>'
                +'<button onclick="var m=document.getElementById(\''+_moreId+'\');if(!m)return;var op=m.style.display!==\'none\';m.style.display=op?\'none\':\'block\';this.textContent=op?\'Ver más ('+rest.length+') ↓\':\'Ver menos ↑\';" style="background:none;border:none;color:var(--sage);font-size:14px;font-weight:600;cursor:pointer;padding:2px 0;font-family:\'Jost\',sans-serif">Ver más ('+rest.length+') ↓</button>'
              : ''))
        +'</div>';
    })() : '')
    // ── Action buttons ───────────────────────────────────────────
    +(guardianId&&!isAnon ? '<button class="p-btn p-btn--primary p-btn--lg p-btn--full" onclick="document.getElementById(\'quickProfileOv\').remove();pOpenGuardian('+_jsAttr(guardianId)+')">Solicitar acompañamiento 💚</button><div style="height:8px"></div>' : '')
    +(!isAnon && uid ? '<button class="p-btn p-btn--secondary p-btn--sm p-btn--full" onclick="pOpenDM('+_jsAttr(uid)+','+_jsAttr(dispName)+','+_jsAttr(dispAv)+');document.getElementById(\'quickProfileOv\').remove()">💬 Enviar mensaje</button><div style="height:8px"></div>' : '')
    +(_showFavBtn ? '<button id="qpFavBtn" class="p-btn p-btn--secondary p-btn--md p-btn--full" onclick="pToggleFavFromProfile('+_jsAttr(uid)+','+_jsAttr(dispName)+','+_jsAttr(dispAv)+')" style="background:'+(isFav?'rgba(255,200,50,.18)':'')+';">'+(isFav?'⭐ En favoritos':'☆ Agregar a favoritos')+'</button><div style="height:8px"></div>' : '')
    +(!isAnon && uid && uid !== _qpMyId ? '<button class="p-btn p-btn--secondary p-btn--sm p-btn--full" onclick="pBlockUser('+_jsAttr(uid)+','+_jsAttr(dispName)+')" style="color:rgba(220,120,120,.85);border-color:rgba(220,120,120,.30);background:rgba(220,120,120,.06)">🚫 Bloquear usuario</button><div style="height:8px"></div>' : '')
    +'<button class="p-btn p-btn--secondary p-btn--md p-btn--full" onclick="document.getElementById(\'quickProfileOv\').remove()">Cerrar</button>';
}

// ── FAVOURITES SYSTEM ─────────────────────────────────────────

function pGetFavs(){
  if(_favsList === null){
    try{ _favsList = JSON.parse(safeLS('get','velo_favs')||'[]'); }catch(e){ _favsList = []; }
  }
  return _favsList;
}

async function _syncFavsFromSupabase(){
  var myId = safeLS('get','velo_user_id')||'';
  _initSupabase();
  if(!myId || !sbClient) return;
  try{
    var {data, error} = await sbClient.from('user_favorites').select('*').eq('user_id', myId).order('created_at',{ascending:false}).limit(100);
    if(error){ console.error('[syncFavs] query error:', error.message); return; }
    if(!data) return;
    if(!data.length){
      // No remote favs — ensure local cache is clean but don't wipe user's localStorage
      return;
    }
    // Clean up stale self-favorites left in DB before our client-side guard was added
    var selfRows = data.filter(function(r){ return r.fav_id === myId; });
    if(selfRows.length){
      sbClient.from('user_favorites').delete().eq('user_id', myId).eq('fav_id', myId).then(function(){}).catch(function(){});
    }
    // Don't re-add IDs the user explicitly removed (tombstone list)
    var _rmList = []; try{ _rmList = JSON.parse(safeLS('get','velo_favs_removed')||'[]'); }catch(e){}
    // Build local list, filtering out self-favs AND tombstoned IDs
    var local = pGetFavs().filter(function(f){ return f.id !== myId && _rmList.indexOf(f.id) < 0; });
    var localIds = local.map(function(f){ return f.id; });
    // Add remote favs not yet in local, excluding self and locally-deleted
    data.forEach(function(r){
      if(r.fav_id !== myId && localIds.indexOf(r.fav_id) < 0 && _rmList.indexOf(r.fav_id) < 0){
        local.push({ id:r.fav_id, name:r.fav_name||'Usuario', av:r.fav_av||'🧑', ts:new Date(r.created_at).getTime() });
      }
    });
    _favsList = local;
    safeLS('set','velo_favs', JSON.stringify(local.slice(0,100)));
    _updateFavBadge();

    // Resolve real names for any fav stored as 'Usuario' or empty
    var needsName = local.filter(function(f){ return !f.name || f.name === 'Usuario'; });
    if(needsName.length && sbClient){
      try{
        var nIds = needsName.map(function(f){ return f.id; });
        var {data:pd} = await sbClient.from('profiles').select('id,nombre,avatar,username').in('id', nIds);
        if(pd && pd.length){
          var dirty = false;
          pd.forEach(function(p){
            var real = p.nombre || (p.username ? '@'+p.username : '');
            if(!real) return;
            _favsList.forEach(function(f){
              if(f.id === p.id){
                f.name = real;
                if(p.avatar && (!f.av || f.av === '🧑')) f.av = p.avatar;
                dirty = true;
              }
            });
            // Update DB so next sync loads the real name
            sbClient.from('user_favorites').update({ fav_name:real, fav_av:p.avatar||'' })
              .eq('user_id', myId).eq('fav_id', p.id)
              .then(function(){}).catch(function(){});
          });
          if(dirty) safeLS('set','velo_favs', JSON.stringify(_favsList.slice(0,100)));
        }
      }catch(e){}
    }
  }catch(e){}
}

function pIsFav(userId){
  return pGetFavs().some(function(f){ return f.id === userId; });
}

function pAddFav(userId, name, av){
  var _myId = safeLS('get','velo_user_id')||'';
  if(!userId || userId === _myId || pIsFav(userId)) return;
  // Clear tombstone — if re-adding a previously removed fav, _syncFavsFromSupabase
  // would otherwise filter them back out because their ID is still in velo_favs_removed.
  try{
    var _rmKey='velo_favs_removed';
    var _rmList=JSON.parse(safeLS('get',_rmKey)||'[]');
    var _rmIdx=_rmList.indexOf(userId);
    if(_rmIdx>=0){ _rmList.splice(_rmIdx,1); safeLS('set',_rmKey,JSON.stringify(_rmList)); }
  }catch(e){}
  var favs = pGetFavs();
  favs.unshift({ id:userId, name:name||'Usuario', av:av||'🧑', ts:Date.now() });
  _favsList = favs;
  safeLS('set','velo_favs', JSON.stringify(favs.slice(0,100)));
  // Persist to Supabase
  _initSupabase();
  if(sbClient){
    var myId = safeLS('get','velo_user_id')||'';
    if(myId) sbClient.from('user_favorites').upsert(
      { user_id:myId, fav_id:userId, fav_name:name||'', fav_av:av||'', created_at:new Date().toISOString() },
      { onConflict:'user_id,fav_id' }
    ).then(function(res){
      if(res && res.error) console.error('[pAddFav] upsert error:', res.error.message);
    }).catch(function(e){ console.error('[pAddFav] upsert exception:', e); });
  }
  pToast('⭐',_escHtml(name||'Usuario')+' guardado en favoritos');
  _updateFavBadge();
}

async function pRemoveFav(userId){
  var favs = pGetFavs().filter(function(f){ return f.id !== userId; });
  _favsList = favs;
  safeLS('set','velo_favs', JSON.stringify(favs));
  // Track removed IDs so _syncFavsFromSupabase doesn't re-add them before the delete propagates
  var _rmKey = 'velo_favs_removed';
  var _rmList = []; try{ _rmList = JSON.parse(safeLS('get',_rmKey)||'[]'); }catch(e){}
  if(_rmList.indexOf(userId) < 0){ _rmList.push(userId); }
  safeLS('set', _rmKey, JSON.stringify(_rmList.slice(0,200)));
  pToast('✓','Eliminado de favoritos');
  _updateFavBadge();
  _initSupabase();
  if(sbClient){
    var myId = safeLS('get','velo_user_id')||'';
    if(myId){
      try{
        var _delRes = await sbClient.from('user_favorites').delete().eq('user_id',myId).eq('fav_id',userId);
        if(_delRes && _delRes.error) console.error('[removeFav]', _delRes.error.message, 'myId='+myId, 'fav='+userId);
      }catch(e){ console.error('[removeFav exception]', e); }
    }
  }
}

function pToggleGuardianFav(){
  if(!_curGuardian) return;
  var uid = (_curGuardian.id||'').replace('live_','');
  var name = _curGuardian.name||'Guardián';
  var av = _curGuardian.av||'🌿';
  if(pIsFav(uid)){ pRemoveFav(uid); } else { pAddFav(uid, name, av); }
  var btn = document.getElementById('gdFavBtn');
  if(btn){ btn.textContent = pIsFav(uid) ? '⭐' : '☆'; btn.style.background = pIsFav(uid) ? 'rgba(255,200,50,.25)' : 'rgba(255,200,50,.15)'; }
}

function pToggleFavFromProfile(userId, name, av){
  if(pIsFav(userId)){ pRemoveFav(userId); } else { pAddFav(userId, name, av); }
  var btn = document.getElementById('qpFavBtn');
  if(btn){
    var nowFav = pIsFav(userId);
    btn.textContent = nowFav ? '⭐ En favoritos' : '☆ Agregar a favoritos';
    btn.style.background    = nowFav ? 'rgba(255,200,50,.2)'  : 'rgba(255,200,50,.07)';
    btn.style.borderColor   = nowFav ? 'rgba(255,200,50,.5)'  : 'rgba(255,200,50,.25)';
    btn.style.color         = nowFav ? '#b88000' : 'var(--ink4)';
  }
}

function pBlockUser(userId, name, av){
  _pConfirm('¿Bloquear a '+(name||'este usuario')+'? Sus publicaciones dejarán de aparecer.', function(){
  var blocked = []; try{ blocked = JSON.parse(safeLS('get','velo_blocked')||'[]'); }catch(e){}
  if(blocked.indexOf(userId)<0){ blocked.push(userId); safeLS('set','velo_blocked', JSON.stringify(blocked)); }
  var bd = []; try{ bd = JSON.parse(safeLS('get','velo_blocked_data')||'[]'); }catch(e){}
  if(!bd.find(function(b){ return b.id===userId; })){
    bd.push({id:userId, name:name||'Usuario', av:av||'🧑'});
    safeLS('set','velo_blocked_data', JSON.stringify(bd));
  }
  // Sync to Supabase so the blocked user silently stops seeing us in their contacts
  var myId = _myUserId();
  if(sbClient && myId && myId !== 'guest'){
    sbClient.from('user_blocks').upsert({blocker_id:myId, blocked_id:userId}, {onConflict:'blocker_id,blocked_id'})
      .then(function(){}).catch(function(){});
  }
  pRemoveFav(userId);
  pToast('🚫','Usuario bloqueado');
  });
}

function pUnblockUser(userId){
  var blocked = []; try{ blocked = JSON.parse(safeLS('get','velo_blocked')||'[]'); }catch(e){}
  blocked = blocked.filter(function(id){ return id !== userId; });
  safeLS('set','velo_blocked', JSON.stringify(blocked));
  var bd = []; try{ bd = JSON.parse(safeLS('get','velo_blocked_data')||'[]'); }catch(e){}
  bd = bd.filter(function(b){ return b.id !== userId; });
  safeLS('set','velo_blocked_data', JSON.stringify(bd));
  // Sync removal to Supabase so the unblocked user can see us again
  var myId = _myUserId();
  if(sbClient && myId && myId !== 'guest'){
    sbClient.from('user_blocks').delete().eq('blocker_id',myId).eq('blocked_id',userId)
      .then(function(){}).catch(function(){});
  }
  pToast('✅','Usuario desbloqueado');
  pRenderContacts();
}

function _isBlocked(userId){
  var blocked = []; try{ blocked = JSON.parse(safeLS('get','velo_blocked')||'[]'); }catch(e){}
  return blocked.indexOf(userId) >= 0;
}

function _updateFavBadge(){
  var total  = parseInt(safeLS('get','velo_fav_me_count')||'0', 10);
  var seen   = parseInt(safeLS('get','velo_fav_me_seen') ||'0', 10);
  var newN   = Math.max(0, total - seen);
  var badge  = document.getElementById('favCountBadge');
  if(badge){ badge.textContent = newN > 0 ? newN : ''; badge.style.display = newN > 0 ? 'inline' : 'none'; }
}

// ── CONTACTS PAGE ─────────────────────────────────────────────

function _contactCard(id, name, av, uname, pInfo, unread, opts){
  var canChat = pInfo.on && pInfo.label !== 'Ocupado/a';
  var sz = opts.small ? 44 : 52;
  var _uc = _userColor(id || name);
  var accent = _uc.border;
  var accentBg = _uc.badge;
  var accentGlow = _uc.glow;
  var accentStrip = _uc.strip.replace(/[\d.]+\)$/, '0.85)');
  var onlineColor = pInfo.on ? (pInfo.label==='En línea'||pInfo.label==='Disponible'?'#4DD988':'#D9A940') : 'rgba(128,135,130,.55)';
  var onlineBg = pInfo.on ? (pInfo.label==='En línea'||pInfo.label==='Disponible'?'rgba(38,120,75,.18)':'rgba(160,118,28,.15)') : 'rgba(120,128,124,.08)';
  var bs = 'width:34px;height:34px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:16px;cursor:pointer;flex-shrink:0';
  return '<div class="vcc-card" data-fav-name="'+_escHtml(name||'')+'" data-fav-uname="'+_escHtml(uname||'')+'" '
    +'style="display:flex;align-items:stretch;border-left:4px solid '+accentStrip+';border-radius:18px;margin-bottom:9px;overflow:hidden">'
    +'<div style="display:flex;align-items:center;gap:12px;padding:12px 12px 12px 10px;flex:1;min-width:0">'
    +'<div style="position:relative;flex-shrink:0;cursor:pointer" onclick="pQuickProfile('+_jsAttr(name||'Usuario')+','+_jsAttr(av||'🧑')+',\'\',\'\','+_jsAttr(id)+')">'
    +'<div style="width:'+sz+'px;height:'+sz+'px;border-radius:50%;border:2.5px solid '+accent+';overflow:hidden;display:flex;align-items:center;justify-content:center;background:'+accentBg+';box-shadow:0 0 14px '+accentGlow+'">'+_avInline(av||'🧑', sz)+'</div>'
    +'<span style="position:absolute;bottom:0;right:0;width:13px;height:13px;border-radius:50%;background:'+onlineColor+';border:2.5px solid white"></span>'
    +'</div>'
    +'<div style="flex:1;min-width:0">'
    +'<div class="vcc-name" style="font-size:15.5px;font-weight:800;font-family:Jost,sans-serif;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:.1px">'+_escHtml(name||'Usuario')+'</div>'
    +(uname?'<div style="font-size:13px;font-weight:600;margin-bottom:3px;font-family:Jost,sans-serif;color:'+accent.replace(/[\d.]+\)$/,'0.78)')+'">'+_escHtml(uname)+'</div>':'')
    +'<div style="display:inline-flex;align-items:center;gap:4px;background:'+onlineBg+';border-radius:100px;padding:2px 8px 2px 5px;margin-top:2px">'
    +'<span style="width:6px;height:6px;border-radius:50%;background:'+onlineColor+';flex-shrink:0"></span>'
    +'<span style="font-size:11px;font-weight:700;color:'+onlineColor+';font-family:Jost,sans-serif;letter-spacing:.2px">'+pInfo.label+'</span>'
    +'</div>'
    +(opts.motto?'<p class="vcc-motto" style="font-size:12px;line-height:1.4;margin:5px 0 0;font-family:\'Cormorant Garamond\',serif;font-style:italic;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">"'+_escHtml(opts.motto)+'"</p>':'')
    +'</div>'
    +'<div style="display:flex;flex-direction:column;gap:4px;flex-shrink:0;justify-content:center;padding-left:4px">'
    +(canChat
      ?'<button onclick="pOpenDM('+_jsAttr(id)+','+_jsAttr(name)+','+_jsAttr(av)+')" title="Chat" style="'+bs+';background:'+accentBg+';border:1.5px solid '+accent+';box-shadow:0 2px 10px '+accentGlow+'">💬</button>'
      :'<button disabled title="No disponible para chat" style="'+bs+';background:rgba(130,130,130,.13);border:1.5px solid rgba(130,130,130,.30);cursor:not-allowed;filter:grayscale(1);opacity:.52">💬</button>')
    +'<div style="display:flex;gap:4px">'
    +(opts.showMail?'<button onclick="pLeaveOfflineMsg('+_jsAttr(id)+','+_jsAttr(name)+','+_jsAttr(av)+')" title="Buzón" style="'+bs+';width:auto;padding:0 8px;background:rgba(200,158,50,.12);border:1px solid rgba(215,168,55,.34)">✉️</button>':'')
    +(opts.showRemove?'<button onclick="pRemoveFav(\''+id+'\');pRenderContacts()" title="Quitar fav" style="'+bs+';width:auto;padding:0 8px;background:rgba(232,182,36,.12);border:1px solid rgba(232,182,36,.36)">⭐</button>':'')
    +(opts.showBlock?'<button onclick="pBlockUser('+_jsAttr(id)+','+_jsAttr(name)+','+_jsAttr(av||'🧑')+');pRenderContacts()" title="Bloquear" style="'+bs+';width:auto;padding:0 8px;background:rgba(192,38,38,.08);border:1px solid rgba(192,38,38,.26)">🚫</button>':'')
    +(opts.showAddFav?'<button onclick="pAddFav('+_jsAttr(id)+','+_jsAttr(name)+','+_jsAttr(av||'🧑')+');pRenderContacts()" title="Agregar fav" style="'+bs+';width:auto;padding:0 8px;background:rgba(116,198,157,.14);border:1px solid rgba(116,198,157,.38)">⭐</button>':'')
    +'</div>'
    +'</div>'
    +'</div></div>';
}

async function pRenderContacts(){
  var _tok = _navToken;
  var el = document.getElementById('contactsContent');
  if(!el) return;
  try{ await _ensureSbSession(); }catch(e){}
  if(_navToken !== _tok || !document.getElementById('contactsContent')) return;
  // Sync favorites from Supabase before reading — ensures cross-device data and
  // catches cases where the 3.5s startup timer hasn't fired yet.
  try{ await _syncFavsFromSupabase(); }catch(e){}
  if(_navToken !== _tok || !document.getElementById('contactsContent')) return;

  try {
  var myId = safeLS('get','velo_user_id')||'';
  var favs = pGetFavs().filter(function(f){ return f.id !== myId; });

  _initSupabase();
  var favMeRows = [];
  if(sbClient && myId){
    try{
      var fmRes = await sbClient.from('user_favorites').select('user_id,created_at').eq('fav_id', myId).order('created_at',{ascending:false}).limit(50);
      if(_navToken !== _tok) return;
      favMeRows = (fmRes.data || []).filter(function(r){ return r.user_id !== myId; });
      safeLS('set','velo_fav_me_count', String(favMeRows.length));
      safeLS('set','velo_fav_me_seen',  String(favMeRows.length));
      _updateFavBadge();
    }catch(e){}
  }

  // Batch-fetch real usernames + names + avatars for all contacts
  var usernameMap = {};
  var profileMap  = {};  // id → {name, av}
  if(sbClient){
    var _allIds = favs.map(function(f){ return f.id; }).concat(favMeRows.map(function(r){ return r.user_id; })).filter(Boolean);
    var _uniqIds = _allIds.filter(function(id,i){ return _allIds.indexOf(id)===i; });
    if(_uniqIds.length){
      try{
        var profRes = await sbClient.from('profiles').select('id,username,nombre,avatar,motto').in('id', _uniqIds);
        if(_navToken !== _tok) return;
        (profRes.data||[]).forEach(function(p){
          if(p.id && p.username){ usernameMap[p.id] = p.username; _uFill(p.id, p.username); }
          if(p.id) profileMap[p.id] = { name: p.nombre || (p.username ? '@'+p.username : ''), av: p.avatar||'', motto: p.motto||'' };
        });
      }catch(e){}
    }
  }

  // Cross-user block filter — silently hide contacts who have blocked me
  if(sbClient && myId && (favs.length || favMeRows.length)){
    try{
      var _cIds = favs.map(function(f){ return f.id; }).concat(favMeRows.map(function(r){ return r.user_id; })).filter(function(id,i,a){ return id&&a.indexOf(id)===i; });
      if(_cIds.length){
        var blRes = await sbClient.from('user_blocks').select('blocker_id').eq('blocked_id', myId).in('blocker_id', _cIds);
        if(_navToken !== _tok) return;
        var _hid = {}; (blRes.data||[]).forEach(function(r){ _hid[r.blocker_id]=1; });
        favs = favs.filter(function(f){ return !_hid[f.id]; });
        favMeRows = favMeRows.filter(function(r){ return !_hid[r.user_id]; });
      }
    }catch(e){}
  }

  await _refreshPresenceCache();
  if(_navToken !== _tok) return;

  var unreadIds = {}; try{ unreadIds = JSON.parse(safeLS('get','velo_dm_unread')||'{}'); }catch(e){}

  // Build online list (favs + fans, deduped, only online)
  var _onlineMap = {};
  favs.forEach(function(f){ var pi=_presenceInfo(f.id); if(pi.on){ var _pm=profileMap[f.id]||{}; _onlineMap[f.id]={id:f.id,name:_pm.name||f.name,av:_pm.av||f.av||'🧑',uname:usernameMap[f.id]||f.username||'',pInfo:pi,unread:unreadIds[f.id]||0,isFav:true}; } });
  favMeRows.forEach(function(r){ var pi=_presenceInfo(r.user_id); if(pi.on&&!_onlineMap[r.user_id]){ var _fp=profileMap[r.user_id]||{}; _onlineMap[r.user_id]={id:r.user_id,name:_fp.name||usernameMap[r.user_id]||'Usuario',av:_fp.av||'🧑',uname:usernameMap[r.user_id]||'',pInfo:pi,unread:0,isFav:false}; } });
  var onlineList = Object.keys(_onlineMap).map(function(k){ return _onlineMap[k]; });

  // Blocked list
  var _bIds = []; try{ _bIds=JSON.parse(safeLS('get','velo_blocked')||'[]'); }catch(e){}
  var _bData = []; try{ _bData=JSON.parse(safeLS('get','velo_blocked_data')||'[]'); }catch(e){}
  var blockedList = _bIds.map(function(id){ return _bData.find(function(b){ return b.id===id; })||{id:id,name:'Usuario',av:'🧑'}; });

  var tabs = [
    {id:'favs',    label:'⭐ Favoritos',     count:favs.length},
    {id:'online',  label:'● Online',         count:onlineList.length},
    {id:'fans',    label:'♥ Me agregaron',   count:favMeRows.length}
  ];
  tabs.push({id:'blocked', label:'🚫 Bloqueados', count:blockedList.length});

  // ── Tab bar ──
  var tabsHtml = '<div class="r-contacts-tabs">'
    +tabs.map(function(t,i){
      return '<button class="r-ctab'+(i===0?' active':'')+'" id="ctab-'+t.id+'" onclick="pContactsTab(\''+t.id+'\')">'
        +(t.id==='online'?'<span style="color:#5BBF87;font-size:13px">●</span> Online':'')
        +(t.id!=='online'?t.label:'')
        +'<span class="r-ctab-count">'+t.count+'</span>'
        +'</button>';
    }).join('')
    +'</div>';

  // ── Favs content ──
  var favsHtml = '<div id="contacts-favs">'
    +(!favs.length
      ? '<div class="p-empty"><span class="p-empty-emoji">⭐</span><div class="p-empty-title">Sin favoritos aún</div><div class="p-empty-sub">Agregá personas como favoritas para verlas aquí.</div></div>'
      : favs.map(function(f){
          var pi=_presenceInfo(f.id); var uname=usernameMap[f.id]?'@'+usernameMap[f.id]:(f.username?'@'+f.username:'');
          // Prefer resolved name from profiles over stale localStorage value
          var prof = profileMap[f.id] || {};
          var dName = (prof.name && prof.name !== 'Usuario') ? prof.name : (f.name && f.name !== 'Usuario' ? f.name : (uname.replace('@','')||'Usuario'));
          var dAv   = prof.av || f.av || '🧑';
          // Silently update local cache with the real name so widget also benefits
          if(prof.name && prof.name !== 'Usuario' && f.name !== prof.name){ f.name = prof.name; f.av = dAv; _favsList = pGetFavs(); safeLS('set','velo_favs',JSON.stringify(_favsList.slice(0,100))); }
          return _contactCard(f.id,dName,dAv,uname,pi,unreadIds[f.id]||0,{showMail:true,showRemove:true,showBlock:true,motto:prof.motto||''});
        }).join(''))
    +'</div>';

  // ── Online content ──
  var onlineHtml = '<div id="contacts-online" style="display:none">'
    +(!onlineList.length
      ? '<div class="p-empty"><span class="p-empty-emoji">💤</span><div class="p-empty-title">Nadie conectado ahora</div><div class="p-empty-sub">Aquí verás a tus favoritos y fans cuando estén online.</div></div>'
      : onlineList.map(function(u){
          var uname=u.uname?'@'+u.uname:'';
          return _contactCard(u.id,u.name,u.av,uname,u.pInfo,u.unread,{showMail:true,showAddFav:!u.isFav,showBlock:u.isFav,showRemove:u.isFav});
        }).join(''))
    +'</div>';

  // ── Fans content ──
  var fansHtml = '<div id="contacts-fans" style="display:none">'
    +(!favMeRows.length
      ? '<div class="p-empty"><span class="p-empty-emoji">♥</span><div class="p-empty-title">Nadie te agregó aún</div></div>'
      : favMeRows.map(function(r){
          var pi=_presenceInfo(r.user_id);
          var uname=usernameMap[r.user_id]?'@'+usernameMap[r.user_id]:'';
          var prof=profileMap[r.user_id]||{};
          var dName = prof.name || uname.replace('@','') || 'Usuario';
          var dAv   = prof.av  || '🧑';
          return _contactCard(r.user_id,dName,dAv,uname,pi,0,{small:true,showAddFav:!pIsFav(r.user_id),showBlock:true,showMail:true});
        }).join(''))
    +'</div>';

  // ── Blocked content ──
  var blockedHtml = '<div id="contacts-blocked" style="display:none">'
    +(!blockedList.length
      ? '<div class="p-empty"><span class="p-empty-emoji">🚫</span><div class="p-empty-title">Sin usuarios bloqueados</div><div class="p-empty-sub">Cuando bloqueés a alguien aparecerá aquí y podrás desbloquearlo.</div></div>'
      : '<div style="font-size:13px;color:var(--ink5);margin-bottom:12px;font-style:italic">Podés desbloquear a cualquier persona en cualquier momento.</div>'
        +blockedList.map(function(b){
          return '<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:var(--cream);border-radius:14px;margin-bottom:8px;border:1.5px solid rgba(200,50,50,.15);opacity:.75">'
            +'<div style="flex-shrink:0;filter:grayscale(1);opacity:.7">'+_avInline(b.av||'🧑',36)+'</div>'
            +'<div style="flex:1;min-width:0"><div style="font-size:15px;font-weight:700;color:var(--ink)">'+_escHtml(b.name||'Usuario')+'</div>'
            +'<div style="font-size:13px;color:var(--ink5)">Bloqueado/a</div></div>'
            +'<button onclick="pUnblockUser('+_jsAttr(b.id)+')" style="padding:6px 12px;background:rgba(116,198,157,.12);border:1.5px solid rgba(116,198,157,.35);border-radius:10px;font-size:14px;font-weight:700;color:var(--sage);cursor:pointer;flex-shrink:0">Desbloquear</button>'
            +'</div>';
        }).join('')
    )
    +'</div>';

  el.innerHTML = tabsHtml + favsHtml + onlineHtml + fansHtml + blockedHtml;
  } catch(e) {
    console.error('[pRenderContacts]', e);
    var elFb = document.getElementById('contactsContent');
    if(elFb) elFb.innerHTML = '<div class="p-empty"><span class="p-empty-emoji">⚠️</span><div class="p-empty-title">Error al cargar</div><div class="p-empty-sub" style="margin-top:8px"><button onclick="pRenderContacts()" style="padding:8px 18px;background:var(--sage7);border:1.5px solid var(--sage4);border-radius:10px;font-size:15px;font-weight:700;color:var(--sage);cursor:pointer">Reintentar</button></div></div>';
  }
}

function pContactsTab(tab){
  ['favs','online','fans','blocked'].forEach(function(t){
    var c=document.getElementById('contacts-'+t); var b=document.getElementById('ctab-'+t);
    if(c) c.style.display = t===tab?'':'none';
    if(b) b.classList.toggle('active', t===tab);
  });
}

function pFilterContacts(q){
  // Search within the currently visible tab
  var lq = (q||'').toLowerCase().replace(/^@/,'');
  document.querySelectorAll('#contactsContent [data-fav-name]').forEach(function(c){
    if(c.closest('[style*="display:none"]')) return; // skip hidden tabs
    var nm=(c.dataset.favName||'').toLowerCase().indexOf(lq)>-1;
    var un=(c.dataset.favUname||'').toLowerCase().replace(/^@/,'').indexOf(lq)>-1;
    c.style.display=(!lq||nm||un)?'':'none';
  });
}

function pLeaveOfflineMsg(toId, toName, toAv){
  var existing = document.getElementById('offlineMsgOv');
  if(existing) existing.remove();
  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.id = 'offlineMsgOv';
  ov.innerHTML = '<div class="p-sheet">'
    +'<div class="p-sheet-handle"></div>'
    +'<div style="text-align:center;padding:4px 0 16px">'
    +'<div style="font-size:36px;margin-bottom:8px">'+_avInline(toAv||'🧑',48)+'</div>'
    +'<div style="font-family:\'Cormorant Garamond\',serif;font-size:19px;color:var(--ink);margin-bottom:4px">Mensaje para '+_escHtml(toName||'Usuario')+'</div>'
    +'<p style="font-size:14px;color:var(--ink4);margin:0 0 14px;line-height:1.5">Le llegará en su Buzón Velo cuando esté disponible.</p>'
    +'</div>'
    +'<textarea id="offlineMsgTa" class="feed-textarea" rows="4" placeholder="Escribí tu mensaje…" style="width:100%;box-sizing:border-box;border-radius:12px;padding:12px;font-size:14px;border:1.5px solid var(--border2);background:var(--cream2);font-family:\'Jost\',sans-serif;resize:none;margin-bottom:12px"></textarea>'
    +'<button class="p-btn p-btn--primary p-btn--lg p-btn--full" onclick="_sendOfflineMsg('+_jsAttr(toId)+','+_jsAttr(toName)+','+_jsAttr(toAv||'🧑')+')">📬 Enviar mensaje</button>'
    +'<div style="height:8px"></div>'
    +'<button class="p-btn p-btn--secondary p-btn--md p-btn--full" onclick="document.getElementById(\'offlineMsgOv\').remove()">Cancelar</button>'
    +'</div>';
  document.body.appendChild(ov);
  ov.addEventListener('click', function(e){ if(e.target===ov) ov.remove(); });
  setTimeout(function(){ var ta=document.getElementById('offlineMsgTa'); if(ta) ta.focus(); }, 100);
}

function _sendOfflineMsg(toId, toName, toAv){
  var ta = document.getElementById('offlineMsgTa');
  if(!ta || !ta.value.trim()){ pToast('✍️','Escribí algo antes de enviar'); return; }
  var text = ta.value.trim();
  var myId   = safeLS('get','velo_user_id')||'';
  var myName = safeLS('get','velo_user_name')||'';
  var myAv   = safeLS('get','velo_user_av')||'🧑';
  var _omOv = document.getElementById('offlineMsgOv'); if(_omOv) _omOv.remove();
  _initSupabase();
  if(sbClient && myId){
    // Route through broadcasts so recipient receives an inbox notification
    sbClient.from('broadcasts').insert({
      target: 'user:'+toId,
      subject: myName + ' te envió un mensaje',
      body: text,
      icon: myAv||'💌',
      sender: JSON.stringify({ n:myName, i:myId, a:myAv||'🧑' }),
      sent_at: new Date().toISOString()
    }).then(function(){}).catch(function(){});
  }
  pToast('📬','Mensaje enviado a '+_escHtml(toName||'Usuario')+'  💌');
}

// ── FAVORITES MINI WIDGET (shown in sections) ──────────────────
async function _renderFavWidget(containerId){
  var el = document.getElementById(containerId);
  if(!el) return;
  var _wMyId = safeLS('get','velo_user_id')||'';
  var favs = pGetFavs().filter(function(f){ return f.id !== _wMyId; });
  if(!favs.length){ el.innerHTML = ''; return; }

  var onlineIds = {};
  _initSupabase();
  if(sbClient){
    try{
      var cutoff = new Date(Date.now()-5*60*1000).toISOString();
      var {data:gd} = await sbClient.from('guardian_presence').select('user_id').gte('last_seen',cutoff);
      if(gd) gd.forEach(function(r){ onlineIds[r.user_id]=true; });
    }catch(e){}
  }

  var onlineFavs = favs.filter(function(f){ return onlineIds[f.id]; });
  var shownFavs  = onlineFavs.length ? onlineFavs : favs.slice(0,5);
  var label      = onlineFavs.length ? '🟢 Favoritos en línea' : '⭐ Mis favoritos';

  // Resolve any stale 'Usuario' names from profiles before rendering
  var _wStale = shownFavs.filter(function(f){ return !f.name || f.name === 'Usuario'; });
  if(_wStale.length && sbClient){
    try{
      var _wIds = _wStale.map(function(f){ return f.id; });
      var {data:_wPd} = await sbClient.from('profiles').select('id,nombre,username,avatar').in('id', _wIds);
      if(_wPd) _wPd.forEach(function(p){
        var real = p.nombre || (p.username ? '@'+p.username : '');
        if(!real) return;
        shownFavs.forEach(function(f){ if(f.id===p.id){ f.name=real; if(p.avatar) f.av=p.avatar; } });
        // Also update persistent cache
        if(_favsList) _favsList.forEach(function(f){ if(f.id===p.id){ f.name=real; if(p.avatar) f.av=p.avatar; } });
        safeLS('set','velo_favs', JSON.stringify(pGetFavs().slice(0,100)));
      });
    }catch(e){}
  }

  el.innerHTML = '<div style="margin-bottom:14px">'
    +'<div style="font-size:12px;font-weight:700;letter-spacing:1.5px;color:var(--sage3);text-transform:uppercase;margin-bottom:8px">'+label+'</div>'
    +'<div style="display:flex;gap:10px;overflow-x:auto;padding-bottom:4px;scrollbar-width:none;-ms-overflow-style:none">'
    +shownFavs.map(function(f){
      var isOnline = !!onlineIds[f.id];
      var displayName = (f.name && f.name !== 'Usuario') ? f.name : '?';
      return '<div style="display:flex;flex-direction:column;align-items:center;gap:4px;flex-shrink:0;cursor:pointer" onclick="pOpenDM('+_jsAttr(f.id)+','+_jsAttr(f.name)+','+_jsAttr(f.av||'🧑')+')">'
        +'<div style="position:relative">'
        +_avInline(f.av||'🧑', 38)
        +'<span style="position:absolute;bottom:0;right:0;width:10px;height:10px;border-radius:50%;background:'+(isOnline?'var(--st-on)':'rgba(150,150,150,.35)')+';border:2px solid var(--cream)"></span>'
        +'</div>'
        +'<div style="font-size:12px;color:var(--ink3);font-weight:600;max-width:48px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+_escHtml(displayName.split(' ')[0])+'</div>'
        +'</div>';
    }).join('')
    +'</div>'
    +'<button onclick="pGoTo(\'contacts\')" style="width:100%;margin-top:8px;padding:10px 16px;background:linear-gradient(135deg,rgba(116,198,157,.13),rgba(116,198,157,.07));border:1.5px solid rgba(116,198,157,.28);border-radius:14px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;font-family:\'Jost\',sans-serif;font-size:13px;font-weight:700;color:var(--sage3);letter-spacing:.3px;transition:all .18s" onmouseenter="this.style.background=\'linear-gradient(135deg,rgba(116,198,157,.20),rgba(116,198,157,.12))\'" onmouseleave="this.style.background=\'linear-gradient(135deg,rgba(116,198,157,.13),rgba(116,198,157,.07))\'"><span style="font-size:14px">👥</span> Ver todos mis contactos</button>'
    +'</div>';
}

