async function _doGenerateBcastImage(desc){
  var btn = document.getElementById('massAiImgBtn');
  var statusEl = document.getElementById('massImgUploadStatus');
  if(btn){ btn.disabled=true; btn.textContent='⏳ Generando imagen…'; }
  if(statusEl){ statusEl.textContent='⏳ Generando imagen con IA…'; statusEl.style.display='block'; }
  try{
    var prompt = 'Generá una imagen para una app de bienestar emocional llamada Velo. Estilo: ilustración digital minimalista y cálida, paleta de colores verdes suaves y oscuros (#0D2B1C, #74C69D, crema), fondo oscuro elegante, composición centrada, formato cuadrado. La imagen debe representar: '+desc+'. Sin texto en la imagen.';
    var res = await fetch(GEMINI_PROXY, {
      method:'POST', cache:'no-store',
      headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ type:'image-gen', prompt: prompt })
    });
    if(!res.ok) throw new Error('HTTP '+res.status);
    var data = await res.json();
    var parts = (((data.candidates||[])[0]||{}).content||{}).parts||[];
    var imgPart = parts.find(function(p){ return p.inlineData && p.inlineData.data; });
    if(!imgPart) throw new Error('Gemini no devolvió imagen. Intentá una descripción diferente.');
    var base64 = imgPart.inlineData.data;
    var mime = imgPart.inlineData.mimeType || 'image/png';
    _pendingBcastImg = { base64: base64, mime: mime };
    // Show confirmation overlay with large preview — don't upload until confirmed
    var prevOv = document.getElementById('bcastImgPreviewOv');
    if(prevOv) prevOv.remove();
    var ov = document.createElement('div');
    ov.id = 'bcastImgPreviewOv';
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(5,18,10,.96);z-index:10000;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px;box-sizing:border-box';
    ov.innerHTML = '<div style="font-size:12px;font-weight:700;letter-spacing:2px;color:rgba(116,198,157,.7);margin-bottom:14px">IMAGEN GENERADA CON IA</div>'
      +'<img src="data:'+mime+';base64,'+base64+'" style="max-width:100%;max-height:55vh;border-radius:16px;border:2px solid rgba(116,198,157,.3);box-shadow:0 8px 40px rgba(0,0,0,.6);object-fit:contain">'
      +'<p style="font-size:14px;color:rgba(255,255,255,.5);margin:14px 0 18px;text-align:center;line-height:1.5">¿Querés usar esta imagen en el mensaje?</p>'
      +'<div style="display:flex;gap:12px;width:100%;max-width:320px">'
      +'<button onclick="pBcastImgConfirm()" style="flex:1;padding:13px;background:var(--sage2);border:none;border-radius:14px;color:#fff;font-size:15px;font-weight:700;font-family:\'Jost\',sans-serif;cursor:pointer">✅ Usar esta imagen</button>'
      +'<button onclick="pBcastImgDiscard()" style="padding:13px 16px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.15);border-radius:14px;color:rgba(255,255,255,.6);font-size:15px;font-family:\'Jost\',sans-serif;cursor:pointer">🗑️ Descartar</button>'
      +'</div>';
    document.body.appendChild(ov);
    if(statusEl){ statusEl.textContent=''; statusEl.style.display='none'; }
  }catch(e){
    if(statusEl){ statusEl.textContent = '⚠️ No se pudo generar: '+e.message; statusEl.style.display='block'; }
    pToast('⚠️','Error al generar imagen');
  }
  if(btn){ btn.disabled=false; btn.textContent='🎨 Generar imagen con IA (opcional)'; }
}

async function pBcastImgConfirm(){
  var ov = document.getElementById('bcastImgPreviewOv');
  if(ov) ov.innerHTML = '<div style="color:#fff;font-size:15px">⏳ Subiendo imagen…</div>';
  var pending = _pendingBcastImg;
  _pendingBcastImg = null;
  try{
    _initSupabase();
    if(!sbClient) throw new Error('No Supabase');
    var byteStr = atob(pending.base64);
    var ab = new ArrayBuffer(byteStr.length);
    var ia = new Uint8Array(ab);
    for(var i=0;i<byteStr.length;i++) ia[i]=byteStr.charCodeAt(i);
    var ext = pending.mime.indexOf('png')>-1 ? 'png' : 'jpg';
    var blob = new Blob([ab], {type:pending.mime});
    var path = 'broadcast/ai-'+Date.now()+'.'+ext;
    var uploadRes = await sbClient.storage.from('avatars').upload(path, blob, {contentType:pending.mime, upsert:true});
    if(uploadRes.error) throw uploadRes.error;
    var urlRes = sbClient.storage.from('avatars').getPublicUrl(path);
    var pub = urlRes && urlRes.data && urlRes.data.publicUrl;
    if(!pub) throw new Error('No public URL');
    var urlEl = document.getElementById('massImageUrl');
    if(urlEl) urlEl.value = pub;
    _previewMassImage();
    pToast('🎨','¡Imagen añadida al mensaje! ✅');
  }catch(e){
    pToast('⚠️','Error al subir: '+e.message);
  }
  if(ov) ov.remove();
}

function pBcastImgDiscard(){
  _pendingBcastImg = null;
  var ov = document.getElementById('bcastImgPreviewOv');
  if(ov) ov.remove();
  pToast('🗑️','Imagen descartada');
}

function _previewMassImage(){
  var el=document.getElementById('massImageUrl');
  var prev=document.getElementById('massImgPreview');
  if(!prev) return;
  var url=(el&&el.value.trim())||'';
  prev.innerHTML=url?'<img src="'+_escHtml(url)+'" style="width:100%;max-height:140px;object-fit:cover;border-radius:8px;border:1px solid rgba(255,255,255,.1)" onerror="this.parentElement.innerHTML=\'<span style=font-size:13px;color:rgba(255,100,100,.6)>URL de imagen no válida</span>\'">':'';
}

async function _onBcastImgPick(input){
  var file = input && input.files && input.files[0];
  if(!file) return;
  var statusEl = document.getElementById('massImgUploadStatus');
  var urlEl    = document.getElementById('massImageUrl');
  if(statusEl){ statusEl.textContent = '⏳ Subiendo imagen…'; statusEl.style.display='block'; }
  try{
    // Resize to max 1000px wide using Canvas
    var dataUrl = await new Promise(function(resolve, reject){
      var reader = new FileReader();
      reader.onload = function(e){
        var img = new Image();
        img.onload = function(){
          var maxW = 1000;
          var w = img.width, h = img.height;
          if(w > maxW){ h = Math.round(h * maxW / w); w = maxW; }
          var canvas = document.createElement('canvas');
          canvas.width = w; canvas.height = h;
          canvas.getContext('2d').drawImage(img, 0, 0, w, h);
          resolve(canvas.toDataURL('image/jpeg', 0.82));
        };
        img.onerror = reject;
        img.src = e.target.result;
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
    // Upload to Supabase storage
    _initSupabase();
    if(!sbClient) throw new Error('No Supabase');
    var byteStr = atob(dataUrl.split(',')[1]);
    var ab = new ArrayBuffer(byteStr.length);
    var ia = new Uint8Array(ab);
    for(var i=0;i<byteStr.length;i++) ia[i]=byteStr.charCodeAt(i);
    var blob = new Blob([ab], {type:'image/jpeg'});
    var path = 'broadcast/'+Date.now()+'.jpg';
    var r = await sbClient.storage.from('avatars').upload(path, blob, {contentType:'image/jpeg', upsert:true});
    if(r.error) throw r.error;
    var urlRes = sbClient.storage.from('avatars').getPublicUrl(path);
    var pub = urlRes && urlRes.data && urlRes.data.publicUrl;
    if(!pub) throw new Error('No public URL');
    if(urlEl){ urlEl.value = pub; }
    if(statusEl){ statusEl.textContent = '✅ Imagen subida'; }
    _previewMassImage();
  }catch(e){
    if(statusEl){ statusEl.textContent = '⚠️ Error al subir. Intentá con una URL directa.'; }
    console.error('[bcast img upload]', e);
  }
  // Reset file input so same file can be re-selected
  input.value = '';
}

async function pSendMassMessage(target){
  var subj = document.getElementById('massSubject');
  var body = document.getElementById('massBody');
  var imgEl= document.getElementById('massImageUrl');
  if(!subj || !subj.value.trim()){ pToast('⚠️','Ingresá un asunto'); return; }
  if(!body || !body.value.trim()){ pToast('⚠️','Escribí el mensaje'); return; }
  var subject  = subj.value.trim();
  var message  = body.value.trim();
  var imageUrl = imgEl ? imgEl.value.trim() : '';
  var icon     = target === 'pros' ? '🩺' : '📢';
  var sender   = 'Velo — Comunicado '+(target === 'pros' ? 'Profesionales' : 'Comunidad');

  var saved = await sbSaveBroadcast(target, subject, message, icon, sender, imageUrl);

  var broadcasts = []; try{ broadcasts = JSON.parse(safeLS('get','velo_broadcasts')||'[]'); }catch(e){}
  broadcasts.unshift({ id:'mass-'+Date.now(), ts:Date.now(), target:target, subject:subject, body:message, icon:icon, sender:sender, sentBy:_ADMIN_EMAIL, imageUrl:imageUrl||undefined });
  safeLS('set','velo_broadcasts', JSON.stringify(broadcasts.slice(0,200)));

  var ov = document.getElementById('massMessageOv');
  if(ov) ov.remove();
  var recipientLabel = target === 'pros' ? 'profesionales' : 'usuarios';
  pToast('📤', saved ? 'Mensaje enviado a todos los '+recipientLabel+' ✅' : 'Enviado localmente (sin conexión)');
  _renderAdmin();
}

async function sbSaveBroadcast(target, subject, body, icon, sender, imageUrl){
  if(!sbClient) return false;
  try{
    var row = { target:target, subject:subject, body:body, icon:icon||'📢', sender:sender||'Velo', sent_at:new Date().toISOString() };
    if(imageUrl) row.image_url = imageUrl;
    var {error} = await sbClient.from('broadcasts').insert(row);
    return !error;
  }catch(e){ return false; }
}

async function sbLoadBroadcasts(userType){
  if(!sbClient) return null;
  try{
    var since = new Date(Date.now() - 90*24*3600*1000).toISOString();
    var myId  = safeLS('get','velo_user_id') || '';
    // Load role-based broadcasts AND personal ones (bottle replies, etc.)
    var targets = [userType, 'all'];
    if(myId) targets.push('user:'+myId);
    var {data,error} = await sbClient.from('broadcasts')
      .select('*')
      .in('target', targets)
      .gte('sent_at', since)
      .order('sent_at',{ascending:false})
      .limit(50);
    return error ? null : (data||[]);
  }catch(e){ return null; }
}

// ── SUPABASE CLOUD FUNCTIONS (ported from velo.js) ────────────
async function sbSignUp(email, password, nombre){
  if(!sbClient) return {error:{message:'Supabase no inicializado'}};
  var {data, error} = await sbClient.auth.signUp({ email:email, password:password, options:{data:{nombre:nombre, role:'user'}} });
  if(!error && data.user){
    try{ await sbClient.from('profiles').insert({ id:data.user.id, nombre:nombre, email:email, role:'user', created_at:new Date().toISOString() }); }catch(e){}
    // Aplicar referral si el usuario llegó con ?ref=UID
    try{ await _applyReferralIfAny(data.user.id); }catch(e){}
  }
  return {data, error};
}

async function sbSignIn(email, password){
  if(!sbClient) return {error:{message:'Supabase no inicializado'}};
  return await sbClient.auth.signInWithPassword({email, password});
}

function _queueDiarySync(entry){
  var q=[]; try{q=JSON.parse(safeLS('get','velo_diary_sync_q')||'[]');}catch(e){}
  if(q.some(function(x){return String(x.ts)===String(entry.ts);})) return;
  q.push({text:entry.text,dateLabel:entry.dateLabel,ts:entry.ts,title:entry.title||''});
  safeLS('set','velo_diary_sync_q', JSON.stringify(q.slice(0,50)));
}

async function _retryDiarySync(){
  if(!sbClient) return;
  var q=[]; try{q=JSON.parse(safeLS('get','velo_diary_sync_q')||'[]');}catch(e){}
  if(!q.length) return;
  var ok=await _ensureSbSession(); if(!ok) return;
  var uid=safeLS('get','velo_user_id'); if(!uid) return;
  var remaining=[];
  for(var i=0;i<q.length;i++){
    var e=q[i];
    try{
      var res=await sbClient.from('diary_entries').upsert(
        {user_id:uid,text:e.text,date_label:e.dateLabel,ts:e.ts,title:e.title||''},
        {onConflict:'user_id,ts',ignoreDuplicates:true}
      );
      if(res.error) remaining.push(e);
    }catch(err){ remaining.push(e); }
  }
  safeLS('set','velo_diary_sync_q', JSON.stringify(remaining));
  if(remaining.length < q.length) pToast('🔄','Entradas sincronizadas');
}

window.addEventListener('online', function(){ setTimeout(_retryDiarySync, 1500); });

async function sbSaveDiaryEntry(text, dateLabel, ts, title){
  if(!sbClient){ _queueDiarySync({text:text,dateLabel:dateLabel,ts:ts,title:title}); return; }
  try{
    var ok = await _ensureSbSession();
    if(!ok){ _queueDiarySync({text:text,dateLabel:dateLabel,ts:ts,title:title}); return; }
    var uid = safeLS('get','velo_user_id');
    if(!uid){ _queueDiarySync({text:text,dateLabel:dateLabel,ts:ts,title:title}); return; }
    var res = await sbClient.from('diary_entries').insert({ user_id:uid, text:text, date_label:dateLabel, ts:ts, title:title||'' });
    if(res.error) _queueDiarySync({text:text,dateLabel:dateLabel,ts:ts,title:title});
  }catch(e){ _queueDiarySync({text:text,dateLabel:dateLabel,ts:ts,title:title}); }
}

async function sbDeleteDiaryEntry(ts){
  if(!sbClient) return;
  try{
    var ok = await _ensureSbSession();
    if(!ok) return;
    var {data:ud} = await sbClient.auth.getUser();
    if(!ud || !ud.user) return;
    await sbClient.from('diary_entries').delete().eq('user_id', ud.user.id).eq('ts', ts);
  }catch(e){}
}

