// ── JITSI MEET — VIDEO CALL ────────────────────────────────────
function _jitsiRoomName(proId){
  // Deterministic room per booking: velo + proId + date (YYYYMMDD) → same room all day
  var d = new Date();
  var dateStr = d.getFullYear()+String(d.getMonth()+1).padStart(2,'0')+String(d.getDate()).padStart(2,'0');
  return 'velo-'+proId+'-'+dateStr;
}

function pStartJitsiCall(){
  var pending = null; try{ pending = JSON.parse(safeLS('get','velo_current_session')||'null'); }catch(e){}
  var proId = pending ? pending.proId : 'sesion';
  var room = _jitsiRoomName(proId);
  var displayName = encodeURIComponent(safeLS('get','velo_user_name')||'Usuario Velo');
  var url = 'https://meet.jit.si/'+room+'#userInfo.displayName='+displayName+'&config.startWithAudioMuted=false&config.prejoinPageEnabled=false&config.toolbarButtons=["microphone","camera","hangup","fullscreen","chat","tileview"]';

  // Embed in iframe inside the session room
  var container = document.getElementById('jitsiContainer');
  var frame     = document.getElementById('jitsiFrame');
  var btn       = document.getElementById('jitsiStartBtn');
  if(frame && container){
    frame.src = url;
    container.style.display = 'block';
    if(btn){ btn.textContent = '📹 Videollamada activa'; btn.style.opacity = '.6'; btn.disabled = true; }
    pToast('📹','Videollamada iniciada — usá auriculares 🎧');
  } else {
    // Fallback: new tab
    window.open('https://meet.jit.si/'+room, '_blank', 'noopener');
    pToast('📹','Videollamada abierta en nueva pestaña');
  }

  // Mark session as started for admin audit
  var sessions = []; try{ sessions = JSON.parse(safeLS('get','velo_sessions')||'[]'); }catch(e){}
  if(pending && !pending.callStarted){
    pending.callStarted = true;
    pending.callStartedAt = Date.now();
    pending.room = room;
    safeLS('set','velo_current_session', JSON.stringify(pending));
    sessions.unshift(pending);
    safeLS('set','velo_sessions', JSON.stringify(sessions.slice(0,200)));
  }
}

function pInitSessionRoom(){
  var pending = null; try{ pending = JSON.parse(safeLS('get','velo_current_session')||'null'); }catch(e){}
  var pro = null;
  if(pending && pending.proId){
    pro = _proData.find(function(p){ return p.id === pending.proId; });
  }
  // Header
  _setEl('srProName',   pro ? pro.name : 'Tu profesional');
  _setEl('srProSpec',   pro ? pro.spec : '');
  _setEl('srProAv',     pro ? pro.av   : '🩺');
  _setEl('srProRating', pro ? '⭐ '+pro.rating : '');

  // Room link preview
  var room = pending ? _jitsiRoomName(pending.proId) : _jitsiRoomName('sesion');
  var linkEl = document.getElementById('srRoomLink');
  if(linkEl) linkEl.textContent = 'meet.jit.si/'+room;

  // Tips
  _setEl('srTips',
    '<ul style="font-size:15px;color:var(--ink4);line-height:2;padding-left:18px">'
    +'<li>Usá <strong>auriculares</strong> para mejor audio</li>'
    +'<li>Buscá un espacio <strong>tranquilo y privado</strong></li>'
    +'<li>La sala es <strong>privada</strong> — solo vos y tu profesional</li>'
    +'<li>No se graba la sesión</li>'
    +'</ul>'
  );
}

function pEndSession(){
  pToast('✅','¡Gracias! Ahora podés dejar tu reseña 🌿');
  // Enable admin transfer approval for this session
  var pending = null; try{ pending = JSON.parse(safeLS('get','velo_current_session')||'null'); }catch(e){}
  if(pending){
    pending.ended = true;
    pending.endedAt = Date.now();
    safeLS('set','velo_current_session', JSON.stringify(pending));
    var transfers = []; try{ transfers = JSON.parse(safeLS('get','velo_pending_transfers')||'[]'); }catch(e){}
    transfers.unshift(pending);
    safeLS('set','velo_pending_transfers', JSON.stringify(transfers.slice(0,100)));
    // Update Supabase session status to completed
    _initSupabase();
    if(sbClient && pending.id){
      sbClient.from('sessions').update({status:'completed',updated_at:new Date().toISOString()}).eq('id',pending.id).then(function(){}).catch(function(){});
    }
  }
  setTimeout(function(){ pGoTo('post-chat'); }, 800);
}

// ── WEEKLY MOOD MINI-GRAPH ────────────────────────────────────
async function _renderHomeWeekMoodGraph(){
  var container = document.getElementById('homeWeekMoodGraph');
  if(!container) return;
  var today = new Date();
  var dayNames = ['D','L','M','M','J','V','S'];
  var dayFullNames = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
  var moodColors = {'😄':'rgba(116,198,157,.9)','😊':'rgba(116,198,157,.65)','😐':'rgba(200,160,80,.7)','😞':'rgba(180,90,90,.7)','😢':'rgba(160,70,70,.8)'};
  var moodBgs    = {'😄':'rgba(116,198,157,.22)','😊':'rgba(116,198,157,.14)','😐':'rgba(200,160,80,.14)','😞':'rgba(180,90,90,.11)','😢':'rgba(160,70,70,.14)'};
  // Score per mood for the "best day" insight + curva emocional
  var moodScore  = {'😄':5,'😊':4,'😐':3,'😞':2,'😢':1};

  function _buildDays(sbMap){
    var days = [];
    for(var i=6; i>=0; i--){
      var d = new Date(today.getFullYear(), today.getMonth(), today.getDate()-i);
      var key = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
      var mood = null;
      try{ mood = JSON.parse(safeLS('get','velo_mood_'+key)||'null'); }catch(e){}
      if(!mood && sbMap && sbMap[key]) mood = sbMap[key];
      days.push({
        dayName:dayNames[d.getDay()],
        dayFull:dayFullNames[d.getDay()],
        mood:mood,
        isToday:i===0,
        key:key
      });
    }
    return days;
  }

  function _buildGraphHtml(days){
    // SVG line connecting registered moods (la curva emocional)
    var pts = [];
    days.forEach(function(d,i){
      if(d.mood && moodScore[d.mood.emoji] !== undefined){
        // x = center of column (each col = ~14.28%); y inverted (higher score → lower y)
        var x = (i + .5) * (100/7);
        var y = 86 - (moodScore[d.mood.emoji]-1) * 18; // map 1..5 → 86..14
        pts.push({x:x, y:y, i:i});
      }
    });
    var svgPath = '';
    if(pts.length >= 2){
      // Smooth curve between points using a quadratic-style midpoint trick
      var path = 'M ' + pts[0].x.toFixed(2) + ' ' + pts[0].y.toFixed(2);
      for(var ci=1; ci<pts.length; ci++){
        var p0 = pts[ci-1], p1 = pts[ci];
        var midX = (p0.x + p1.x) / 2;
        path += ' Q ' + midX.toFixed(2) + ' ' + p0.y.toFixed(2) + ' ' + midX.toFixed(2) + ' ' + ((p0.y+p1.y)/2).toFixed(2);
        path += ' T ' + p1.x.toFixed(2) + ' ' + p1.y.toFixed(2);
      }
      svgPath = '<svg viewBox="0 0 100 100" preserveAspectRatio="none" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:0;overflow:visible">'
        + '<defs><linearGradient id="moodCurveGrad" x1="0%" y1="0%" x2="100%" y2="0%">'
        + '<stop offset="0%" stop-color="rgba(116,198,157,.45)"/>'
        + '<stop offset="100%" stop-color="rgba(155,210,180,.85)"/>'
        + '</linearGradient></defs>'
        + '<path d="'+path+'" fill="none" stroke="url(#moodCurveGrad)" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke" style="filter:drop-shadow(0 1px 3px rgba(116,198,157,.35))"/>'
        + '</svg>';
    }
    var dayCols = days.map(function(d){
      var color = d.mood ? (moodColors[d.mood.emoji]||'rgba(116,198,157,.65)') : (d.isToday ? 'rgba(116,198,157,.80)' : 'rgba(116,198,157,.30)');
      var bg    = d.mood ? (moodBgs[d.mood.emoji]||'rgba(116,198,157,.18)') : (d.isToday ? 'rgba(116,198,157,.15)' : 'rgba(255,255,255,.05)');
      var shadow = d.mood ? 'box-shadow:0 2px 12px '+color+';' : (d.isToday ? 'box-shadow:0 0 10px rgba(116,198,157,.35);' : '');
      var ring  = d.isToday ? 'border:2.5px solid '+color+';' : (d.mood ? 'border:2px solid '+color+';' : 'border:1.5px dashed rgba(116,198,157,.28);');
      var emoji = d.mood ? d.mood.emoji : (d.isToday ? '✦' : '·');
      var todayEmptyStyle = (d.isToday && !d.mood) ? 'animation:moodDayPulse 2.2s ease-in-out infinite;' : '';
      var emojiSz = d.mood ? '20' : (d.isToday ? '14' : '10');
      var cls   = 'mood-day-circle'+(d.mood?'':' mood-day-empty')+(d.isToday?' mood-day-today':'');
      return '<div style="display:flex;flex-direction:column;align-items:center;gap:4px;flex:1;cursor:pointer;position:relative;z-index:1" onclick="pGoTo(\'mood\')" title="'+(d.mood?(d.dayFull+': '+(d.mood.label||d.mood.emoji)):(d.isToday?'Registrá tu ánimo de hoy':'Sin registro · '+d.dayFull))+'">'
        +'<div class="'+cls+'" style="width:40px;height:40px;border-radius:50%;'+ring+shadow+'background:'+bg+';display:flex;align-items:center;justify-content:center;font-size:'+emojiSz+'px;transition:.2s;'+todayEmptyStyle+'">'+emoji+'</div>'
        +'<span style="font-size:10px;font-weight:700;letter-spacing:.3px;color:var(--ink4);opacity:'+(d.isToday?'1':'.55')+'">'+d.dayName+'</span>'
        +'</div>';
    }).join('');
    return svgPath
      + '<div style="position:relative;z-index:1;display:flex;gap:4px;justify-content:space-between;align-items:flex-end;width:100%">'+dayCols+'</div>';
  }

  // Streak + insight + progress bar
  function _streakInsightHtml(days){
    var loggedCount = 0;
    var streak = 0;
    var streakBroken = false;
    var moodTally = {};
    var bestScore = -1;
    var bestDay = null;
    for(var i=6; i>=0; i--){
      var d = days[i];
      var sIdx = 6 - i; // 0 = today, 1 = yesterday, ...
      if(d.mood && d.mood.emoji){
        loggedCount++;
        moodTally[d.mood.emoji] = (moodTally[d.mood.emoji]||0) + 1;
        var sc = moodScore[d.mood.emoji] || 0;
        if(sc > bestScore){ bestScore = sc; bestDay = d; }
      }
      if(!streakBroken){
        if(d.mood && d.mood.emoji) streak++;
        else if(sIdx > 0) streakBroken = true;
      }
    }
    if(!loggedCount){
      return '<div style="text-align:center;padding:6px 0 2px;font-size:12px;color:var(--ink4);font-family:Jost,sans-serif;font-style:italic;opacity:.72">Registrá cómo te sentís para ver tu historial</div>';
    }
    var streakMsg = streak >= 5 ? '🔥 '+streak+' días seguidos — ¡imparable!'
                  : streak >= 3 ? '🔥 '+streak+' días seguidos'
                  : streak >= 2 ? '✨ '+streak+' días seguidos esta semana'
                  : loggedCount >= 3 ? '💚 '+loggedCount+' días registrados esta semana'
                  : '💚 Registraste '+loggedCount+' día'+(loggedCount>1?'s':'')+' esta semana';
    // Dominant emotion
    var domEmoji = '', domCount = 0;
    Object.keys(moodTally).forEach(function(k){ if(moodTally[k] > domCount){ domCount = moodTally[k]; domEmoji = k; }});
    // Insights block
    var insights = [];
    if(bestDay && bestDay.mood) insights.push('Tu mejor día: <strong style="color:rgba(116,198,157,.95)">'+bestDay.dayFull+'</strong> '+bestDay.mood.emoji);
    if(domCount >= 2) insights.push('Emoción dominante: '+domEmoji+' ×'+domCount);
    if(loggedCount < 7) insights.push('<span style="opacity:.78">Faltan '+(7-loggedCount)+' día'+(7-loggedCount>1?'s':'')+' para completar tu semana</span>');
    // Progress bar
    var progPct = Math.round(loggedCount / 7 * 100);
    var progBar = '<div style="margin:8px 14px 0;height:5px;background:rgba(116,198,157,.10);border-radius:100px;overflow:hidden;position:relative">'
      + '<div style="height:100%;width:'+progPct+'%;background:linear-gradient(90deg,rgba(116,198,157,.65),rgba(155,210,180,.95));border-radius:100px;transition:width .6s ease-out;box-shadow:0 0 8px rgba(116,198,157,.55)"></div>'
      + '</div>';
    var html = '<div style="text-align:center;padding:6px 0 2px;font-size:12.5px;font-weight:800;color:rgba(116,198,157,.90);font-family:Jost,sans-serif;letter-spacing:.2px">'+streakMsg+'</div>'
      + progBar;
    if(insights.length){
      html += '<div style="text-align:center;margin-top:8px;font-size:11.5px;color:var(--ink3);font-family:Jost,sans-serif;line-height:1.55">'+insights.join(' &nbsp;·&nbsp; ')+'</div>';
    }
    // CTA "Ver mi mes" — usa helper que cierra el sheet si está abierto
    html += '<div style="text-align:center;margin-top:9px"><button onclick="pVerMiMesCompleto()" style="background:rgba(116,198,157,.18);border:1.5px solid rgba(116,198,157,.55);color:rgba(170,235,200,.98);font-size:12px;font-weight:800;font-family:Jost,sans-serif;padding:8px 18px;border-radius:100px;letter-spacing:.4px;cursor:pointer;transition:all .15s;box-shadow:0 2px 10px rgba(116,198,157,.18)">Ver mi mes completo →</button></div>';
    return html;
  }

  // Make container relative so SVG can overlay
  container.style.position = 'relative';

  // Render immediately from localStorage (instant, no waiting)
  var _days0 = _buildDays(null);
  container.innerHTML = _buildGraphHtml(_days0);
  var _streakEl = document.getElementById('homeWeekStreak');
  if(_streakEl) _streakEl.innerHTML = _streakInsightHtml(_days0);

  // Then silently update from Supabase in background
  var _months = {};
  for(var _mi=0; _mi<7; _mi++){
    var _md = new Date(today.getFullYear(), today.getMonth(), today.getDate()-_mi);
    var _mk = _md.getFullYear()+'-'+String(_md.getMonth()+1).padStart(2,'0');
    if(!_months[_mk]) _months[_mk] = {year:_md.getFullYear(), month:_md.getMonth()+1};
  }
  var _sbMap = {};
  await Promise.all(Object.values(_months).map(async function(m){
    var sbData = await sbLoadAllMoods(m.year, m.month);
    if(sbData) sbData.forEach(function(e){ _sbMap[e.date_key] = e; });
  }));
  // Only re-render if Supabase added data not in localStorage
  var _gwEl=document.getElementById('homeWeekMoodGraph');
  if(Object.keys(_sbMap).length > 0 && _gwEl){
    var _daysSb = _buildDays(_sbMap);
    _gwEl.innerHTML = _buildGraphHtml(_daysSb);
    var _streakElSb = document.getElementById('homeWeekStreak');
    if(_streakElSb) _streakElSb.innerHTML = _streakInsightHtml(_daysSb);
  }
}

// ── DIARY PROMPTS ─────────────────────────────────────────────
var _DIARY_PROMPTS = [
  '¿Qué fue lo más difícil de hoy y cómo lo manejaste?',
  '¿Qué pequeña cosa te alegró hoy?',
  '¿De qué te sentís orgulloso/a esta semana?',
  '¿Qué emoción sentiste más fuerte hoy?',
  '¿Qué necesitás que aún no te diste?',
  '¿Hay algo que querías decirle a alguien y no te animaste?',
  '¿Qué harías diferente si pudieras repetir el día de hoy?',
  '¿Qué persona te hizo sentir acompañado/a últimamente?',
  '¿Qué te preocupa más ahora y qué podés hacer al respecto?',
  '¿Qué le dirías a la versión de vos de hace un año?',
  '¿Dónde sentís la tensión en tu cuerpo hoy?',
  '¿Qué límite necesitás poner que aún no pusiste?',
  '¿Qué emoción estás evitando sentir?',
  '¿Qué te gustaría que alguien notara de vos hoy?',
  '¿Qué situación te robó energía esta semana?',
  '¿Cuándo fue la última vez que te reíste de verdad?',
  '¿Qué significa para vos estar bien hoy?',
  '¿Qué aprendiste sobre vos mismo/a esta semana?',
  '¿Hay algo que ya no querés cargar? ¿Qué pasaría si lo soltaras?',
  '¿Qué parte de tu historia te cuesta contar?',
  '¿Qué cosa simple te da paz?',
  '¿Qué expectativa tuya te está pesando?',
  '¿Qué vínculo necesitás cuidar más?',
  '¿Qué estás esperando que llegue para estar bien?',
  '¿En qué momento del día te sentís más vos?',
  '¿Qué no dijiste hoy que querías decir?',
  '¿Qué estás postergando y por qué?',
  '¿Qué emoción te acompaña al cerrar este día?',
  '¿Qué es algo que hacés por los demás pero no por vos?',
  '¿Qué te da miedo reconocer?'
];

function _getDiaryPrompt(){
  var day0 = new Date(new Date().getFullYear(),0,0);
  var dayOfYear = Math.floor((Date.now()-day0.getTime())/86400000);
  return _DIARY_PROMPTS[dayOfYear % _DIARY_PROMPTS.length];
}

function pInjectDiaryPrompt(){
  var ta = document.getElementById('diaryTa');
  if(!ta) return;
  var prompt = _getDiaryPrompt();
  ta.value = prompt + '\n\n';
  ta.focus();
  ta.setSelectionRange(ta.value.length, ta.value.length);
  pToast('✨','Reflexión del día ▸ Escribí libremente');
}

function _initDiaryPromptPreview(){
  var el = document.getElementById('diaryPromptPreview');
  if(el) el.textContent = _getDiaryPrompt();
}

// ── WEEKLY SUMMARY ────────────────────────────────────────────
async function _checkWeeklySummary(){
  var lastKey = safeLS('get','velo_last_weekly_summary')||'';
  var today = new Date();
  var todayKey = today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0')+'-'+String(today.getDate()).padStart(2,'0');
  if(lastKey === todayKey) return;
  var isSunday = today.getDay() === 0;
  // Only run on Sundays — the 7-day fallback caused unexpected mid-week overlays
  if(!isSunday) return;
  // Skip if Supabase sync shows this week's summary was already sent/read on another device
  if(_syncedReadIds['weekly-'+todayKey]){
    safeLS('set','velo_last_weekly_summary', todayKey);
    return;
  }

  // Build Supabase fallback map for last 7 days (covers localStorage gaps)
  var _wsMonths = {};
  for(var _wmi=0; _wmi<7; _wmi++){
    var _wmd = new Date(today.getFullYear(), today.getMonth(), today.getDate()-_wmi);
    var _wmk = _wmd.getFullYear()+'-'+String(_wmd.getMonth()+1).padStart(2,'0');
    if(!_wsMonths[_wmk]) _wsMonths[_wmk] = {year:_wmd.getFullYear(), month:_wmd.getMonth()+1};
  }
  var _wsSbMap = {};
  await Promise.all(Object.values(_wsMonths).map(async function(m){
    var sbData = await sbLoadAllMoods(m.year, m.month);
    if(sbData) sbData.forEach(function(e){ _wsSbMap[e.date_key] = e; });
  }));

  // Count moods via date keys + Supabase fallback
  var weekMoods = [];
  var _today = new Date();
  for(var _i=0; _i<7; _i++){
    var _d = new Date(_today.getFullYear(), _today.getMonth(), _today.getDate()-_i);
    var _k = _d.getFullYear()+'-'+String(_d.getMonth()+1).padStart(2,'0')+'-'+String(_d.getDate()).padStart(2,'0');
    var _m = null; try{ _m = JSON.parse(safeLS('get','velo_mood_'+_k)||'null'); }catch(e){}
    if(!_m && _wsSbMap[_k]) _m = _wsSbMap[_k];
    if(_m) weekMoods.push(_m);
  }
  var diary = []; try{ diary = JSON.parse(safeLS('get','velo_diary')||'[]'); }catch(e){}
  var weekDiary = diary.filter(function(e){ return e.ts && (Date.now()-e.ts)<7*86400000; });
  // Use mood-registration streak (account-scoped) — visit-day count can be stale
  var streak = _getMoodStreak ? _getMoodStreak() : weekMoods.length;

  safeLS('set','velo_last_weekly_summary', todayKey);

  // Build full 7-day timeline (ordered Mon→Sun, with nulls for missing days)
  var dayNamesShort = ['Do','Lu','Ma','Mi','Ju','Vi','Sa'];
  var timeline = [];
  for(var _j=6; _j>=0; _j--){
    var _dj = new Date(_today.getFullYear(), _today.getMonth(), _today.getDate()-_j);
    var _kj = _dj.getFullYear()+'-'+String(_dj.getMonth()+1).padStart(2,'0')+'-'+String(_dj.getDate()).padStart(2,'0');
    var _mj = null; try{ _mj = JSON.parse(safeLS('get','velo_mood_'+_kj)||'null'); }catch(e){}
    if(!_mj && _wsSbMap[_kj]) _mj = _wsSbMap[_kj];
    timeline.push({ dayName: dayNamesShort[_dj.getDay()], mood: _mj, isToday: _j===0 });
  }

  var moodCount = {}; weekMoods.forEach(function(m){ if(m && m.emoji){ moodCount[m.emoji]=(moodCount[m.emoji]||0)+1; } });
  var dominantMood = Object.keys(moodCount).sort(function(a,b){ return moodCount[b]-moodCount[a]; })[0]||null;
  var userName = (safeLS('get','velo_user_name')||'').split(' ')[0]||'';
  var sinRegistros = weekMoods.length === 0 && weekDiary.length === 0;
  var inbox=[]; try{ inbox=JSON.parse(safeLS('get','velo_inbox')||'[]'); }catch(e){}
  var alreadySent = inbox.find(function(m){ return m.id==='weekly-'+todayKey; }) || _syncedReadIds['weekly-'+todayKey];

  // ── Compute rich weekly stats ──────────────────────────────
  var _moodScore = {'😄':5,'😊':4,'😐':3,'😞':2,'😢':1};
  var _moodLabel = {'😄':'Genial','😊':'Bien','😐':'Neutro','😞':'Bajo','😢':'Difícil'};
  var moodDistrib = {}; // emoji → count
  weekMoods.forEach(function(m){ if(m&&m.emoji){ moodDistrib[m.emoji]=(moodDistrib[m.emoji]||0)+1; } });
  var totalReg = weekMoods.length;
  var consistenciaPct = Math.round((totalReg/7)*100);

  // Mood distribution sorted by frequency
  var distribLines = Object.keys(moodDistrib)
    .sort(function(a,b){ return moodDistrib[b]-moodDistrib[a]; })
    .map(function(e){
      var pct = Math.round((moodDistrib[e]/totalReg)*100);
      return e+' '+(_moodLabel[e]||e)+': '+moodDistrib[e]+' día'+(moodDistrib[e]!==1?'s':'')+' ('+pct+'%)';
    });

  // Best and worst day
  var dayNamesLong = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
  var bestDay = null, worstDay = null;
  timeline.forEach(function(d){
    if(!d.mood) return;
    var sc = _moodScore[d.mood.emoji]||3;
    if(!bestDay  || sc > (_moodScore[bestDay.mood.emoji]||3))  bestDay  = d;
    if(!worstDay || sc < (_moodScore[worstDay.mood.emoji]||3)) worstDay = d;
  });

  // Trend: compare first half vs second half scores
  var scores = timeline.filter(function(d){ return d.mood; }).map(function(d){ return _moodScore[d.mood.emoji]||3; });
  var half = Math.ceil(scores.length/2);
  var avgFirst  = scores.slice(0,half).reduce(function(a,b){return a+b;},0)/(half||1);
  var avgSecond = scores.slice(half).reduce(function(a,b){return a+b;},0)/((scores.length-half)||1);
  var trendVal  = scores.length < 2 ? 0 : avgSecond - avgFirst;
  var trendTxt  = trendVal > 0.4 ? '↗ Mejoró a lo largo de la semana (+'+(Math.round(trendVal*20))+'%)'
                : trendVal < -0.4 ? '↘ Descendió en la segunda mitad (-'+(Math.round(Math.abs(trendVal)*20))+'%)'
                : '→ Se mantuvo estable durante la semana';

  // Diary days
  var diaryDays = [];
  weekDiary.forEach(function(e){ if(e.ts){ var d=new Date(e.ts); var dn=dayNamesLong[d.getDay()].slice(0,2); if(diaryDays.indexOf(dn)<0) diaryDays.push(dn); } });

  if(sinRegistros){
    if(!alreadySent){
      var encBody = 'Hola'+(userName?' '+userName:'')+', esta semana no registraste cómo te sentiste — y está bien, todos los ritmos son válidos. 💙\n\n'
        +'Cuando quieras, tocá "¿Cómo te sentís hoy?" en la pantalla principal. Son 5 segundos y te ayuda a conocerte mejor.\n\n'
        +'📊 Con más registros, tu resumen semanal de cada domingo se vuelve más rico y personalizado.\n'
        +'📋 El 1° de cada mes el equipo de Velo te envía un análisis completo y detallado de todos tus registros del mes.\n\n'
        +'¡Cada pequeño paso cuenta! 🌱';
      inbox.unshift({id:'weekly-'+todayKey,tipo:'sistema',icon:'💙',remitente:'Velo — Resumen Semanal',asunto:'Esta semana todavía no registraste nada 🌱',extracto:'Animáte a registrar cómo te sentís esta semana',cuerpo:encBody,leido:false,fecha:new Date().toLocaleDateString('es',{day:'2-digit',month:'short'})});
      safeLS('set','velo_inbox',JSON.stringify(inbox.slice(0,100)));
      if(typeof _updateInboxDot==='function') _updateInboxDot();
    }
    return;
  }

  // Generate AI analysis and send to Buzón
  setTimeout(async function(){
    var aiText = await _generateWeeklySummaryAI(timeline, dominantMood, streak, totalReg, weekDiary.length, userName, distribLines, trendTxt, bestDay, worstDay);
    if(!alreadySent){
      var _inbox2=[]; try{_inbox2=JSON.parse(safeLS('get','velo_inbox')||'[]');}catch(e){}
      var _wqB = _pickWeeklyQuote(dominantMood);
      var _moodCat = (dominantMood==='😄'||dominantMood==='😊') ? 'feliz' : (dominantMood==='😞'||dominantMood==='😢') ? 'dificil' : 'neutral';
      var _mediaRec = {
        feliz:   { libro:'El Alquimista — Paulo Coelho', peli:'Coco (Pixar, 2017)' },
        neutral: { libro:'El Poder del Ahora — Eckhart Tolle', peli:'Into the Wild (2007)' },
        dificil: { libro:'El Hombre en Busca de Sentido — Viktor Frankl', peli:'Good Will Hunting (1997)' }
      }[_moodCat];

      var bodyTxt = '¡Hola'+(userName?' '+userName:'')+'! 💚\n\n'
        +'Estamos muy felices de que formes parte de nuestra comunidad. Tu presencia hace la diferencia.\n\n'
        +(aiText ? '─────────────────────\n'+aiText+'\n─────────────────────\n\n' : '')
        +'📊 TUS ÁNIMOS ESTA SEMANA\n'
        +'Registraste '+totalReg+' de 7 días ('+consistenciaPct+'% de consistencia)\n'
        +(distribLines.length ? distribLines.map(function(l){ return '  · '+l; }).join('\n')+'\n' : '')
        +(dominantMood ? 'Estado dominante: '+dominantMood+' '+(_moodLabel[dominantMood]||'')+'\n' : '')
        +'Tendencia: '+trendTxt+'\n'
        +(bestDay&&bestDay.mood?'🏆 Mejor día: '+dayNamesLong[['Do','Lu','Ma','Mi','Ju','Vi','Sa'].indexOf(bestDay.dayName)]||bestDay.dayName+' '+bestDay.mood.emoji+'\n':'')
        +(worstDay&&worstDay.mood&&worstDay!==bestDay?'⚡ Día más desafiante: '+(dayNamesLong[['Do','Lu','Ma','Mi','Ju','Vi','Sa'].indexOf(worstDay.dayName)]||worstDay.dayName)+' '+worstDay.mood.emoji+'\n':'')
        +'\n'
        +(weekDiary.length
          ? '📔 TU DIARIO\n'
            +'Escribiste '+weekDiary.length+' entrada'+(weekDiary.length!==1?'s':'')+' esta semana'
            +(diaryDays.length?' ('+diaryDays.join(', ')+')':'')+'\n\n'
          : '')
        +'📅 RACHA\n'
        +streak+' día'+(streak!==1?'s':'')+' seguidos en Velo'
        +(streak>=7?' 🔥 ¡Una semana completa!':streak>=3?' 💪 ¡Excelente ritmo!':'')+'\n\n'
        +(_wqB ? '❝ '+_wqB.q+'❞\n— '+_wqB.a+(_wqB.b?', '+_wqB.b:'')+'\n\n' : '')
        +(_mediaRec ? '📚 Para esta semana:\n  Libro: '+_mediaRec.libro+'\n  Película: '+_mediaRec.peli+'\n\n' : '')
        +'📋 El 1° de cada mes recibís un análisis completo de tu mes.\n\n¡Hasta el próximo domingo! 🌱';

      _inbox2.unshift({id:'weekly-'+todayKey,tipo:'sistema',icon:'📊',remitente:'Velo — Resumen Semanal',asunto:'Tu semana en Velo 🌱'+(dominantMood?' '+dominantMood:'')+' | '+consistenciaPct+'% constancia',extracto:aiText?aiText.slice(0,80)+'…':totalReg+'/7 días registrados ('+consistenciaPct+'%)',cuerpo:bodyTxt,leido:false,fecha:new Date().toLocaleDateString('es',{day:'2-digit',month:'short'})});
      safeLS('set','velo_inbox',JSON.stringify(_inbox2.slice(0,100)));
      if(typeof _updateInboxDot==='function') _updateInboxDot();
    }
  }, 3000);
}

async function _generateWeeklySummaryAI(timeline, dominantMood, streak, checkIns, diaryCount, userName, distribLines, trendTxt, bestDay, worstDay, activity){
  try{
    var _moodLabel = {'😄':'Genial','😊':'Bien','😐':'Neutro','😞':'Bajo','😢':'Difícil'};
    var dayNamesLong = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
    var dayNamesShort = ['Do','Lu','Ma','Mi','Ju','Vi','Sa'];
    var moodLines = timeline.map(function(d){
      return d.dayName+': '+(d.mood ? d.mood.emoji+' '+(_moodLabel[d.mood.emoji]||d.mood.label||d.mood.emoji) : '—');
    }).join('\n');
    var activityLines = '';
    if(activity){
      var lines = [];
      if(activity.btPosted>0) lines.push('Publicó '+activity.btPosted+' historia'+(activity.btPosted>1?'s':'')+' en Bitácora');
      if(activity.btReactionsReceived>0) lines.push('Recibió '+activity.btReactionsReceived+' reacciones a sus historias');
      if(activity.btCommentsReceived>0) lines.push('Recibió '+activity.btCommentsReceived+' comentarios');
      if(activity.btReactionsGiven>0 || activity.btCommentsGiven>0) lines.push('Apoyó a otros con '+(activity.btReactionsGiven+activity.btCommentsGiven)+' interacciones en Bitácora');
      if(activity.helpPosted>0) lines.push('Pidió acompañamiento en Sala de Ayuda '+activity.helpPosted+' vez'+(activity.helpPosted>1?'ces':''));
      if(activity.helpOffered>0) lines.push('Acompañó a '+activity.helpOffered+' persona'+(activity.helpOffered>1?'s':'')+' como Guardián');
      if(activity.dqAnswered>0) lines.push('Respondió la Pregunta del Día '+activity.dqAnswered+' vez'+(activity.dqAnswered>1?'ces':''));
      if(activity.dqComments>0) lines.push('Dejó '+activity.dqComments+' comentario'+(activity.dqComments>1?'s':'')+' en respuestas de la comunidad');
      if(activity.momentosPosted>0) lines.push('Compartió '+activity.momentosPosted+' momento'+(activity.momentosPosted>1?'s':''));
      if(lines.length) activityLines = '\nActividad en la comunidad:\n' + lines.map(function(l){return '• '+l;}).join('\n') + '\n';
      // Comparación con semana anterior
      if(activity.prevAvgScore>0 && activity.thisAvgScore>0){
        var diff = activity.thisAvgScore - activity.prevAvgScore;
        if(Math.abs(diff) > 0.3){
          activityLines += 'Comparado con la semana anterior: '+(diff>0?'ánimo promedio subió +'+(Math.round(diff*20))+'%':'bajó '+(Math.round(diff*20))+'%')+'\n';
        }
      }
    }
    var prompt = 'Sos un acompañante empático de Velo, una app de apoyo emocional. '
      +(userName?'El usuario se llama '+userName+'. ':'')
      +'Esta semana registró '+checkIns+' de 7 días. Sus ánimos día a día:\n'+moodLines+'\n'
      +(distribLines&&distribLines.length?'Distribución: '+distribLines.join(' · ')+'\n':'')
      +'Tendencia: '+trendTxt+'\n'
      +(bestDay&&bestDay.mood?'Mejor día: '+(dayNamesLong[dayNamesShort.indexOf(bestDay.dayName)]||bestDay.dayName)+' '+bestDay.mood.emoji+'\n':'')
      +(worstDay&&worstDay.mood&&worstDay!==bestDay?'Día más difícil: '+(dayNamesLong[dayNamesShort.indexOf(worstDay.dayName)]||worstDay.dayName)+' '+worstDay.mood.emoji+'\n':'')
      +'Racha: '+streak+' días seguidos en la app. '
      +(diaryCount>0?'Escribió en su diario '+diaryCount+' vez'+(diaryCount>1?'es':'')+' esta semana. ':'')
      +activityLines
      +'\nEscribí 3-4 oraciones cálidas y ULTRA específicas que:\n'
      +'1. Mencionen algo CONCRETO de su semana real (un día específico, o una actividad — ej: "acompañaste a X personas", "compartiste tu historia y recibiste apoyo")\n'
      +'2. Reconozcan gestos de generosidad hacia la comunidad si los hubo (comentarios que dejó, gente que acompañó)\n'
      +'3. Validen sus emociones con naturalidad\n'
      +'4. Cierren con una invitación GENUINA para la próxima semana basada en lo que ya está haciendo bien\n\n'
      +'REGLAS: NO empieces con "Hola" ni con el nombre. Empezá directo con la observación. '
      +'Tono cercano, cálido y humano — como un amigo cercano, no clínico. Sin hashtags. Sin listas. NUNCA uses "salud mental". '
      +'Máximo 90 palabras.';
    var text = await _geminiCall(prompt, { temperature:0.85, maxOutputTokens:220 });
    return text || null;
  }catch(e){ return null; }
}

