function _renderMomentoComments(comments,col,lightMode){
  var brd=col?col.border:'rgba(116,198,157,1)';
  var lbl=col?col.label:'rgba(200,240,218,1)';
  var strip=col?col.strip:'rgba(116,198,157,1)';
  var bg=col?col.bg:'rgba(6,28,18,.92)';
  var ca=function(c,a){ return c.replace(/,[\d.]+\)$/,','+a+')'); };
  // El contenedor #dqCommentFeed tiene fondo cream cuando lightMode=true.
  // Por eso NOMBRE, FECHA y TEXTO deben ser OSCUROS sobre cream, o CLAROS sobre el sheet oscuro.
  var textColor=lightMode?'rgba(20,25,20,.94)':'rgba(255,255,255,.94)';
  var nameLbl=lightMode?'rgba(10,55,30,.96)':ca(lbl,'.96');
  var textDim=lightMode?'rgba(60,80,60,.55)':'rgba(255,255,255,.50)';
  var unameCol=lightMode?'rgba(60,90,55,.65)':'rgba(255,255,255,.45)';
  var bubbleBg=lightMode?'rgba(255,238,170,.98)':ca(strip,'.20');
  var bubbleBdr=lightMode?'rgba(220,170,40,.65)':ca(brd,'.40');
  var bubbleLeft=lightMode?'rgba(220,140,20,.95)':ca(brd,'.80');
  if(!comments||!comments.length){
    return '<div style="text-align:center;padding:28px 8px 20px;font-family:\'Jost\',sans-serif">'
      +'<div style="font-size:36px;margin-bottom:10px;opacity:.60">💬</div>'
      +'<div style="font-size:14px;font-weight:700;color:'+(lightMode?'rgba(60,80,60,.55)':'rgba(255,255,255,.50)')+';margin-bottom:4px">Todavía no hay comentarios</div>'
      +'<div style="font-size:14px;color:'+(lightMode?'rgba(60,80,60,.32)':'rgba(255,255,255,.28)')+'">Sé el primero en sumar algo 🌿</div>'
      +'</div>';
  }
  var _curUid = safeLS('get','velo_user_id') || '';
  var _curUname = safeLS('get','velo_username') || '';
  return comments.map(function(c){
    var name=c.user_name||'Anónimo/a';
    var isAnon = (name === 'Anónimo' || name === 'Anónimo/a' || name === 'anónimo');
    // Para Anónimo SIEMPRE ignoramos el avatar guardado (comentarios viejos pueden traer el avatar real del usuario)
    var av = isAnon ? '' : (c.user_avatar||'');
    var isImg=av&&av.startsWith('http');
    // Avatar fill — para Anónimo usamos 🕊️ (paloma); default 🌿
    var avEmoji = av || (isAnon ? '🕊️' : '🌿');
    // Solid bg (no gradient that swallows the emoji) + tamaño 40px con emoji 22px
    var avBg = isAnon
      ? (lightMode ? 'rgba(180,210,245,.95)' : 'rgba(60,100,170,.45)')
      : ca(strip,'.55');
    var avBdr = isAnon
      ? (lightMode ? 'rgba(95,140,210,.65)' : ca(brd,'.65'))
      : ca(brd,'.65');
    // Clickable profile when NOT anon and user_id is present → abre pQuickProfile
    var canClick = !isAnon && c.user_id;
    // Username fallback — si es del usuario actual y la hidratación no trajo nada, usar localStorage
    var unameVal = c.username || (canClick && _curUid && String(c.user_id) === String(_curUid) ? _curUname : '');
    var profileArgs = '\''+_jsAttr(name)+'\',\''+_jsAttr(av)+'\',\'\',\''+_jsAttr(unameVal||'')+'\',\''+_jsAttr(String(c.user_id||''))+'\'';
    var clickAttr = canClick ? ' onclick="pQuickProfile('+profileArgs+')" style="cursor:pointer"' : '';
    var avClickStyle = canClick ? 'cursor:pointer;' : '';
    var avHtml=isImg
      ?'<img src="'+_escHtml(av)+'"'+(canClick?' onclick="pQuickProfile('+profileArgs+')"':'')+' style="'+avClickStyle+'width:40px;height:40px;border-radius:50%;object-fit:cover;border:2px solid '+ca(brd,'.60')+';flex-shrink:0;box-shadow:0 2px 8px rgba(0,0,0,.18)">'
      :'<div'+(canClick?' onclick="pQuickProfile('+profileArgs+')"':'')+' style="'+avClickStyle+'width:40px;height:40px;border-radius:50%;background:'+avBg+';display:flex;align-items:center;justify-content:center;font-size:22px;line-height:1;flex-shrink:0;border:2px solid '+avBdr+';box-shadow:0 2px 8px rgba(0,0,0,.20)">'+_escHtml(avEmoji)+'</div>';
    // Username @ debajo del nombre (solo no-anon y si profile tiene username)
    var unameLine = (canClick && unameVal)
      ? '<div style="font-size:11.5px;font-weight:600;color:'+unameCol+';font-family:Jost,sans-serif;line-height:1;margin-top:2px">@'+_escHtml(unameVal)+'</div>'
      : '';
    var nameClickAttr = canClick ? ' onclick="pQuickProfile('+profileArgs+')" style="cursor:pointer"' : '';
    return '<div style="display:flex;gap:11px;margin-bottom:14px;align-items:flex-start">'
      +avHtml
      +'<div style="flex:1;min-width:0">'
      +'<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:6px;margin-bottom:5px">'
      +'<div style="min-width:0"><span'+nameClickAttr+' style="font-size:14px;font-weight:800;color:'+nameLbl+';font-family:\'Jost\',sans-serif;letter-spacing:.1px'+(canClick?';cursor:pointer':'')+'">'+_escHtml(name)+'</span>'+unameLine+'</div>'
      +'<span style="font-size:12px;color:'+textDim+';font-family:\'Jost\',sans-serif;flex-shrink:0">'+_momentoAgo(c.created_at)+'</span>'
      +'</div>'
      +'<div style="background:'+bubbleBg+';border:1.5px solid '+bubbleBdr+';border-left:3px solid '+bubbleLeft+';border-radius:0 14px 14px 14px;padding:10px 14px;font-size:15px;color:'+textColor+';line-height:1.55;word-break:break-word;box-shadow:0 2px 8px rgba(0,0,0,.12)">'+_escHtml(c.text||'')+'</div>'
      +'</div>'
      +'</div>';
  }).join('');
}

async function pPostMomentoComment(momentoId){
  var inp=document.getElementById('momentoCommentInput');
  if(!inp) return;
  var text=(inp.value||'').trim();
  if(!text) return;
  var btn=document.getElementById('momentoCommentBtn');
  if(btn){btn.disabled=true;btn.textContent='...';}
  _initSupabase();
  if(!sbClient){ pToast('⚠️','Sin conexión'); if(btn){btn.disabled=false;btn.textContent='Enviar';} return; }
  var data={momento_id:String(momentoId),text:text,user_hash:_momentoUserHash(),created_at:new Date().toISOString()};
  var pn=safeLS('get','velo_user_name'); var pav=safeLS('get','velo_user_av'); var uid=safeLS('get','velo_user_id');
  if(pn) data.user_name=pn;
  if(pav) data.user_avatar=pav;
  if(uid) data.user_id=uid;
  var res=await sbClient.from('momento_comments').insert(data);
  if(res.error){
    // Table doesn't exist yet
    if(res.error.code==='42P01'||res.error.code==='PGRST200'){
      pToast('🛠️','La tabla de comentarios aún no está creada en la base de datos');
      if(btn){btn.disabled=false;btn.textContent='Enviar';} return;
    }
    // Profile columns missing — retry without them
    if(res.error.code==='42703'||res.error.code==='PGRST204'||(res.error.message&&res.error.message.indexOf('user_avatar')>=0)){
      delete data.user_name; delete data.user_avatar;
      res=await sbClient.from('momento_comments').insert(data);
      if(res.error){ pToast('⚠️','Error al comentar'); if(btn){btn.disabled=false;btn.textContent='Enviar';} return; }
    } else { pToast('⚠️','Error: '+res.error.message); if(btn){btn.disabled=false;btn.textContent='Enviar';} return; }
  }
  inp.value='';
  pToast('💬','Comentario publicado');
  var _mOwnerItem=_homeMomentoCache&&_homeMomentoCache.find(function(m){return String(m.id)===String(momentoId);});
  if(_mOwnerItem&&_mOwnerItem.user_id){
    _createVeloNotif(_mOwnerItem.user_id,'momento_comment',(safeLS('get','velo_user_name')||'Alguien')+' comentó tu momento',text.slice(0,80),momentoId);
  }
  var comments=await _loadMomentoComments(momentoId);
  var feed=document.getElementById('momentoCommentFeed');
  if(feed) feed.innerHTML=_renderMomentoComments(comments);
  if(btn){btn.disabled=false;btn.textContent='Enviar';}
}

