async function pDeleteMomento(momentoId, btnEl, fromModal){
  if(!confirm('¿Borrar este momento? No se puede deshacer.')) return;
  _initSupabase(); if(!sbClient) return;
  try {
    var res = await sbClient.from('momentos').delete().eq('id', String(momentoId));
    if(res.error){ console.warn('[pDeleteMomento]', res.error); return; }
    _homeMomentoCache = (_homeMomentoCache||[]).filter(function(m){ return String(m.id) !== String(momentoId); });
    var sh = document.getElementById('momentoDetailSheetOv');
    if(sh) sh.remove();
    if(btnEl){
      var card = typeof btnEl.closest==='function' ? btnEl.closest('.home-mc') : null;
      if(card) card.remove();
    }
    _renderMomentoCards(_homeMomentoCache.slice(0,4), 'homeMomentoFeed');
    _initCarouselDots('homeMomentoFeed','momentoDots');
  } catch(e){ console.warn('[pDeleteMomento]', e); }
}
async function _initHomeMomento(){
  var section=document.getElementById('homeMomentoSection');
  if(!section) return;
  // Streak badge
  var streak=_momentoStreak();
  var badge=document.getElementById('momentoStreakBadge');
  if(badge){
    if(streak>=2){ badge.style.display=''; badge.textContent='🔥 '+streak+' días seguidos'; }
    else { badge.style.display='none'; }
  }
  // Daily prompt for Muro Feliz tab
  var pt=document.getElementById('happyPromptText');
  if(pt) pt.textContent=_happyDailyPrompt();

  var momentos=await _fetchMomentos(10);
  if(momentos===null){ section.style.display='none'; return; }
  _homeMomentoCache = momentos || [];
  section.style.display='block';
  _renderMomentoCards(momentos.slice(0,4),'homeMomentoFeed');
  _initCarouselDots('homeMomentoFeed','momentoDots');
  _initMomentoProfileToggle();
  _updateFeedTabCounts();
}

var _homeActiveFeedTab = 'momento';
var _homeMomentoCache = [];

function pHomeTabSwitch(tab){
  _homeActiveFeedTab = tab;
  var tM = document.getElementById('hfTab-momento');
  var tH = document.getElementById('hfTab-happy');
  var cM = document.getElementById('homeTabMomento');
  var cH = document.getElementById('homeTabHappy');
  if(!tM||!tH||!cM||!cH) return;
  if(tab === 'happy'){
    tH.className = 'hf-tab hf-tab--active-happy';
    tM.className = 'hf-tab hf-tab--inactive';
    cM.style.display = 'none';
    cH.style.display = '';
    _loadHomeHappyFeed();
  } else {
    tM.className = 'hf-tab hf-tab--active';
    tH.className = 'hf-tab hf-tab--inactive-happy';
    cH.style.display = 'none';
    cM.style.display = '';
  }
}

async function _updateFeedTabCounts(){
  if(!sbClient) return;
  var cutoff = new Date(Date.now()-24*60*60*1000).toISOString();
  try{
    var rM = await sbClient.from('momentos').select('id',{count:'exact',head:true}).gte('created_at',cutoff);
    var nM = rM.count || 0;
    var cntM = document.getElementById('hfTab-momento-cnt');
    if(cntM) cntM.textContent = nM > 0 ? nM+(nM===1?' momento hoy':' momentos hoy') : '';
  }catch(e){}
  try{
    var rH = await sbClient.from('happy_posts').select('id',{count:'exact',head:true}).gte('created_at',cutoff);
    var nH = rH.count || 0;
    var cntH = document.getElementById('hfTab-happy-cnt');
    if(cntH) cntH.textContent = nH > 0 ? nH+(nH===1?' momento hoy':' momentos hoy') : '';
  }catch(e){}
}

/* ── v957: Home Muro Feliz cards — 💬 action opens full sheet ── */
var _happyHomePosts = [];

