// ── DAILY STATUS ──────────────────────────────────────────────
function _todayStatusKey(){
  var d = new Date();
  return 'velo_daily_status_'+d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}

function pInitDailyStatus(){
  var key = _todayStatusKey();
  var saved = {}; try{ saved = JSON.parse(safeLS('get', key)||'{}'); }catch(e){}
  // Pre-fill from persistent profile keys so both forms always show the same data
  var el;
  el = document.getElementById('statusMusic');  if(el) el.value = saved.music  || safeLS('get','velo_status_music')  || '';
  el = document.getElementById('statusBook');   if(el) el.value = saved.book   || safeLS('get','velo_status_book')   || '';
  el = document.getElementById('statusMovie');  if(el) el.value = saved.movie  || safeLS('get','velo_status_film')   || '';
  el = document.getElementById('statusPhrase'); if(el) el.value = saved.phrase || safeLS('get','velo_status_phrase') || '';
}

async function pSaveDailyStatus(){
  var movie  = document.getElementById('statusMovie')  ? document.getElementById('statusMovie').value.trim()  : '';
  var music  = document.getElementById('statusMusic')  ? document.getElementById('statusMusic').value.trim()  : '';
  var book   = document.getElementById('statusBook')   ? document.getElementById('statusBook').value.trim()   : '';
  var phrase = document.getElementById('statusPhrase') ? document.getElementById('statusPhrase').value.trim() : '';
  var key = _todayStatusKey();
  safeLS('set', key, JSON.stringify({ movie:movie, music:music, book:book, phrase:phrase, ts:Date.now() }));
  // Also persist to cross-device profile keys so other users always see current data
  safeLS('set','velo_status_film',   movie);
  safeLS('set','velo_status_music',  music);
  safeLS('set','velo_status_book',   book);
  safeLS('set','velo_status_phrase', phrase);
  // Push to Supabase so it survives across devices and sessions
  _initSupabase();
  var uid = safeLS('get','velo_user_id');
  if(sbClient && uid){
    try{
      var {data:_sd2} = await sbClient.auth.getSession();
      if(_sd2 && _sd2.session && _sd2.session.user && _sd2.session.user.id) uid = _sd2.session.user.id;
      await sbClient.from('profiles').upsert({
        id: uid, status_film: movie, status_music: music,
        status_book: book, status_phrase: phrase
      },{ onConflict:'id' });
    }catch(e){}
  }
  pToast('✨','Estado del día guardado 💚');
}

function _getDailyStatus(){
  var key = _todayStatusKey();
  try{ return JSON.parse(safeLS('get',key)||'{}'); }catch(e){ return {}; }
}

// ── GLOBAL CONTENT REPORT ─────────────────────────────────────
var _rptPreview = '';
function pReportContent(type, id, preview){
  _rptPreview = preview || '';
  var reasons = ['Contenido agresivo o hiriente','Discurso de odio o discriminación','Spam o autopromoción','Información médica incorrecta o peligrosa','Acoso o bullying','Sugerencias de autolesión','Otro'];
  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.id = 'globalReportOv';
  ov.innerHTML = '<div class="p-sheet">'
    +'<div class="p-sheet-handle"></div>'
    +'<div style="font-size:28px;text-align:center;margin-bottom:8px">⚠️</div>'
    +'<div style="font-family:\'Cormorant Garamond\',serif;font-size:20px;color:var(--ink);text-align:center;margin-bottom:8px">Reportar contenido</div>'
    +(preview ? '<div style="font-size:14px;color:var(--ink4);background:var(--cream2);border-radius:10px;padding:10px;margin-bottom:14px;font-style:italic;line-height:1.5">'+_escHtml(preview.slice(0,120))+(preview.length>120?'…':'')+'</div>' : '')
    +'<div style="font-size:14px;font-weight:700;color:var(--ink3);margin-bottom:8px">¿Por qué lo reportás?</div>'
    +'<div style="display:flex;flex-direction:column;gap:6px;margin-bottom:14px" id="rptGlobalReasons">'
    +reasons.map(function(r,i){
      return '<label style="display:flex;align-items:center;gap:10px;font-size:15px;color:var(--ink3);cursor:pointer;padding:8px;border-radius:10px;border:1.5px solid var(--border);transition:border-color .15s" onclick="this.style.borderColor=\'var(--sage3)\'">'
        +'<input type="radio" name="rptGlobal" value="'+r+'" style="accent-color:var(--sage2)"> '+r+'</label>';
    }).join('')
    +'</div>'
    +'<textarea class="p-textarea" id="rptGlobalDetail" rows="2" placeholder="Descripción adicional (opcional)" style="margin-bottom:12px"></textarea>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="p-btn p-btn--md p-btn--full" style="background:var(--sos);border-color:var(--sos);color:#fff;font-family:\'Jost\',sans-serif;font-size:15px;font-weight:700;padding:11px;border-radius:14px;cursor:pointer" onclick="pSubmitGlobalReport(\''+type+'\',\''+id+'\')">Enviar reporte</button>'
    +'<button class="p-btn p-btn--secondary p-btn--md p-btn--full" onclick="document.getElementById(\'globalReportOv\').remove()">Cancelar</button>'
    +'</div>'
    +'</div>';
  document.body.appendChild(ov);
}

function pSubmitGlobalReport(type, id){
  var checked = document.querySelector('input[name="rptGlobal"]:checked');
  if(!checked){ pToast('⚠️','Seleccioná un motivo'); return; }
  var detail = (document.getElementById('rptGlobalDetail') ? document.getElementById('rptGlobalDetail').value.trim() : '');
  var ov = document.getElementById('globalReportOv');
  if(ov) ov.remove();

  // Save to audit log
  var audit = []; try{ audit = JSON.parse(safeLS('get','velo_audit_log')||'[]'); }catch(e){}
  var reportId = type+'-'+id;
  audit.unshift({ ts:Date.now(), tipo:'report_'+type, contentId:id, motivo:checked.value, detail:detail, resolved:false });
  safeLS('set','velo_audit_log', JSON.stringify(audit.slice(0,500)));

  // AI review: verify if content truly violates rules, using preview stored at open time
  _aiReviewReport(type, id, detail || _rptPreview, checked.value);

  // Mark content as hidden until admin resolves
  var hidden = []; try{ hidden = JSON.parse(safeLS('get','velo_hidden_content')||'[]'); }catch(e){}
  if(hidden.indexOf(reportId) < 0){ hidden.push(reportId); safeLS('set','velo_hidden_content', JSON.stringify(hidden)); }

  // Hide the reported content from UI
  if(type === 'bottle'){
    safeLS('set','velo_reported_bottle_'+id,'1');
    var bottleCard = document.getElementById('bottle-'+id) || document.querySelector('[data-id="'+id+'"]');
    if(bottleCard){ bottleCard.style.transition='opacity .35s'; bottleCard.style.opacity='0'; setTimeout(function(){ pRenderBottle(); }, 380); }
  } else if(type === 'happy'){
    var happyCard = document.querySelector('.happy-card[data-id="'+id+'"]');
    if(happyCard){ happyCard.style.transition='opacity .35s'; happyCard.style.opacity='0'; setTimeout(function(){ happyCard.remove(); }, 380); }
  } else if(type === 'help'){
    var helpCard = document.getElementById('help-'+id) || document.querySelector('[data-id="'+id+'"]');
    if(helpCard){ helpCard.style.transition='opacity .35s'; helpCard.style.opacity='0'; setTimeout(function(){ helpCard.remove(); }, 380); }
  }

  pToast('✅','Reporte enviado. El contenido quedó oculto hasta que lo revise el equipo de Velo 🙏');
}

function pReportDMChat(){
  if(!_dmPeer) return;
  pReportContent('dm', 'dm-'+_dmPeer.id, 'Chat con '+(_dmPeer.name||'usuario'));
}

async function _aiReviewReport(type, id, content, userReason){
  if(!content || content.length < 5) return;
  var prompt = 'Sos el sistema de moderación de Velo, una app de bienestar emocional entre pares.\n'
    +'Un usuario reportó este contenido con el motivo: "'+userReason+'".\n'
    +'Analizá el contenido y determiná si realmente viola las normas de la comunidad.\n'
    +'Normas violadas: acoso, agresión, discriminación, spam, información médica peligrosa, incitación a autolesiones.\n'
    +'NO es violación: expresiones de dolor, tristeza, crisis personal, pedidos de ayuda genuinos.\n'
    +'Respondé SOLO con JSON: {"viola": true/false, "tipo": "acoso|spam|contenido_peligroso|ninguno", "gravedad": "alta|media|baja", "justificacion": "breve razon"}\n\n'
    +'Contenido reportado: "'+content.replace(/"/g,"'").slice(0,300)+'"';
  try{
    var result = await _geminiCall(prompt);
    if(!result) return;
    var match = result.match(/\{[\s\S]*\}/);
    if(!match) return;
    var data = JSON.parse(match[0]);
    _initSupabase();
    if(data.viola && sbClient){
      sbClient.from('moderation_flags').insert({
        section: type, tipo: data.tipo, gravedad: data.gravedad||'media',
        content: content.slice(0,300), user_id: safeLS('get','velo_user_id')||'',
        resolved: false, resolution: null
      }).then(function(){
        _notifyAdminsNewReport('🤖 Alerta IA: '+data.tipo, 'Contenido reportado por usuario y confirmado por IA en "'+type+'". Gravedad: '+(data.gravedad||'media')+'. Revisá el panel de Moderación.');
      }).catch(function(){});
    }
    var audit = []; try{ audit = JSON.parse(safeLS('get','velo_audit_log')||'[]'); }catch(e){}
    audit[0] = Object.assign(audit[0]||{}, { aiVerdict: data.viola ? 'VIOLA:'+data.tipo : 'ok', aiJustif: data.justificacion });
    safeLS('set','velo_audit_log', JSON.stringify(audit.slice(0,500)));
  }catch(e){}
}

function _isHidden(type, id){
  try{ var h = JSON.parse(safeLS('get','velo_hidden_content')||'[]'); return h.indexOf(type+'-'+id) >= 0; }catch(e){ return false; }
}

// ── PROFILE EXTRAS: DELETE ACCOUNT, CANCEL SUB, CONTACT ────────
function pDeleteAccount(){
  var isDark = document.body.classList.contains('r-dark');
  var bg   = isDark ? '#162a1e' : '#fff';
  var brd  = isDark ? 'border:1px solid rgba(255,80,80,.2);' : 'border:1px solid rgba(220,60,50,.12);';
  var inkC = isDark ? 'rgba(255,255,255,.9)' : 'var(--ink)';
  var sub  = isDark ? 'rgba(255,255,255,.55)' : 'var(--ink4)';
  var inp  = isDark ? 'background:rgba(255,255,255,.06);color:#fff;border-color:rgba(255,255,255,.15)' : '';
  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.innerHTML = '<div class="p-sheet" style="background:'+bg+';'+brd+'max-width:440px;margin:auto">'
    +'<div class="p-sheet-handle"></div>'
    +'<div style="font-size:36px;text-align:center;margin-bottom:10px">🗑️</div>'
    +'<div style="font-family:\'Cormorant Garamond\',serif;font-size:21px;color:'+inkC+';text-align:center;margin-bottom:8px;font-weight:700">¿Eliminar tu cuenta?</div>'
    +'<p style="font-size:15px;color:'+sub+';text-align:center;line-height:1.6;margin-bottom:18px">Esta acción es <strong>irreversible</strong>. Se eliminarán tu perfil, mensajes, publicaciones y presencia de los contactos de otros usuarios.<br><br>Si querés volver a usar Velo con el mismo correo, podés registrarte de nuevo como usuario nuevo.</p>'
    +'<div class="p-field" style="margin-bottom:14px">'
    +'<label class="p-field-label" style="color:'+inkC+'">¿Por qué te vas? <span style="color:'+sub+';font-weight:400">(opcional)</span></label>'
    +'<textarea class="p-textarea" id="deleteReasonInput" rows="3" placeholder="Contanos el motivo para mejorar Velo…" style="'+inp+';resize:none;width:100%;box-sizing:border-box"></textarea></div>'
    +'<div class="p-field" style="margin-bottom:16px">'
    +'<label class="p-field-label" style="color:'+inkC+'">Escribí <strong>ELIMINAR</strong> para confirmar</label>'
    +'<input class="p-input" type="text" id="deleteConfirmInput" placeholder="ELIMINAR" style="'+inp+'"></div>'
    +'<div style="display:flex;gap:8px">'
    +'<button class="p-btn p-btn--md p-btn--full" style="background:#c0312a;border-color:#c0312a;color:#fff;font-family:\'Jost\',sans-serif;font-weight:700;padding:12px;border-radius:14px;cursor:pointer" onclick="pConfirmDelete(this.closest(\'.p-modal-ov\'))">Eliminar cuenta</button>'
    +'<button class="p-btn p-btn--secondary p-btn--md p-btn--full" style="padding:12px" onclick="this.closest(\'.p-modal-ov\').remove()">Cancelar</button>'
    +'</div>'
    +'</div>';
  document.body.appendChild(ov);
}

function pConfirmDelete(ov){
  var input = document.getElementById('deleteConfirmInput');
  if(!input || input.value.trim().toUpperCase() !== 'ELIMINAR'){ pToast('⚠️','Escribí ELIMINAR para confirmar'); return; }
  var reason = (document.getElementById('deleteReasonInput')||{}).value||'';
  if(ov) ov.remove();
  pToast('🗑️','Eliminando tu cuenta…');
  _execDeleteAccount(reason.trim());
}

function _clearAllLocalData(){
  var keys = [];
  try{ for(var i=0;i<localStorage.length;i++){ var k=localStorage.key(i); if(k&&k.startsWith('velo_')) keys.push(k); } }catch(e){}
  keys.forEach(function(k){ safeLS('del',k); });
}

function _showDeleteErrorAlert(msg, isWarning){
  var ov = document.createElement('div');
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.82);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px';
  var title = isWarning ? '⚠️ Errores al eliminar — copiá esto' : '❌ No se pudo eliminar la cuenta';
  ov.innerHTML = '<div style="background:#1a0a0a;border:2px solid #c0312a;border-radius:16px;padding:24px;max-width:420px;width:100%;max-height:80vh;overflow-y:auto">'
    +'<div style="font-size:15px;font-weight:700;color:#ff6b6b;margin-bottom:12px">'+title+'</div>'
    +'<pre id="_delErrPre" style="font-size:13px;color:#ffb3b3;white-space:pre-wrap;word-break:break-all;background:rgba(255,255,255,.06);border-radius:8px;padding:12px;margin:0 0 16px;line-height:1.6">'+_escHtml(msg)+'</pre>'
    +'<div style="display:flex;gap:8px">'
    +'<button id="_delErrCopy" style="flex:1;padding:10px;background:rgba(255,107,107,.15);border:1px solid #ff6b6b;border-radius:10px;color:#ff6b6b;font-size:15px;font-weight:600;cursor:pointer;font-family:\'Jost\',sans-serif">📋 Copiar error</button>'
    +'<button id="_delErrClose" style="flex:1;padding:10px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.2);border-radius:10px;color:rgba(255,255,255,.7);font-size:15px;font-weight:600;cursor:pointer;font-family:\'Jost\',sans-serif">Cerrar</button>'
    +'</div>'
    +'</div>';
  document.body.appendChild(ov);
  var copyBtn  = document.getElementById('_delErrCopy');
  var closeBtn = document.getElementById('_delErrClose');
  if(copyBtn) copyBtn.addEventListener('click', function(){
    if(navigator.clipboard) navigator.clipboard.writeText(msg).then(function(){ copyBtn.textContent = '✅ Copiado'; }).catch(function(){});
    else { var ta=document.createElement('textarea'); ta.value=msg; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); copyBtn.textContent='✅ Copiado'; }
  });
  if(closeBtn) closeBtn.addEventListener('click', function(){ ov.remove(); });
}

async function _execDeleteAccount(reason){
  _initSupabase();
  var uid   = safeLS('get','velo_user_id') || '';
  var email = safeLS('get','velo_user_email') || '';
  try{
    if(sbClient){
      // Refresh session so JWT is valid for the RPC call
      try{ var {data:_rD} = await sbClient.auth.refreshSession();
        if(_rD && _rD.user){ uid = _rD.user.id || uid; email = _rD.user.email || email; }
      }catch(e){}
      try{ var {data:_gD} = await sbClient.auth.getUser();
        if(_gD && _gD.user){ uid = _gD.user.id || uid; email = _gD.user.email || email; }
      }catch(e){}

      if(uid){
        // Log deletion request (best-effort)
        try{ sbClient.from('deleted_accounts').insert({
          email: email, user_id: uid, reason: reason||null, deleted_at: new Date().toISOString()
        }).catch(function(){}); }catch(e){}

        // 0) Intentar Edge Function `delete-account` (service-role → borra auth.users → libera email)
        //    Si la function no está deployada todavía, sigue al RPC + fallback (no rompe nada).
        var edgeOk = false;
        try{
          var _fnRes = await sbClient.functions.invoke('delete-account', { body:{ reason: reason||null } });
          if(_fnRes && !_fnRes.error) edgeOk = true;
        }catch(e){}

        // 1) Intentar RPC server-side (elimina de auth.users también)
        var rpcOk = edgeOk; // si Edge Function ya borró auth.users, no necesitamos el RPC
        if(!edgeOk){
          try{
            var {error:_rpcErr} = await sbClient.rpc('delete_my_account', { p_reason: reason || null });
            if(!_rpcErr) rpcOk = true;
          }catch(e){}
        }

        // 2) Fallback cliente: borrar tabla por tabla (best-effort, silencioso)
        if(!rpcOk){
          var _del = function(p){ return Promise.resolve(p).catch(function(){}); };
          await _del(sbClient.from('user_favorites').delete().eq('user_id', uid));
          await _del(sbClient.from('user_favorites').delete().eq('fav_id', uid));
          await _del(sbClient.from('guardian_presence').delete().eq('user_id', uid));
          await _del(sbClient.from('direct_messages').delete().or('from_id.eq.'+uid+',to_id.eq.'+uid));
          await _del(sbClient.from('guardian_requests').delete().or('seeker_id.eq.'+uid+',guardian_id.eq.'+uid));
          await _del(sbClient.from('help_posts').delete().eq('user_id', uid));
          await _del(sbClient.from('happy_posts').delete().eq('user_id', uid));
          await _del(sbClient.from('daily_responses').delete().eq('user_id', uid));
          await _del(sbClient.from('mood_entries').delete().eq('user_id', uid));
          await _del(sbClient.from('bitacora_entries').delete().eq('user_id', uid));
          await _del(sbClient.from('bitacora_comments').delete().eq('user_id', uid));
          await _del(sbClient.from('bitacora_comment_reactions').delete().eq('user_id', uid));
          await _del(sbClient.from('dq_reactions').delete().eq('user_id', uid));
          await _del(sbClient.from('profiles').update({
            nombre:'[eliminado]', avatar:'🌿', motto:'', bio:'',
            push_subscription:null, helped_count:0, received_count:0
          }).eq('id', uid));
        }
      }
    }
  }catch(e){}
  // SIEMPRE: cerrar sesión + limpiar local + redirigir, pase lo que pase
  try{ if(sbClient) await sbClient.auth.signOut(); }catch(e){}
  try{ _clearAllLocalData(); }catch(e){}
  try{ _authenticated = false; _favsList = null; }catch(e){}
  pToast('👋','Tu cuenta fue eliminada 🌿');
  setTimeout(function(){
    try{ window.location.replace(window.location.href.split('?')[0].split('#')[0]); }
    catch(e){ try{ window.location.reload(); }catch(e2){} }
  }, 1800);
}

