function _btToggleTema(t){
  var ov=document.getElementById('btComposeOv');
  if(!ov) return;
  var cur=ov.dataset.tema||'';
  var next=cur===t?'':t;
  ov.dataset.tema=next;
  var type=ov.dataset.type||'apoyo';
  var ac=_btCmpAccent[type]||_btCmpAccent.apoyo;
  document.querySelectorAll('#btCmpTemas button').forEach(function(el){
    var isAct=el.dataset.tema===next;
    el.style.background=isAct?ac.pill:'rgba(255,255,255,.05)';
    el.style.borderColor=isAct?ac.pillBorder:'rgba(255,255,255,.14)';
    el.style.color=isAct?'rgba(255,255,255,.92)':'rgba(255,255,255,.40)';
  });
}
function _btCmpCounter(el){
  var cnt=document.getElementById('btCmpCharCount');
  if(cnt) cnt.textContent=(el.value.length)+' / 2000';
}
function _btToggleSave(id,e){
  if(e) e.stopPropagation();
  var idx=_btSavedIds.indexOf(id);
  if(idx>=0) _btSavedIds.splice(idx,1); else _btSavedIds.push(id);
  safeLS('set','bt_saved',JSON.stringify(_btSavedIds));
  var btn=document.getElementById('btSave-'+id);
  var isSaved=_btSavedIds.indexOf(id)>=0;
  if(btn){
    btn.style.background=isSaved?'rgba(80,110,230,.85)':'transparent';
    btn.style.color=isSaved?'#fff':'rgba(80,110,230,.9)';
    btn.style.border=isSaved?'none':'1.5px solid rgba(80,110,230,.5)';
    btn.textContent=isSaved?'✓ Siguiendo':'+ Seguir';
  }
}
function _btAutoTema(text){
  var t=(text||'').toLowerCase();
  var map=[['Amor',['amor','enamorado','enamorada','pareja','noviazgo']],['Ansiedad',['ansiedad','ansioso','ansiosa','pánico','nervios']],['Familia',['familia','padre','madre','hijo','hija','hermano','hermana','padres']],['Soledad',['soledad','solo','sola','aislado','aislada']],['Trauma',['trauma','abuso','maltrato','violencia','herida']],['Duelo',['duelo','muerte','fallecio','falleció','pérdida','luto']],['Autoestima',['autoestima','confianza','inseguro','insegura','valgo']],['LGBTQ+',['gay','lesbiana','bisexual','trans','lgbtq','queer']],['Adicciones',['adicción','adicto','adicta','droga','alcohol','vicio']],['Sexualidad',['sexo','sexual','sexualidad','intimidad']]];
  for(var i=0;i<map.length;i++){
    for(var j=0;j<map[i][1].length;j++){
      if(t.indexOf(map[i][1][j])>=0) return map[i][0];
    }
  }
  return '';
}
function _btUpdateTemaFilter(){
  var el=document.getElementById('btTemaFilter');
  if(!el) return;
  el.style.display='';
  var type=_btCurrentTab;
  if(type==='mio'||type==='guardados'){ el.innerHTML=''; return; }
  var isLight=!document.body.classList.contains('r-dark');
  var temas=['Todos'].concat(_btTemas[type]||[]);
  var c=(isLight?(_btColorsLight[type]||_btColorsLight.apoyo):(_btColors[type]||_btColors.apoyo));
  var offBg=isLight?'rgba(255,255,255,.70)':'rgba(255,255,255,.05)';
  var offBd=isLight?'rgba(100,100,130,.20)':'rgba(255,255,255,.12)';
  var offCl=isLight?'rgba(50,50,80,.65)':'rgba(255,255,255,.40)';
  el.innerHTML=temas.map(function(t){
    var isAct=(t==='Todos'?(!_btTemaFilter):(t===_btTemaFilter));
    var bg=isAct?(isLight?c.strip.replace(/[\d.]+\)$/,'.35)'):c.strip.replace(/[\d.]+\)$/,'.55)')):offBg;
    var bd=isAct?c.border:offBd;
    var cl=isAct?c.label:offCl;
    return '<button onclick="_btSetTemaFilter(\''+t+'\')" style="padding:5px 11px;border-radius:20px;border:1.5px solid '+bd+';background:'+bg+';color:'+cl+';font-size:13px;font-weight:'+(isAct?'700':'500')+';font-family:Jost,sans-serif;cursor:pointer;white-space:nowrap;transition:all .15s">'+t+'</button>';
  }).join('');
}
function _btSetTemaFilter(t){
  _btTemaFilter=(t==='Todos'?'':t);
  _btUpdateTemaFilter();
  _btApplyFilters();
}
function _btRelevanceScore(p){
  var rx=_btReactMap[p.id]||_btEmptyRx();
  var rxKeys=['resuena','ayudo','cambio','apoyo_a','apoyo_b','apoyo_te','entiendo','abrazo','acompano','inspiro','concuerdo','no_concuerdo','neutral'];
  var rxTotal=0; rxKeys.forEach(function(k){ rxTotal+=(rx[k]||0); });
  return rxTotal+(_btCommentCounts[p.id]||0)*2;
}
function _btToggleSort(){
  _btSortMode=(_btSortMode==='recent'?'relevante':'recent');
  var btn=document.getElementById('btSortBtn');
  if(btn){
    var isRel=_btSortMode==='relevante';
    var _isLt=!document.body.classList.contains('r-dark');
    btn.textContent=isRel?'🔥 Relevantes':'🕐 Recientes';
    btn.style.background=isRel?(_isLt?'rgba(220,80,20,.12)':'rgba(255,130,50,.18)'):(_isLt?'rgba(50,80,60,.10)':'rgba(255,255,255,.07)');
    btn.style.borderColor=isRel?'rgba(255,130,50,.45)':(_isLt?'rgba(50,80,60,.28)':'rgba(255,255,255,.14)');
    btn.style.color=isRel?(_isLt?'rgba(160,50,10,.90)':'rgba(255,160,80,.95)'):(_isLt?'rgba(30,60,40,.75)':'rgba(200,210,205,.65)');
  }
  _btRenderFeed(_btCurrentTab);
}
function _btApplyFilters(){
  var q=((document.getElementById('btSearch')||{}).value||'').trim().toLowerCase();
  _btSearchQ=q;
  if(q){
    // Global search across all tabs
    var allPosts=(_btPosts.apoyo||[]).concat(_btPosts.superacion||[]).concat(_btPosts.debate||[]);
    var feed=document.getElementById('btFeed');
    if(!feed) return;
    var uid=safeLS('get','velo_user_id');
    var matched=allPosts.filter(function(p){ return !_btHiddenIds.has(String(p.id))||String(p.user_id)===String(uid); });
    matched=matched.filter(function(p){
      var haystack=((p.titulo||'')+' '+(p.contenido||'')+' '+(p.author_name||'')).toLowerCase();
      return haystack.indexOf(q)>=0;
    });
    // Sort: title matches first, then body matches
    matched.sort(function(a,b){
      var aTitle=((a.titulo||'')).toLowerCase().indexOf(q)>=0?0:1;
      var bTitle=((b.titulo||'')).toLowerCase().indexOf(q)>=0?0:1;
      return aTitle-bTitle;
    });
    if(!matched.length){
      feed.innerHTML='<div style="text-align:center;padding:50px 0"><div style="font-size:15px;color:rgba(180,200,190,.50);font-family:Jost,sans-serif;line-height:1.5">Sin resultados para ese filtro.</div></div>';
      return;
    }
    feed.innerHTML=matched.map(function(p,i){ return _btCard(p,i,uid); }).join('');
  } else {
    _btRenderFeed(_btCurrentTab);
  }
}

function pInitBitacora(){
  _initSupabase();
  if(sbClient && !_btRtCh){
    _btRtCh = _sbSub('velo:bitacora','bitacora_posts',function(){ _btLoadTab(_btCurrentTab,true); });
  }
  // Load globally-hidden post IDs (reported but not yet resolved)
  if(sbClient){
    sbClient.from('bitacora_reports').select('post_id').not('post_id','is',null)
      .then(function(res){
        if(res.data) res.data.forEach(function(r){ if(r.post_id) _btHiddenIds.add(String(r.post_id)); });
      }).catch(function(){});
  }
  _btRenderShell();
  _btSwitchTab('apoyo');
}

